-- pt-BR texts of the Chaos overlay modules (client/MANIFEST.md "Localization"): English key -> Brazilian Portuguese.
-- The key is the exact text a module gives tr() (a string.format pattern when it has arguments: the translation keeps
-- its % conversions in the same order). Values are UTF-8 here; locale_core.lua turns them into cp1252, the encoding
-- the client's fonts draw. Proper names of classes, spells, items, bosses, orbs, systems and the top menu stay in
-- English, as in the wiki's pt-BR guides. tools/ci/check_locales.py checks that every tr() key has an entry here.
-- New texts: add them here (python3 -I tools/ci/check_locales.py --missing prints the lines to fill in).
ChaosLocaleStrings = ChaosLocaleStrings or {}
