  ["King of The Hill\n\nFight with your guild to obtain control of the castle and earn its rewards. The event is held twice a day and alternates between two modes:\n\n- Balanced Mode\nAll players enter with the same HP, damage and attributes. Equipment, soul scrolls, skill tree and prestige have no effect.\n\n- No Limits Mode\nEach player enters with their real HP, damage, equipment, soul scrolls, skill tree, prestige and summons. Anything goes - the strongest wins."] = "King of The Hill\n\nLute com sua guild para tomar o castelo e ganhar as recompensas dele. O evento acontece duas vezes por dia e alterna entre dois modos:\n\n- Modo equilibrado\nTodos entram com a mesma vida, o mesmo dano e os mesmos atributos. Equipamento, soul scrolls, árvore de habilidades e prestígio não têm efeito.\n\n- Modo sem limites\nCada jogador entra com a vida, o dano, o equipamento, os soul scrolls, a árvore de habilidades, o prestígio e as invocações reais. Vale tudo: o mais forte vence.",
