  ["You have no backpack to put it in."] = "Você não tem mochila para guardar.",
  ["That item is gone."] = "Esse item sumiu.",
  -- game_groundlabels/groundlabels.otui
  ["Names over the items on the ground, in their rarity colour, by the rules of your loot filter. Click a label to pick the item up, right click for its menu."] = "Nomes sobre os itens no chão, na cor da raridade, pelas regras do seu filtro de loot. Clique em um rótulo para pegar o item, botão direito para o menu.",
  ["Show ground labels"] = "Mostrar rótulos no chão",
  ["Always label Magic+ items (else only what glows)"] = "Sempre rotular itens de raridade Mágica+ (senão só o que brilha)",
  ["Magic and better gear, uniques, orbs and legendary powers get a label even when the filter does not make them glow. Items the filter dims never do."] = "Equipamento Mágico ou melhor, únicos, orbes e poderes lendários ganham um rótulo mesmo quando o filtro não os faz brilhar. Itens que o filtro escurece nunca ganham.",
  ["Hold Alt to label everything"] = "Segure Alt para rotular tudo",
  ["While Alt is held every item on the ground gets a label, the ones the filter dims too (faded)."] = "Enquanto Alt estiver apertado, todo item no chão ganha rótulo, inclusive os que o filtro apaga (esmaecidos).",
  ["Label corpses that hold loot for you"] = "Rotular corpos com loot para você",
  ["\"Corpse: 2 items\" over a corpse you may loot when it holds items your filter makes glow. Click it to open the corpse."] = "\"Corpo: 2 itens\" sobre um corpo que você pode lootear quando ele tem itens que seu filtro faz brilhar. Clique para abrir o corpo.",
  ["Show despawn timers"] = "Mostrar tempo até sumir",
  ["Time until a corpse (with its loot) or a decaying item is gone. Items lying on the floor do not vanish on their own."] = "Tempo até um corpo (com o loot) ou um item que se desfaz sumir. Itens largados no chão não somem sozinhos.",
  ["Label size"] = "Tamanho do rótulo",
  ["Saved on this computer."] = "Salvo neste computador.",
