  -- game_pvpzone/pvpzone.lua
  ["Open PvP, risk and reward"] = "PvP aberto, risco e recompensa",
  ["Level %d+. Everyone in the Marches can attack you, whatever the world's rules. Nobody dies: a defeat throws you out and drops the embers you carry; your killer may take them. Bank them by standing %ds in a safe exit circle. Monsters have x%.1f health, x%.2f damage and give x%.1f experience and x%.1f loot. No equipment or experience is ever lost here."] = "Nível %d+. Todos nas Marches podem atacar você, sejam quais forem as regras do mundo. Ninguém morre: uma derrota joga você para fora e derruba as brasas que você carrega; quem te derrotou pode pegá-las. Guarde-as ficando %ds em um círculo de saída seguro. Os monstros têm x%.1f de vida, x%.2f de dano e dão x%.1f de experiência e x%.1f de loot. Nenhum equipamento nem experiência se perde aqui.",
  ["Hardcore: a defeat here may end your Hardcore run."] = "Hardcore: uma derrota aqui pode encerrar sua corrida Hardcore.",
  ["Hardcore characters cannot enter the Marches: a Hardcore life is not staked in open PvP."] = "Personagens Hardcore não podem entrar nas Marches: uma vida Hardcore não é apostada em PvP aberto.",
  ["The Cinder Shrine"] = "The Cinder Shrine",
  ["Every %s the Shrine Warden rises. Slay it, then hold the circle with your faction: the holder's faction gets +%d%% experience and +%d%% loot everywhere for %d minutes."] = "A cada %s o Shrine Warden surge. Mate-o e segure o círculo com sua facção: a facção que segura ganha +%d%% de experiência e +%d%% de loot em todo lugar por %d minutos.",
  ["Your pledge"] = "Seu juramento",
  ["Defeating a player pledged to another faction gives %d reputation (the sworn rival full, the others half), at most %d a day (today %d). Unpledged players earn no reputation and cannot take the shrine."] = "Derrotar um jogador jurado a outra facção dá %d de reputação (o rival jurado inteiro, os outros metade), no máximo %d por dia (hoje %d). Jogadores sem juramento não ganham reputação e não podem tomar o santuário.",
  ["Embers vendor"] = "Vendedor de brasas",
  ["Banked: %s embers   Carried: %s / %s"] = "Guardadas: %s brasas   Carregadas: %s / %s",
  ["Record"] = "Recorde",
  -- game_pvpzone/pvpzone.otui
  ["The Scorched Marches"] = "The Scorched Marches",
  ["Enter the Scorched Marches?"] = "Entrar nas Scorched Marches?",
  ["Hardcore: I accept that a defeat here may end my Hardcore run."] = "Hardcore: aceito que uma derrota aqui pode encerrar minha corrida Hardcore.",
  ["I understand: open PvP, and my carried embers can be lost."] = "Eu entendo: PvP aberto, e as brasas que carrego podem ser perdidas.",
