  ["Pledge to a faction in this window, outside the zone. Pledged players earn reputation and can take the shrine."] = "Faça o juramento a uma facção nesta janela, fora da zona. Jogadores com juramento ganham reputação e podem tomar o santuário.",
  ["Enter from a protection zone. Kill monsters and rival players: every kill gives embers, which you carry (at most %s)."] = "Entre a partir de uma zona de proteção. Mate monstros e jogadores rivais: cada abate dá brasas, que você carrega (no máximo %s).",
  ["Carried embers are at risk. If you are defeated you drop them all and your killer may take up to %s. Equipment and experience are never lost."] = "As brasas carregadas correm risco. Se você for derrotado, derruba todas e quem te derrotou pode pegar até %s. Equipamento e experiência nunca se perdem.",
  ["Bank them: stand %ds in a white safe-exit circle without fighting (the circles are marked on your map). Banked embers are safe and buy orbs, potions and cosmetics from the vendor below."] = "Guarde-as: fique %ds em um círculo branco de saída segura sem lutar (os círculos estão marcados no seu mapa). Brasas guardadas ficam seguras e compram orbs, poções e cosméticos no vendedor abaixo.",
  ["%d tiles north"] = "%d sqm ao norte",
  ["%d tiles north-east"] = "%d sqm a nordeste",
  ["%d tiles east"] = "%d sqm a leste",
