  ["%d tiles west"] = "%d sqm a oeste",
  ["%d tiles north-west"] = "%d sqm a noroeste",
  ["you are here"] = "você está aqui",
  ["Leaving... hold still, do not fight. Your %s embers are banked when the bar is full."] = "Saindo... fique parado e não lute. Suas %s brasas são guardadas quando a barra encher.",
  ["Embers carried: %s. Bank them at the nearest safe exit (%s, marked on your map) before you are defeated."] = "Brasas carregadas: %s. Guarde-as na saída segura mais próxima (%s, marcada no seu mapa) antes de ser derrotado.",
  ["Embers carried: %s. Bank them at a safe exit (marked on your map) before you are defeated."] = "Brasas carregadas: %s. Guarde-as em uma saída segura (marcada no seu mapa) antes de ser derrotado.",
  ["Goal: kill monsters and rival players for embers, then bank them at a safe exit (marked on your map)."] = "Objetivo: mate monstros e jogadores rivais por brasas e depois guarde-as em uma saída segura (marcada no seu mapa).",
  ["Shrine event: slay the Shrine Warden at the shrine (%s, marked on your map)."] = "Evento do santuário: derrote o Shrine Warden no santuário (%s, marcado no seu mapa).",
  ["Shrine event: slay the Shrine Warden at the shrine (marked on your map)."] = "Evento do santuário: derrote o Shrine Warden no santuário (marcado no seu mapa).",
  ["Shrine event: stand in the shrine circle with your faction to take it (%s, marked on your map)."] = "Evento do santuário: fique no círculo do santuário com a sua facção para tomá-lo (%s, marcado no seu mapa).",
  ["Shrine event: stand in the shrine circle with your faction to take it (marked on your map)."] = "Evento do santuário: fique no círculo do santuário com a sua facção para tomá-lo (marcado no seu mapa).",
