  -- game_chronicle, game_nemesis
  ["%d chapters recorded"] = "%d capítulos registrados",
  ["Chapters"] = "Capítulos",
  ["Chronicle"] = "Crônica",
  ["Each season the whole realm writes a story together: world bosses, rifts, Omens, the Sepulchre and new heroes fill its chapters, and every written chapter changes the world."] = "A cada temporada o reino inteiro escreve uma história junto: chefes de mundo, rifts, Omens, o Sepulchre e novos heróis preenchem os capítulos, e cada capítulo escrito muda o mundo.",
  ["Goals of the realm"] = "Metas do reino",
  ["Memorial"] = "Memorial",
  ["Nemesis"] = "Nêmesis",
  ["No Chronicle is being written now. It begins with the next season."] = "Nenhuma crônica está sendo escrita agora. Ela começa na próxima temporada.",
  ["No realm first this season yet."] = "Nenhum primeiro do reino nesta temporada ainda.",
  ["No record this season yet."] = "Nenhum recorde nesta temporada ainda.",
  ["No season has been closed yet. When one ends, the Chronicler writes down who carried each chapter."] = "Nenhuma temporada foi encerrada ainda. Quando uma acabar, a Cronista anota quem carregou cada capítulo.",
  ["Nobody is remembered here this season."] = "Ninguém é lembrado aqui nesta temporada.",
  ["Nobody recorded."] = "Ninguém registrado.",
  ["Nobody yet. The realm writes this chapter together."] = "Ninguém ainda. O reino escreve este capítulo junto.",
  ["Realm firsts"] = "Primeiros do reino",
  ["Records and realm firsts are shown unless you turn them off; a fall is shown only after your yes."] = "Recordes e primeiros do reino aparecem a menos que você os desligue; uma queda só aparece depois do seu sim.",
  ["Saving your choice..."] = "Salvando sua escolha...",
  ["Show me on the Memorial"] = "Mostrar meu nome no Memorial",
  ["Show my Hardcore fall (name, level, class, cause and date)"] = "Mostrar minha queda no Hardcore (nome, nível, classe, causa e data)",
  ["Show my records and realm firsts"] = "Mostrar meus recordes e primeiros do reino",
  ["The Ashen Chronicle"] = "The Ashen Chronicle",
  ["The Ember Memorial in the capital keeps the realm firsts, the season records and the fallen of Hardcore. It shows your name only if you want it to; you can change your mind at any time."] = "O Ember Memorial na capital guarda os primeiros do reino, os recordes da temporada e os caídos do Hardcore. Ele só mostra seu nome se você quiser; você pode mudar de ideia quando quiser.",
  ["The Ember Memorial, %s"] = "O Ember Memorial, %s",
  ["The end of the book"] = "O fim do livro",
  ["The fallen"] = "Os caídos",
  ["The monster that hunts you"] = "O monstro que caça você",
  ["The record"] = "O registro",
  ["This page is still blank. The chapters before it must be written first."] = "Esta página ainda está em branco. Os capítulos antes dela precisam ser escritos primeiro.",
  ["Traits"] = "Traços",
  ["What changed"] = "O que mudou",
  ["Who carried each chapter of the past seasons"] = "Quem carregou cada capítulo das temporadas passadas",
  ["Who carried it"] = "Quem carregou",
  ["Your character fell in Hardcore. Should the Memorial remember it? Tick the box above and save, or save it unticked."] = "Seu personagem caiu no Hardcore. O Memorial deve lembrar disso? Marque a caixa acima e salve, ou salve sem marcar.",
  ["Your part in this chapter: %s points."] = "Sua parte neste capítulo: %s pontos.",
  -- base client_background (the login screen's panels; labels and counts through tr() by base patch 0054)
  ["Active"] = "Em andamento",
