  ["Add to my rules"] = "Somar às minhas regras",
  ["Replace"] = "Substituir",
  ["This preset has your own rules.\nAdd the class spells below them, or replace them?\n(Undo puts the list back.)"] = "Este preset tem suas próprias regras.\nSomar as magias da classe abaixo delas, ou substituí-las?\n(Desfazer devolve a lista.)",
  ["Put back the spell rules as they were before the last Auto rotation"] = "Devolve as regras de magia como estavam antes da última Auto rotation",
  ["New spell available"] = "Nova magia disponível",
  ["New spell available: %s.\nAdd to rotation?"] = "Nova magia disponível: %s.\nAdicionar à rotação?",
  ["Ignore"] = "Ignorar",
  ["Auto-update my spells"] = "Atualizar minhas magias sozinho",
  ["Auto turn"] = "Virar sozinho",
  ["Class changed: %d spell(s) of your old class were taken out of the Helper. Press Auto rotation for your new class."] = "Classe trocada: %d magia(s) da sua classe antiga saíram do Helper. Use o Auto rotation para a nova classe.",
  ["Turn toward the target before a wave or beam spell, so it hits in front of the target.\nWithout a target the character faces the side with most monsters."] = "Vira para o alvo antes de uma magia de onda ou raio, para ela acertar na frente do alvo.\nSem alvo, o personagem vira para o lado com mais monstros.",
  ["Auto-update"] = "Atualizar sozinho",
  ["Auto setup"] = "Configuração automática",
  ["Set up your helper in one click"] = "Configure seu helper com um clique",
  ["Auto setup done for %s, level %d."] = "Configuração automática feita para %s, nível %d.",
  ["Auto setup has no recommendations for this class."] = "A configuração automática não tem recomendações para esta classe.",
  ["Healing: %d spells, %d potions."] = "Cura: %d magias, %d poções.",
  ["Nothing to undo."] = "Nada para desfazer.",
  ["Set up healing, tools, shooter, timers and support spells for your class and level in one click\n(only spells you can cast and potions you may drink). Right-click: undo the last Auto setup."] = "Configura cura, ferramentas, ataque, timers e magias de suporte para sua classe e nível em um clique\n(só magias que você pode usar e poções que pode beber). Clique direito: desfaz a última configuração automática.",
  ["Shooter: %d attack spells."] = "Ataque: %d magias de ataque.",
  ["Shooter: no attack spell at this level yet."] = "Ataque: ainda nenhuma magia de ataque neste nível.",
  ["Timers: %d buffs."] = "Timers: %d buffs.",
