  ["Alarm when count lower than:"] = "Alarme quando a quantidade for menor que:",
  ["Alert In Protect Zone"] = "Alertar em PZ",
  ["Condition Settings"] = "Ajustes da condição",
  ["Cast If Trapped"] = "Usar se preso",
  ["Only cast this spell/rune if you cannot walk in any direction."] = "Só usa esta magia/runa se você não puder andar em nenhuma direção.",
  ["Cast If Count Lower Than"] = "Usar se a contagem for menor",
  ["Cast only if the creature count is equal to or lower than the threshold.\nExample: Creatures = 8 will cast if count is between 1 and 8."] = "Usa só se a quantidade de criaturas for igual ou menor que o limite.\nExemplo: Criaturas = 8 usa se houver de 1 a 8.",
  ["Cast On Foot"] = "Usar em si",
  ["Cast spell at your own position instead of at the target."] = "Usa a magia na sua posição em vez de no alvo.",
  ["Extended Area"] = "Área ampliada",
  ["If your WOD has enlarged the area of the Spell.\nUse the extended area version of this spell."] = "Se a área da magia foi ampliada.\nUsa a versão de área ampliada desta magia.",
  ["Extended Area 2"] = "Área ampliada 2",
  ["If your WOD has enlarged the area of the Spell to level 2.\nUse the extended area level 2 version of this spell."] = "Se a área da magia foi ampliada ao nível 2.\nUsa a versão de área ampliada nível 2 desta magia.",
  ["Force Spell On Target"] = "Forçar magia no alvo",
  ["Cast the spell directly towards the target\ninstead of calculating the best direction\nfor maximum creatures hit."] = "Usa a magia direto na direção do alvo\nem vez de calcular a melhor direção\npara acertar mais criaturas.",
  ["TARGETING & SPELL RULES"] = "ALVOS E REGRAS DE MAGIA",
  ["ACTION"] = "AÇÃO",
  ["Click to select a Rune"] = "Clique para escolher uma runa",
  ["(select spell or rune)"] = "(escolha magia ou runa)",
  ["MONSTERS"] = "MONSTROS",
  ["Conditions checked against monsters around your character."] = "Condições verificadas nos monstros em volta do personagem.",
  ["COUNT"] = "QTD.",
  ["Monster threshold: N+ means at least N; N- means at most N."] = "Limite de monstros: N+ significa pelo menos N; N- significa no máximo N.",
  ["Choose N+ to cast with at least N monsters, or N- to cast with at most N (for example, 5- means no more than 5)."] = "Escolha N+ para usar com pelo menos N monstros, ou N- para usar com no máximo N (por exemplo, 5- significa até 5).",
  ["Monster HP lower limit. Example: 20 means monsters at 20%% HP or above. Set 0 to ignore."] = "Limite inferior de vida do monstro. Exemplo: 20 significa monstros com 20%% de vida ou mais. Use 0 para ignorar.",
  ["HP MIN %%"] = "VIDA MÍN %%",
  ["Minimum MONSTER health percentage."] = "Vida mínima do MONSTRO, em porcentagem.",
  ["Monster HP upper limit. Example: 50 means monsters at 50%% HP or below. Set 0 to ignore."] = "Limite superior de vida do monstro. Exemplo: 50 significa monstros com 50%% de vida ou menos. Use 0 para ignorar.",
  ["HP MAX %%"] = "VIDA MÁX %%",
  ["Maximum MONSTER health percentage."] = "Vida máxima do MONSTRO, em porcentagem.",
  ["PLAYER"] = "JOGADOR",
  ["Minimum character resources required before this rule can cast."] = "Recursos mínimos do personagem para esta regra ser usada.",
  ["Your minimum mana percentage required to cast. Set 0 to ignore."] = "Sua porcentagem mínima de mana para usar. Use 0 para ignorar.",
  ["MANA MIN"] = "MANA MÍN",
  ["Your minimum health percentage required to cast. Set 0 to ignore."] = "Sua porcentagem mínima de vida para usar. Use 0 para ignorar.",
  ["HP MIN"] = "VIDA MÍN",
  ["HARMONY"] = "HARMONIA",
  ["DELAY MS"] = "ATRASO MS",
  ["Additional delay after using this rule, in milliseconds."] = "Atraso extra depois de usar esta regra, em milissegundos.",
  ["Monster names to count for this spell (comma-separated). Only these monsters will be counted for the creature threshold."] = "Nomes de monstros contados para esta magia (separados por vírgula). Só esses monstros contam para o limite de criaturas.",
  ["TARGET MONSTERS"] = "MONSTROS ALVO",
  ["* (all monsters)"] = "* (todos os monstros)",
  ["Which monsters to attack.\n*  = every monster\nOr a list of names separated by comma: dragon, dragon lord\nThe bot sticks to one monster until it dies, then picks the next."] = "Quais monstros atacar.\n*  = qualquer monstro\nOu uma lista de nomes separados por vírgula: dragon, dragon lord\nO bot fica num monstro até ele morrer, depois escolhe o próximo.",
  ["Advanced +"] = "Avançado +",
  ["Show the advanced targeting options (mode, ignore list, priority list)."] = "Mostra as opções avançadas de alvo (modo, lista de ignorados, lista de prioridade).",
  ["Ignore Monster List"] = "Lista de monstros ignorados",
  ["Monsters to ignore (separated by comma). Affects Auto Target and Magic Shooter. Numbers are not allowed."] = "Monstros a ignorar (separados por vírgula). Vale para Auto Target e Magic Shooter. Números não são permitidos.",
  ["My Priority List In Order (Only in Mode \"J\")"] = "Minha lista de prioridade em ordem (só no modo \"J\")",
  ["Priority targets in order (separated by comma). First monster has highest priority."] = "Alvos prioritários em ordem (separados por vírgula). O primeiro monstro tem a maior prioridade.",
  ["Mode A = Prioritizes the closest target\nMode B = Prioritizes the farthest target\nMode C = Prioritizes target with the lowest health\nMode D = Prioritizes target with the highest health\nMode E = Prioritizes the best target to throw runes or diamond arrow for paladins\nMode F = Attacks the closest target, prioritizing lowest health\nMode G = Prioritizes the closest target with highest health\nMode H = Prioritizes the farthest target with lowest health\nMode I = Prioritizes the farthest target with highest health\nMode J = Prioritizes targets from your priority list in order"] = "Modo A = Prioriza o alvo mais perto\nModo B = Prioriza o alvo mais longe\nModo C = Prioriza o alvo com menos vida\nModo D = Prioriza o alvo com mais vida\nModo E = Prioriza o melhor alvo para runas ou flechas de área\nModo F = Ataca o alvo mais perto, priorizando o de menos vida\nModo G = Prioriza o alvo mais perto com mais vida\nModo H = Prioriza o alvo mais longe com menos vida\nModo I = Prioriza o alvo mais longe com mais vida\nModo J = Prioriza os alvos da sua lista de prioridade, em ordem",
  ["Always Chase Opponent"] = "Sempre perseguir",
  ["Keeps Chase Opponent enabled while this option is checked."] = "Mantém Perseguir oponente ligado enquanto esta opção estiver marcada.",
  ["Priority targets"] = "Alvos prioritários",
  ["Loot goblins first, then bosses, then special monsters (magic, rare and legendary), before the nearest normal monster.\nOff: only the mode below decides. Not used in mode J."] = "Primeiro os goblins de tesouro, depois os chefes, depois os monstros especiais (mágicos, raros e lendários), antes do monstro normal mais próximo.\nDesligado: só o modo abaixo decide. Não vale no modo J.",
  ["Only reachable"] = "Só alcançáveis",
  ["Auto Target only picks monsters it can get to: a walkable way for melee, a clear line of sight for the ranged classes.\nOff: any monster in reach, even behind a wall or across water."] = "O Auto Target só escolhe monstros que consegue alcançar: um caminho livre para corpo a corpo, linha de visão limpa para as classes à distância.\nDesligado: qualquer monstro no alcance, mesmo atrás de parede ou do outro lado da água.",
  ["Follow Friend"] = "Seguir amigo",
  ["Keeps walking after the named player and re-follows whenever the server drops it.\nSpells and healing keep working while following.\nAuto Target is held while this is on: attacking and following cannot both be active."] = "Continua andando atrás do jogador escolhido e volta a seguir sempre que o servidor solta.\nMagias e cura continuam funcionando enquanto segue.\nAuto Target fica parado enquanto isto está ligado: atacar e seguir não podem ficar ativos juntos.",
  ["character name"] = "nome do personagem",
  ["Exact name of the player to follow."] = "Nome exato do jogador a seguir.",
  ["Enable Shooter"] = "Ativar Shooter",
  ["Disable in Protect Zone"] = "Desligar em zona de proteção",
  ["If enabled, it will disable both \"Auto Target\" and \"Magic Shooter\" when entering a Protection Zone."] = "Se ativado, desliga \"Auto Target\" e \"Magic Shooter\" ao entrar numa zona de proteção.",
