  ["All character saves"] = "Dados de todos os personagens",
  ["Per-character bot settings, custom scripts and alarms."] = "Ajustes do bot, scripts próprios e alarmes de cada personagem.",
  ["%d characters   /   %d settings files"] = "%d personagens   /   %d arquivos de ajustes",
  ["No saved character settings found."] = "Nenhum ajuste de personagem salvo.",
  ["Auto Target disabled (Protection Zone)."] = "Auto Target desligado (zona de proteção).",
  ["Magic Shooter disabled (Protection Zone)."] = "Magic Shooter desligado (zona de proteção).",
  ["Uses a healing or mana potion when your health or\nmana reaches the defined percentage."] = "Usa uma poção de vida ou de mana quando sua vida ou\nmana chega à porcentagem definida.",
  ["Uses a healing or mana potion when your health or\nmana reaches the defined percentage.\nClick on this button to change the potion priority:\n  - Icon: Blue (Mana Priority)\n  - Icon: Red  (Health Priority)"] = "Usa uma poção de vida ou de mana quando sua vida ou\nmana chega à porcentagem definida.\nClique neste botão para trocar a prioridade da poção:\n  - Ícone azul (prioridade de mana)\n  - Ícone vermelho (prioridade de vida)",
  ["Assign Haste Spell"] = "Escolher magia de pressa",
  ["Assign Training Spell"] = "Escolher magia de treino",
  ["Level: %d"] = "Nível: %d",
  ["Your vocation can not use this rune."] = "Sua vocação não pode usar esta runa.",
  ["Invalid rune!"] = "Runa inválida!",
  ["Select Attack Spell"] = "Escolher magia de ataque",
  ["Invalid potion!"] = "Poção inválida!",
  ["This potion is healing mana..."] = "Esta poção cura mana...",
  ["This potion is healing health..."] = "Esta poção cura vida...",
  ["No potion selected"] = "Nenhuma poção escolhida",
  ["Edit Rune"] = "Editar runa",
  ["Assign Rune"] = "Escolher runa",
