  ["Edit Training Spell"] = "Editar magia de treino",
  ["Edit Haste Spell"] = "Editar magia de pressa",
  ["Select exercise weapon"] = "Escolher arma de exercício",
  ["Uses a healing or mana potion when your health or\nmana reaches the defined percentage.\nPaladins can click on this button to change the potion priority:\n  - Icon: Blue (Mana Priority)\n  - Icon: Red  (Health Priority)"] = "Usa uma poção de vida ou de mana quando sua vida ou\nmana chega à porcentagem definida.\nPaladinos podem clicar neste botão para trocar a prioridade da poção:\n  - Ícone azul (prioridade de mana)\n  - Ícone vermelho (prioridade de vida)",
  ["Helper configuration saved successfully!"] = "Configuração do Helper salva!",
  ["Could not save Helper configuration."] = "Não foi possível salvar a configuração do Helper.",
  ["%s\nRight click to change or remove"] = "%s\nBotão direito para trocar ou tirar",
  ["Right click to assign an item"] = "Botão direito para escolher um item",
  ["Change Item"] = "Trocar item",
  ["Assign Item"] = "Escolher item",
  ["Helper toggled + Config LOADED!"] = "Helper alternado e configuração CARREGADA!",
  ["Helper: %s"] = "Helper: %s",
  ["Enabled"] = "Ligado",
  ["Disabled"] = "Desligado",
  ["Enabled - Click to DISABLE auto functions OR LOAD config"] = "Ligado - Clique para DESLIGAR as funções automáticas OU CARREGAR a configuração",
  ["Disabled - Click to ENABLE auto functions OR LOAD config"] = "Desligado - Clique para LIGAR as funções automáticas OU CARREGAR a configuração",
  ["Config not available."] = "Configuração indisponível.",
  ["There is already a preset with this name."] = "Já existe um preset com este nome.",
  ["The name cannot be empty."] = "O nome não pode ficar vazio.",
  ["The name cannot be longer than 20 characters."] = "O nome não pode ter mais de 20 caracteres.",
  ["%s profile changed to %s."] = "Preset de %s trocado para %s.",
  ["You can't delete your only preset."] = "Você não pode apagar seu único preset.",
  ["Preset %s deleted."] = "Preset %s apagado.",
  ["Delete Preset"] = "Apagar preset",
  ["Are you sure you want to delete preset %s?"] = "Tem certeza de que quer apagar o preset %s?",
  ["Rename %s preset"] = "Renomear preset de %s",
  ["Add %s preset"] = "Adicionar preset de %s",
