  ["Enable/Disable Helper"] = "Ligar/desligar o Helper",
  ["Enable/Disable Auto Target"] = "Ligar/desligar Auto Target",
  ["Enable/Disable Magic Shooter"] = "Ligar/desligar Magic Shooter",
  ["Enable/Disable Target and Magic Shooter"] = "Ligar/desligar Target e Magic Shooter",
  ["Change Shooter Preset"] = "Trocar preset do Shooter",
  ["Change Equipment Preset"] = "Trocar preset de equipamento",
