  ["Ranged Monster Names:"] = "Nomes de monstros à distância:",
  ["Rules:"] = "Regras:",
  ["Parameter:"] = "Parâmetro:",
  ["Targeting: every monster, Auto Target and Magic Shooter on."] = "Alvo: todos os monstros, Auto Target e Magic Shooter ligados.",
  -- game_helpersupport: the helper's Support spells tab (owner 2026-10-18)
  ["(empty)"] = "(vazio)",
  ["A support spell is only cast when this share of your maximum mana is left after it,\nso healing and attack spells keep their mana."] = "Uma magia de suporte só é usada se sobrar esta parte da sua mana máxima depois dela,\npara que as magias de cura e de ataque tenham mana.",
  ["Add the support spells of your class and level that are not in the list yet."] = "Adiciona à lista as magias de suporte da sua classe e nível que ainda não estão nela.",
  ["Cast support spells automatically"] = "Usar magias de suporte automaticamente",
  ["Cast this spell"] = "Usar esta magia",
  ["Clear list"] = "Limpar lista",
  ["Fill for my class"] = "Preencher para minha classe",
  ["Keep this much mana:"] = "Manter esta mana:",
  ["Spells the helper casts by itself as soon as they are off cooldown, from the top row down: shields, summons, vigils, buffs. A buff is not cast again while it is on (the Buff Bar tells). Nothing is cast in a protection zone."] = "Magias que o helper usa sozinho assim que o tempo de recarga acaba, da linha de cima para baixo: escudos, invocações, vigílias, buffs. Um buff não é usado de novo enquanto está ativo (a Barra de Buffs informa). Nada é usado em zona de proteção.",
  ["Support spells"] = "Magias de suporte",
  ["Support spells: %d."] = "Magias de suporte: %d.",
  ["Support spells: the helper casts them by itself when they are off cooldown"] = "Magias de suporte: o helper as usa sozinho quando o tempo de recarga acaba",
  ["The Buff Bar is off: buffs are timed by their duration, vigils are not cast."] = "A Barra de Buffs está desligada: os buffs são contados pela duração e as vigílias não são usadas.",
  ["The list is empty. Pick spells in the rows, or press Fill for my class."] = "A lista está vazia. Escolha magias nas linhas ou use Preencher para minha classe.",
  ["Tools: eat food, haste %s."] = "Ferramentas: comer, haste %s.",
  ["Tools: eat food."] = "Ferramentas: comer.",
  ["You have your own settings in: %s.\nAdd the recommended ones to yours, or replace yours?\n(Undo puts everything back.)"] = "Você tem configurações próprias em: %s.\nAdicionar as recomendadas às suas, ou substituir as suas?\n(Desfazer volta tudo como estava.)",
  ["After a level-up, update a rotation that Auto rotation wrote with the new spells.\nOff: a new spell is only offered (Add / Ignore). Your own rules are never changed."] = "Depois de subir de nível, atualiza com as novas magias uma rotação escrita pela Auto rotation.\nDesligado: uma magia nova só é oferecida (Adicionar / Ignorar). Suas próprias regras nunca mudam.",
  -- base patch 0056: Options menu, Graphics, modal dialog, helper (base windows read this table first)
  ["Controls"] = "Controles",
  ["General Hotkeys"] = "Atalhos gerais",
  ["Action Bar Hotkeys"] = "Atalhos da barra",
  ["Custom Hotkeys"] = "Atalhos próprios",
  ["Interface"] = "Interface",
  ["HUD"] = "HUD",
  ["Console"] = "Console",
  ["Game Window"] = "Janela do jogo",
  ["Action Bars"] = "Barras de ação",
  ["Control Buttons"] = "Botões laterais",
  ["Graphics"] = "Gráficos",
  ["Effects"] = "Efeitos",
  ["Misc."] = "Diversos",
  ["Gameplay"] = "Jogabilidade",
  ["Screenshot"] = "Captura",
  ["Medium"] = "Média",
  ["Orb size"] = "Tamanho dos orbes",
  ["Size of the health and mana orbs"] = "Tamanho dos orbes de vida e mana",
  ["This client draws with OpenGL."] = "Este cliente desenha com OpenGL.",
  ["Rarity outline on dropped items"] = "Contorno de raridade nos itens no chão",
  ["Rarity outline in bags and inventory"] = "Contorno de raridade nas bolsas e no inventário",
  ["Shine on legendary and unique frames"] = "Brilho nas molduras lendárias e únicas",
  ["Liquid health and mana orbs"] = "Orbes líquidos de vida e mana",
  ["Flash creatures that take damage"] = "Piscar criaturas que levam dano",
  ["Shake the screen on big hits taken"] = "Tremer a tela em golpes fortes recebidos",
  ["Soft shadow under creatures"] = "Sombra suave sob as criaturas",
  ["Light the ground around spell effects"] = "Iluminar o chão ao redor dos efeitos de magia",
  ["A spell effect lights the ground around it for a moment in its colour, so spells glow\nin caves and at night. It adds nothing in full daylight and needs Show light effects."] = "Um efeito de magia ilumina o chão ao redor por um instante, na sua cor, e as magias brilham\nem cavernas e à noite. Não muda nada em plena luz do dia e precisa de Mostrar efeitos de luz.",
  ["Living water and lava"] = "Água e lava vivas",
  ["Water and lava ground ripple and shimmer a little. The colours stay the same;\nit costs a little on a weak computer."] = "O chão de água e de lava ondula e cintila um pouco. As cores continuam as mesmas;\npesa um pouco num computador fraco.",
  ["Rain and weather"] = "Chuva e clima",
  ["When the server says it rains, rain falls over the game window. It is drawn by your\ncomputer, only outdoors, and costs very little; turn it off if you do not want it."] = "Quando o servidor diz que está chovendo, a chuva cai sobre a janela do jogo. Ela é desenhada\npelo seu computador, só ao ar livre, e pesa muito pouco; desligue se não quiser.",
  ["Vignette and colour grade"] = "Vinheta e correção de cor",
  ["Soft glow"] = "Brilho suave",
  ["A soft halo around very bright light: spell effects, missiles, fire and lava. Only what is\nalready bright glows; the colours of the ground and the biome stay as they are. It costs a\nlittle on a weak computer and is off until you turn it on."] = "Um halo suave ao redor de luz muito forte: efeitos de magia, projéteis, fogo e lava. Só brilha\no que já é forte; as cores do chão e do bioma continuam as mesmas. Pesa um pouco num\ncomputador fraco e fica desligado até você ligar.",
  ["Soft damage numbers"] = "Números de dano suaves",
  ["Damage and healing numbers pop up a little, rise quickly and slow down, fade out smoothly and\nspread sideways so that several hits do not sit on top of each other. Turn it off for the plain\nstraight rise."] = "Os números de dano e cura surgem com um pequeno pulo, sobem rápido e desaceleram, somem\naos poucos e se espalham para os lados, para que vários golpes não fiquem uns sobre os outros.\nDesligue para a subida reta de sempre.",
  ["Target and follow outline"] = "Contorno do alvo e de quem você segue",
  ["A soft red outline with a gentle pulse around the creature you attack and a green one around\nthe creature you follow, so you see your target in a crowd. The stock square stays."] = "Um contorno vermelho suave, com um leve pulsar, em volta da criatura que você ataca e um verde\nem volta da que você segue, para achar o alvo no meio da multidão. O quadrado padrão continua.",
  ["Outline under the mouse"] = "Contorno sob o mouse",
  ["A faint white outline around the creature under the mouse, so you see what a click will hit."] = "Um contorno branco discreto em volta da criatura sob o mouse, para ver o que um clique vai atingir.",
  ["Fade on floor change"] = "Transição ao mudar de andar",
  ["A short fade from black when you take stairs, fall through a hole or are teleported, so the\nnew place does not appear in one hard cut. It lasts under half a second and costs nothing otherwise."] = "Uma transição curta a partir do preto quando você usa escadas, cai em um buraco ou é teletransportado, para o\nnovo lugar não surgir de uma vez, em um corte seco. Dura menos de meio segundo e, fora isso, não custa nada.",
  ["Fade out dying creatures"] = "Criaturas que morrem somem aos poucos",
  ["A creature that dies fades away in about a third of a second instead of vanishing in one frame.\nThe corpse still appears at once and nothing is delayed. It costs almost nothing."] = "Uma criatura que morre some em cerca de um terço de segundo, em vez de desaparecer de uma vez.\nO corpo continua aparecendo na hora e nada é atrasado. Quase não custa nada.",
  ["Fade windows in and out"] = "Janelas aparecem e somem suavemente",
  ["Windows fade in when they open and fade out when they close, in about a tenth of a second.\nClicks and keys work at once and nothing waits for the fade."] = "As janelas surgem aos poucos ao abrir e somem aos poucos ao fechar, em cerca de um décimo de segundo.\nCliques e teclas funcionam na hora e nada espera o efeito.",
  ["Ambient particles"] = "Partículas do ambiente",
  ["Slow embers in burnt places, fireflies in forests and swamps and dust in caves drift over the game window.\nThey are few and cheap, and stop while the window is hidden."] = "Brasas lentas em lugares queimados, vagalumes em florestas e pântanos e poeira nas cavernas flutuam sobre a janela do jogo.\nSão poucas e leves, e param enquanto a janela está escondida.",
  ["Smooth health bars"] = "Barras de vida suaves",
  ["Health and mana bars over creatures and on your own plate move smoothly to a new value in about a seventh of a second.\nWhen you lose health, a pale piece stays for a moment and then slides down. It costs almost nothing."] = "As barras de vida e de mana sobre as criaturas e na sua própria placa se movem com suavidade até o novo valor em cerca de um sétimo de segundo.\nQuando você perde vida, um pedaço claro fica por um instante e depois desce. Quase não custa nada.",
  ["Trails and arcs on missiles"] = "Rastros e arcos nos projéteis",
  ["Arrows, bolts and spell missiles leave a short fading trail, and arrows, bolts, spears and stones\nfly in a slight arc. Spell missiles stay straight. It costs a few extra sprites per missile."] = "Flechas, virotes e projéteis de magia deixam um rastro curto que some, e flechas, virotes, lanças e pedras\nvoam em um leve arco. Projéteis de magia seguem retos. Custa alguns sprites a mais por projétil.",
  ["Stains on the ground"] = "Manchas no chão",
  ["Blood where a creature dies, a scorch mark under fire, frost cracks under ice and a green stain under poison.\nThey fade away in 20 to 30 seconds, at most 24 at a time, and only on the screen. It costs almost nothing."] = "Sangue onde uma criatura morre, uma marca de queimado sob o fogo, rachaduras de gelo sob o gelo e uma mancha verde sob o veneno.\nElas somem em 20 a 30 segundos, no máximo 24 por vez, e só na tela. Quase não pesa.",
  ["Flickering fire light"] = "Luz de fogo tremulante",
  ["Fire, torch and lava light flicker gently, by about a tenth. Only the glow on the map\nchanges, not the pictures. Soft round light edges and soft mixing of overlapping\nlights are always on."] = "A luz de fogo, tochas e lava treme de leve, cerca de um décimo. Só o brilho no mapa\nmuda, não as imagens. Bordas de luz redondas e suaves e a mistura suave de luzes\nsobrepostas ficam sempre ligadas.",
  ["Interface scale: %d%%"] = "Escala da interface: %d%%",
  ["Interface scale: %d%% (this window fits %d%%)"] = "Escala da interface: %d%% (esta janela comporta %d%%)",
  ["Makes the whole interface bigger and sharp on large screens: 100%%, 200%% or 300%%.\nA size is offered only when the window is big enough for it (about 2048x1152 for 200%%,\n3072x1728 for 300%%); on a smaller window it stays at the largest size that fits.\nThe change applies at once and is saved on this computer."] = "Deixa toda a interface maior e nítida em telas grandes: 100%%, 200%% ou 300%%.\nUm tamanho só vale quando a janela é grande o bastante (cerca de 2048x1152 para 200%%,\n3072x1728 para 300%%); numa janela menor fica no maior tamanho que cabe.\nA mudança vale na hora e fica salva neste computador.",
  ["Looks for the game window. A creature that takes damage flashes for a moment, a big hit\nyou take shakes the screen a few pixels, creatures get a soft shadow under their feet and\nthe edges of the picture darken with a light colour grade. Each one can be turned off; the\nshadow and the grade cost a little on a weak computer."] = "Visual da janela do jogo. Uma criatura que leva dano pisca por um instante, um golpe forte\nque você recebe treme a tela alguns pixels, as criaturas ganham uma sombra suave sob os pés e\nas bordas da imagem escurecem com um leve ajuste de cor. Cada um pode ser desligado; a\nsombra e o ajuste de cor pesam um pouco num computador fraco.",
  ["My character save"] = "Dados do meu personagem",
  ["New Preset"] = "Novo preset",
  ["Duplicate"] = "Duplicar",
  ["Set Key"] = "Definir tecla",
  ["Set Key (Target/Shooter)"] = "Definir tecla (Alvo/Atirador)",
  -- base patch 0059: the helper's shortcut and save boxes
  ["Open Helper"] = "Abrir o Helper",
  ["Helper settings"] = "Configurações do Helper",
  ["Helper save data deleted."] = "Dados salvos do Helper apagados.",
  ["Could not delete the helper save data."] = "Não foi possível apagar os dados salvos do Helper.",
  ["Delete Helper Save"] = "Apagar dados do Helper",
  -- game_lookpreview effect stage, game_unlocks (owned and locked lists), game_cosmetics, base patch 0060
  ["Compare with default"] = "Comparar com o padrão",
  ["Play the default effects first, then the ones of this skin"] = "Mostra primeiro os efeitos padrão, depois os deste visual",
  ["Default effects"] = "Efeitos padrão",
  ["With this skin"] = "Com este visual",
  ["Not unlocked yet."] = "Ainda não desbloqueado.",
  ["How to get it: %s"] = "Como obter: %s",
  ["Unlocked."] = "Desbloqueado.",
  ["Only mine"] = "Só os meus",
  ["Show only what you have unlocked"] = "Mostrar só o que você desbloqueou",
  ["The picture beside plays these effects. Preview plays them in the game around your character (only you see them)."] = "A imagem ao lado mostra estes efeitos. Pré-visualizar os mostra no jogo em volta do seu personagem (só você vê).",
  ["You have not unlocked everything you picked."] = "Você não desbloqueou tudo o que escolheu.",
  ["A part of this preset is not unlocked."] = "Uma parte deste preset não está desbloqueada.",
  ["Free; addons: Store"] = "Grátis; addons: Loja",
  -- game_simpleskills (owner debug item 46: one melee skill)
  ["Melee"] = "Corpo a corpo",
  ["Ranged"] = "À distância",
  ["Magic / Wand"] = "Magia / Varinha",
  ["Swords, axes and clubs share one skill: the best of the three."] = "Espadas, machados e clavas usam uma só skill: a melhor das três.",
  -- game_passivetree (auto build, stat help)
  ["%d more nodes of the build need points you do not have yet."] = "Mais %d nós da build precisam de pontos que você ainda não tem.",
  ["%d nodes your class cannot hold are left out."] = "%d nós que sua classe não pode ter ficam de fora.",
  ["Add the nodes of the build you can afford. Takes nothing back."] = "Adiciona os nós da build que você pode pagar. Não devolve nada.",
  ["Apply: adds %d nodes, takes nothing back, free."] = "Aplicar: adiciona %d nós, não devolve nada, grátis.",
  ["Auto build"] = "Build automática",
  ["Build applied."] = "Build aplicada.",
  ["Focus"] = "Foco",
  ["Gold marks a Primary stat of your class, silver a Secondary one."] = "Dourado marca um atributo Principal da sua classe, prata um Secundário.",
  ["Pick a build. The tree shows what it would take."] = "Escolha uma build. A árvore mostra o que ela exigiria.",
  ["Pick a recommended build or a focus theme for your class and apply it"] = "Escolha uma build recomendada ou um tema de foco para a sua classe e aplique",
  ["Primary"] = "Principal",
  ["Recommended"] = "Recomendadas",
  ["Reset and apply"] = "Resetar e aplicar",
  ["Reset and apply: takes back %d nodes and builds this one (%d nodes). Price: %s."] = "Resetar e aplicar: devolve %d nós e monta esta build (%d nós). Preço: %s.",
  ["Reset and apply: your tree already fits this build, nothing is taken back."] = "Resetar e aplicar: sua árvore já cabe nesta build, nada é devolvido.",
  ["Reset your tree and apply %s?\nNodes taken back: %d. Price: %s."] = "Resetar sua árvore e aplicar %s?\nNós devolvidos: %d. Preço: %s.",
  ["Secondary"] = "Secundário",
  ["Stats"] = "Atributos",
  ["Take back your nodes (respec price) and build this one"] = "Devolve seus nós (preço do respec) e monta esta build",
  ["The build could not be applied."] = "Não foi possível aplicar a build.",
  ["The build uses %d points. You own %d and %d are free."] = "A build usa %d pontos. Você tem %d e %d estão livres.",
  ["What every stat of the tree does. Gold marks a Primary stat of your class, silver a Secondary one."] = "O que cada atributo da árvore faz. Dourado marca um atributo Principal da sua classe, prata um Secundário.",
  ["free (a free reset is used)"] = "grátis (um reset grátis é usado)",
  -- game_waystone: the waystone device window
  ["%d held"] = "%d na bolsa",
  ["level %d"] = "nível %d",
  ["Only the default look is unlocked."] = "Só o visual padrão está liberado.",
  ["Open portals"] = "Abrir portais",
  ["Opening the portals..."] = "Abrindo os portais...",
  ["Pick a Waystone Tier you carry. Four portals open around the device for 60 seconds and lead to a random map whose monsters have the level shown."] = "Escolha uma Waystone que você carrega. Quatro portais abrem em volta do dispositivo por 60 segundos e levam a um mapa aleatório com monstros do nível mostrado.",
  ["Pick a portal look."] = "Escolha o visual do portal.",
  ["Waystones pay in gear. Kills inside drop Rare or better set pieces, the map boss drops a table of Legendary pieces, uniques, new waystones and the waystone orbs. A higher tier and more modifiers pay more. Crafting orbs are the rifts' reward."] = "Waystones pagam em equipamento. Monstros lá dentro soltam peças de conjunto Raras ou melhores, o chefe do mapa solta uma tabela de peças Lendárias, únicos, novas waystones e os orbes de waystone. Um tier maior e mais modificadores pagam mais. Orbes de criação são a recompensa das fendas.",
  ["Waystones pay in gear: Rare or better set pieces from the kills, a boss table of Legendary pieces, uniques, new waystones and the waystone orbs. A higher tier and more modifiers pay more."] = "Waystones pagam em equipamento: peças de conjunto Raras ou melhores dos monstros, uma tabela do chefe com peças Lendárias, únicos, novas waystones e os orbes de waystone. Um tier maior e mais modificadores pagam mais.",
  ["Rifts pay in crafting currency: orbs from the kills (Upheaval, Fate, the waystone orbs), a burst from the guardian, and a stronger key when you seal a rift. Low rifts are a fast step for a high level character."] = "Fendas pagam em moeda de criação: orbes dos monstros (Orb of Upheaval, Orb of Fate, os orbes de waystone), uma chuva de orbes do guardião e uma chave mais forte ao selar a fenda. Fendas baixas são um passo rápido para um personagem de nível alto.",
  ["Pays in crafting orbs and keys"] = "Paga em orbes de criação e chaves",
  ["Rifts pay in crafting currency: orbs from the kills (Upheaval, Fate, the waystone orbs), a burst from the guardian, and a stronger key when you seal a rift. Waystones are the place for gear."] = "Fendas pagam em moeda de criação: orbes dos monstros (Orb of Upheaval, Orb of Fate, os orbes de waystone), uma chuva de orbes do guardião e uma chave mais forte ao selar a fenda. Waystones são o lugar do equipamento.",
  ["Portal look"] = "Visual do portal",
  ["Portal look saved."] = "Visual do portal salvo.",
  ["The device refused."] = "O dispositivo recusou.",
  ["The portals are open around the device for 60 seconds."] = "Os portais estão abertos em volta do dispositivo por 60 segundos.",
  ["Waystone Device"] = "Dispositivo de Waystone",
  ["Waystone Tier %s"] = "Waystone Nível %s",
