  -- Passive tree descriptions: a keystone / class text joined into one paragraph (treetext.lua TreeText.lines)
  ["A hit taken from a creature reflects 20% of what landed (and your Reflect Damage once more) as physical damage, at most 50% of your maximum health a hit. Players take a third (at most 5% of their health a hit), bosses half (at most 2 x your level a second). Your damage is 10% less."] = "Um golpe sofrido de uma criatura reflete 20% do que acertou (e mais uma vez o seu Reflect Damage) como dano físico, no máximo 50% da sua vida máxima por golpe. Jogadores sofrem um terço (no máximo 5% da vida por golpe), chefes metade (no máximo 2 x seu nível por segundo). Seu dano é 10% menor.",
  ["A critical hit releases a burst on the other enemies within 1 sqm of its target for 60% of the hit, of your strongest tree element (energy if none), at most once every 0.8 s. Your non-critical hits deal 5% less."] = "Um golpe crítico libera uma explosão nos outros inimigos a até 1 sqm do alvo, com 60% do golpe, do seu elemento mais forte da árvore (energia se não houver), no máximo uma vez a cada 0,8 s. Seus golpes não críticos causam 5% menos.",
  ["Every hit you deal leeches 5% of its damage as health, at most 6% of your maximum health in any second. Healing you receive is 30% less."] = "Todo golpe que você causa drena 5% do dano como vida, no máximo 6% da sua vida máxima por segundo. A cura que você recebe é 30% menor.",
  ["Ranger line: bow and crossbow hits arc to 3 other enemies within 3 sqm for 40% of the hit as energy damage. The hit on its own target deals 10% less."] = "Linha Ranger: golpes de arco e besta saltam para outros 3 inimigos a até 3 sqm com 40% do golpe como dano de energia. O golpe no próprio alvo causa 10% menos.",
  ["Mystic, Necromancer, Monk and Templar lines: your maximum health is 100. Your energy shield: the items' +50%, plus 50% of the health given up. It recharges 15% of its maximum a second faster and starts 1 s after a hit. No poison, no life drain can hurt you. Heals and leech fill only the 100."] = "Linhas Mystic, Necromancer, Monk e Templar: sua vida máxima é 100. Seu escudo de energia: os +50% dos itens, mais 50% da vida abandonada. Ele recarrega 15% do máximo por segundo mais rápido e começa 1 s depois de um golpe. Nenhum veneno nem drenagem de vida pode te ferir. Curas e drenagem enchem só os 100.",
  ["Mystic, Necromancer and Templar lines: your vigils reserve 30% less, reach 3 sqm farther and give your party members 20% more of every effect. Your own damage is 10% less."] = "Linhas Mystic, Necromancer e Templar: suas vigils reservam 30% menos, alcançam 3 sqm a mais e dão 20% a mais de cada efeito aos membros do seu grupo. Seu próprio dano é 10% menor.",
  ["Warrior, Monk and Templar lines: your vigils reserve maximum health instead of mana, at 60% of their share. They work on you alone, 50% stronger. No effect next to Hollow Vessel."] = "Linhas Warrior, Monk e Templar: suas vigils reservam vida máxima em vez de mana, com 60% da parte delas. Funcionam só em você, 50% mais fortes. Sem efeito ao lado do Hollow Vessel.",
  ["Ranger and Thief lines: 2 more traps and 3 more mines may be out at once; they arm in 50% of the time and hit 25% harder. Your other hits (weapon, spells; not damage over time) are 15% less."] = "Linhas Ranger e Thief: 2 armadilhas e 3 minas a mais podem estar ativas ao mesmo tempo; elas armam em 50% do tempo e acertam 25% mais forte. Seus outros golpes (arma, magias; não dano ao longo do tempo) são 15% menores.",
  ["Mystic and Templar lines: fire and holy spell hits ignite (15% of the hit over 4 s). A spell that hits one enemy brands it for 8 s: every second the sigil burns enemies within 1 sqm for 5% of that hit and jumps on when its bearer dies; ignited monsters spread the burn to 2 more when they die. Damage that is not fire or holy is 20% less."] = "Linhas Mystic e Templar: golpes de magia de fogo e sagrado incendeiam (15% do golpe em 4 s). Uma magia que acerta um só inimigo o marca por 8 s: a cada segundo o sigilo queima inimigos a até 1 sqm com 5% desse golpe e salta adiante quando o portador morre; monstros incendiados espalham a queimadura para mais 2 quando morrem. Dano que não é de fogo nem sagrado é 20% menor.",
  ["Thief line: a monster that dies with your poison on it spreads it to 3 monsters within 2 sqm (5 ticks of its last tick). Spread poison spreads again, up to 4 deep. Your weapon hits deal 10% less."] = "Linha Thief: um monstro que morre com o seu veneno espalha-o para 3 monstros a até 2 sqm (5 ticks do último tick). Veneno espalhado se espalha de novo, até 4 de profundidade. Seus golpes de arma causam 10% menos.",
  ["Warrior and Templar lines. Out of a protection zone and in a fight, enemies within 2 sqm take 4% of your maximum health as fire damage every second. You burn for 2.5% of your maximum health a second (never lethal; your fire absorbs count) and regenerate 2% of it a second. Your other damage is 25% less."] = "Linhas Warrior e Templar. Fora de uma zona de proteção e em luta, inimigos a até 2 sqm sofrem 4% da sua vida máxima como dano de fogo por segundo. Você queima 2,5% da sua vida máxima por segundo (nunca letal; suas absorções de fogo contam) e regenera 2% dela por segundo. Seu outro dano é 25% menor.",
  ["Every line but the Monk's. With no weapon in your hands (a shield is fine) your fists hit with the Monk's fist attack (40 + level / 40, at most 60) and your best melee skill, +10% damage."] = "Todas as linhas menos a do Monk. Sem arma nas mãos (escudo pode), seus punhos acertam com o ataque de punho do Monk (40 + nível / 40, no máximo 60) e sua melhor habilidade corpo a corpo, +10% de dano.",
  ["Templar line: a Reliquary Warden follows you. Every 2 s it heals you and your party within 3 sqm (0.6% of maximum health + 2 x your magic level), the others deal +5% damage for 3 s, and enemies within 2 sqm take 0.6 x level + 3 x magic level as holy damage. Your damage is 10% less."] = "Linha Templar: um Reliquary Warden te segue. A cada 2 s ele cura você e seu grupo a até 3 sqm (0,6% da vida máxima + 2 x seu magic level), os outros causam +5% de dano por 3 s, e inimigos a até 2 sqm sofrem 0,6 x nível + 3 x magic level como dano sagrado. Seu dano é 10% menor.",
  ["Mystic and Necromancer lines: an attack spell hitting 2 or more enemies raises a Cinder Effigy on your tile (at most 2, for 12 s). Every 2 s it repeats the cast within 3 sqm of it for 24% of the cast's average hit. Your spells deal 25% less."] = "Linhas Mystic e Necromancer: uma magia de ataque que acerta 2 ou mais inimigos ergue um Cinder Effigy no seu quadrado (no máximo 2, por 12 s). A cada 2 s ele repete a conjuração a até 3 sqm dele com 24% do golpe médio da conjuração. Suas magias causam 25% menos.",
  ["Mystic and Necromancer lines: a monster that dies within 2 s of your ice hit shatters: enemies within 2 sqm take 6% of its maximum health as ice damage (at most 12 x your level). Kills shatter again. Your fire and energy damage is 30% less."] = "Linhas Mystic e Necromancer: um monstro que morre até 2 s depois de um golpe seu de gelo se estilhaça: inimigos a até 2 sqm sofrem 6% da vida máxima dele como dano de gelo (no máximo 12 x seu nível). Abates estilhaçam de novo. Seu dano de fogo e energia é 30% menor.",
  ["Monk and Templar lines: your weapon and fist hits add 6% of your current energy shield as energy damage. Your maximum health is 20% less."] = "Linhas Monk e Templar: seus golpes de arma e punho somam 6% do seu escudo de energia atual como dano de energia. Sua vida máxima é 20% menor.",
  ["Necromancer line: your minions deal +50% damage (Bone Lord: +20% damage) and have +50% health. Your own spells deal 25% less damage."] = "Linha Necromancer: seus lacaios causam +50% de dano (Bone Lord: +20% de dano) e têm +50% de vida. Suas próprias magias causam 25% menos dano.",
  ["Templar line: a melee or ranged hit you take is answered with a holy strike on the attacker for 40% of the damage + 4 x magic level (at most one every 0.5 s). Your defence aura's damage reduction is halved (for the party too)."] = "Linha Templar: um golpe corpo a corpo ou à distância que você sofre é respondido com um golpe sagrado no atacante, com 40% do dano + 4 x magic level (no máximo um a cada 0,5 s). A redução de dano da sua aura de defesa cai pela metade (para o grupo também).",
  ["Thief line: every attack poisons the target as Poison Blades does, with or without the buff: auto attacks and all attack spells, single target and area. Your poison deals +30% damage. Your evasion is halved."] = "Linha Thief: todo ataque envenena o alvo como o Poison Blades, com ou sem o buff: ataques automáticos e todas as magias de ataque, alvo único e área. Seu veneno causa +30% de dano. Sua esquiva cai pela metade.",
  ["Monk line: a hit you take gives 1 chi (at most one every 2 s); while you hold 3 chi or more you take 10% less damage. You can no longer dodge."] = "Linha Monk: um golpe que você sofre dá 1 chi (no máximo um a cada 2 s); enquanto tiver 3 chi ou mais você sofre 10% menos dano. Você não consegue mais esquivar.",
  ["Warrior line: every 4th melee hit deals 50% more and slams the ground: up to 6 other enemies within 2 sqm take 60% of that hit as physical damage. Your other melee hits deal 10% less."] = "Linha Warrior: todo 4º golpe corpo a corpo causa 50% a mais e bate no chão: até 6 outros inimigos a até 2 sqm sofrem 60% desse golpe como dano físico. Seus outros golpes corpo a corpo causam 10% menos.",
  ["Warrior line: a melee or spell hit that would leave a monster (not a boss) at 15% of its health or less kills it. Your melee and spell hits on monsters above 60% health deal 10% less."] = "Linha Warrior: um golpe corpo a corpo ou de magia que deixaria um monstro (não chefe) com 15% da vida ou menos o mata. Seus golpes corpo a corpo e de magia em monstros acima de 60% da vida causam 10% menos.",
  ["Ranger line: bow, crossbow and thrown weapon hits have a 25% chance to hobble the target for 3 s (40% slower). Your hits on a hobbled target deal 20% more, on any other 8% less."] = "Linha Ranger: golpes de arco, besta e arma de arremesso têm 25% de chance de atrasar o alvo por 3 s (40% mais lento). Seus golpes num alvo atrasado causam 20% a mais, em qualquer outro 8% a menos.",
  ["Warrior line: killing a monster gives a stack (at most 5; they end 6 s after the last kill). Each stack: you deal 6% more damage and take 4% more damage."] = "Linha Warrior: matar um monstro dá uma carga (no máximo 5; elas acabam 6 s depois do último abate). Cada carga: você causa 6% mais dano e sofre 4% mais dano.",
  ["Warrior line: a hit that would take you below 20% of your maximum health is cut so you keep 20%; then you take 40% less damage for 5 s. Once every 90 s, not against players. Healing you receive is 20% less."] = "Linha Warrior: um golpe que te levaria abaixo de 20% da vida máxima é reduzido para você ficar com 20%; depois você sofre 40% menos dano por 5 s. Uma vez a cada 90 s, não contra jogadores. A cura que você recebe é 20% menor.",
  ["Ranger line: bow, crossbow and thrown weapon hits bleed for 60% of the hit as physical damage over 4 s. The hit itself deals 10% less."] = "Linha Ranger: golpes de arco, besta e arma de arremesso sangram por 60% do golpe como dano físico em 4 s. O golpe em si causa 10% menos.",
  ["Ranger line: bow, crossbow and thrown weapon hits deal 6% more for every square of distance beyond 2, at most 30% more. Hits from 2 sqm or closer deal 15% less."] = "Linha Ranger: golpes de arco, besta e arma de arremesso causam 6% a mais por quadrado de distância além de 2, no máximo 30% a mais. Golpes a 2 sqm ou menos causam 15% menos.",
  ["Ranger line: your first bow, crossbow or thrown weapon hit on a monster at full health deals 80% more. Your other such hits deal 7% less."] = "Linha Ranger: seu primeiro golpe de arco, besta ou arma de arremesso num monstro com a vida cheia causa 80% a mais. Seus outros golpes desse tipo causam 7% menos.",
  ["Holds the keystone of your class: every class has its own here."] = "Guarda a keystone da sua classe: cada classe tem a sua aqui.",
  ["Two-handed melee hits cleave: up to 3 other enemies next to you take 40% of the hit."] = "Golpes corpo a corpo de duas mãos atingem em arco: até 3 outros inimigos ao seu lado sofrem 40% do golpe.",
  ["Bow and crossbow hits: 100% chance to ricochet to the nearest other enemy within 4 sqm for 65% of the hit, then once more for 65% of that (42%). Never the same target twice."] = "Golpes de arco e besta: 100% de chance de ricochetear para o inimigo mais próximo a até 4 sqm com 65% do golpe, e mais uma vez com 65% disso (42%). Nunca o mesmo alvo duas vezes.",
  ["Spells that hit 2 or more enemies: 35% chance to echo 0.6 s later on the same spots for 50% of their damage. Cooldown 3 s."] = "Magias que acertam 2 ou mais inimigos: 35% de chance de ecoar 0,6 s depois nos mesmos pontos com 50% do dano. Recarga de 3 s.",
  ["Heals you cast on others also plant regrowth: 10% of the heal again over 6 s (3 pulses). A new heal adds its share to what is left."] = "Curas que você lança em outros também plantam rebrota: 10% da cura de novo em 6 s (3 pulsos). Uma nova cura soma a parte dela ao que sobrou.",
  ["Support (needs a party): your hits mark the enemy for 6 s. Other party members deal +12% damage to a marked enemy and heal for 4% of it."] = "Suporte (precisa de grupo): seus golpes marcam o inimigo por 6 s. Outros membros do grupo causam +12% de dano a um inimigo marcado e se curam em 4% dele.",
  ["You take 8% less damage, 16% less while below 50% health."] = "Você sofre 8% menos dano, 16% menos abaixo de 50% da vida.",
  ["Bow and crossbow hits on the same target deal +4% more each, up to +20%. Another target (or 6 s without a hit) starts again."] = "Golpes de arco e besta no mesmo alvo causam +4% a mais cada, até +20%. Outro alvo (ou 6 s sem golpe) recomeça.",
  ["Weapon hits: 30% chance for your shadow to strike the same target again 0.3 s later for 60% of the hit. You take 6% more damage."] = "Golpes de arma: 30% de chance de a sua sombra atacar o mesmo alvo de novo 0,3 s depois com 60% do golpe. Você sofre 6% mais dano.",
  ["A monster you or your minions kill explodes: 12% of its maximum health (at most 15 x your level) as death damage on up to 6 enemies within 2 sqm. Your and your minions' hits deal 8% less."] = "Um monstro que você ou seus lacaios matam explode: 12% da vida máxima dele (no máximo 15 x seu nível) como dano de morte em até 6 inimigos a até 2 sqm. Seus golpes e os dos seus lacaios causam 8% menos.",
  ["Every 5th melee hit (fists or weapon) within 4 s is a finisher: 120% more damage, and a shockwave hits up to 4 enemies next to the target for 50% of it. Your other melee hits deal 10% less."] = "Todo 5º golpe corpo a corpo (punhos ou arma) em 4 s é um golpe final: 120% a mais de dano, e uma onda de choque atinge até 4 inimigos ao lado do alvo com 50% dele. Seus outros golpes corpo a corpo causam 10% menos.",
  ["With a shield: 20% chance to block a melee or ranged attack completely. A block sends a holy nova (once per 1 s): up to 8 enemies within 2 sqm take the blocked hit + 4 x your magic level. Your weapon hits deal 10% less."] = "Com escudo: 20% de chance de bloquear totalmente um ataque corpo a corpo ou à distância. Um bloqueio solta uma holy nova (uma vez por 1 s): até 8 inimigos a até 2 sqm sofrem o golpe bloqueado + 4 x seu magic level. Seus golpes de arma causam 10% menos.",
  ["With a shield: 15% chance to block a melee or ranged attack completely, and 30% of melee damage taken is reflected to the attacker."] = "Com escudo: 15% de chance de bloquear totalmente um ataque corpo a corpo ou à distância, e 30% do dano corpo a corpo sofrido é refletido ao atacante.",
  ["Crossbow and bolts: 15% chance for a Deadeye shot that deals double damage (+100%)."] = "Besta e virotes: 15% de chance de um tiro Deadeye que causa dano dobrado (+100%).",
  ["A spell hit primes the other elements: your next spell of a different element within 8 s deals +20% damage."] = "Um golpe de magia prepara os outros elementos: sua próxima magia de outro elemento em até 8 s causa +20% de dano.",
  ["Melee and ranged attackers take earth damage back: 30% of their hit + 2 x your magic level."] = "Atacantes corpo a corpo e à distância sofrem dano de terra de volta: 30% do golpe deles + 2 x seu magic level.",
  ["Support (needs a party): other party members within 8 sqm of you deal +8% damage."] = "Suporte (precisa de grupo): outros membros do grupo a até 8 sqm de você causam +8% de dano.",
  ["Melee weapon hits heal you for 4% of the damage dealt, 8% while below 50% health."] = "Golpes de arma corpo a corpo te curam em 4% do dano causado, 8% abaixo de 50% da vida.",
  ["Your companions' bites and Feral Command deal +35% damage, and companions take 20% less."] = "As mordidas dos seus companheiros e o Feral Command causam +35% de dano, e os companheiros sofrem 20% menos.",
  ["Weapon hits on a poisoned target: 20% chance to strike a vital for double damage (+100%). Weapon hits on a target that is not poisoned deal 15% less."] = "Golpes de arma num alvo envenenado: 20% de chance de acertar um ponto vital com dano dobrado (+100%). Golpes de arma num alvo não envenenado causam 15% menos.",
  ["Your and your minions' hits on a monster at 40% health or less deal 100% more; on a monster above 40% they deal 8% less."] = "Seus golpes e os dos seus lacaios num monstro com 40% da vida ou menos causam 100% a mais; num monstro acima de 40% causam 8% menos.",
  ["Melee hits (fists or weapon) pass through: the enemy behind the target takes 70% of the hit, the next one behind it 40%. The hit itself deals 5% less."] = "Golpes corpo a corpo (punhos ou arma) atravessam: o inimigo atrás do alvo sofre 70% do golpe, o seguinte atrás dele 40%. O golpe em si causa 5% menos.",
  ["Melee weapon hits chain holy light to the nearest other enemy within 3 sqm for 55% of the hit, then once more for 55% of that (30%). Never the same target twice. Your spells deal 10% less."] = "Golpes de arma corpo a corpo encadeiam luz sagrada para o inimigo mais próximo a até 3 sqm com 55% do golpe, e mais uma vez com 55% disso (30%). Nunca o mesmo alvo duas vezes. Suas magias causam 10% menos.",
  ["Melee, heavy armour, the most health. Keystones: Cleaving Arc, Bulwark. Ascends: Juggernaut or Berserker."] = "Corpo a corpo, armadura pesada, a maior vida. Keystones: Cleaving Arc, Bulwark. Ascende: Juggernaut ou Berserker.",
  ["The tank: taunts, damage reduction, shield block. Keystones: Immovable, Bulwark."] = "O tanque: provocação, redução de dano, bloqueio de escudo. Keystones: Immovable, Bulwark.",
  ["Two-handed area damage, rage as health drops. Keystones: Cleaving Arc, Undying Rage."] = "Dano em área com duas mãos, fúria conforme a vida cai. Keystones: Cleaving Arc, Undying Rage.",
  ["Bows and crossbows. Keystones: Ricochet, Deadeye. Ascends: Deadeye or Beastmaster."] = "Arcos e bestas. Keystones: Ricochet, Deadeye. Ascende: Deadeye ou Beastmaster.",
  ["The top single-target damage. Keystones: Hunter's Focus, Deadeye."] = "O maior dano em alvo único. Keystones: Hunter's Focus, Deadeye.",
  ["Companions beside you, bow with arrow splash. Keystones: Ricochet, Pack Alpha."] = "Companheiros ao seu lado, arco com dano em área de flechas. Keystones: Ricochet, Pack Alpha.",
  ["Spells, wands and rods. Keystones: Arcane Echo, Elemental Overload. Ascends: Elementalist or Illusionist."] = "Magias, varinhas e cajados. Keystones: Arcane Echo, Elemental Overload. Ascende: Elementalist ou Illusionist.",
  ["The top area damage. Keystones: Arcane Echo, Elemental Overload."] = "O maior dano em área. Keystones: Arcane Echo, Elemental Overload.",
  ["The best healer, party attack buffs. Keystones: Shared Phantasm, Inspiring Illusion."] = "O melhor curandeiro, buffs de ataque para o grupo. Keystones: Shared Phantasm, Inspiring Illusion.",
  ["Light blades, shurikens, stealth. Class section (top left): Ninja and Samurai paths after ascension. Line keystone: Blackblood Creed. Wrath / Resolve: Shadow Twin, Viper's Verdict."] = "Lâminas leves, shurikens, furtividade. Seção da classe (canto superior esquerdo): caminhos de Ninja e Samurai após a ascensão. Keystone da linha: Blackblood Creed. Wrath / Resolve: Shadow Twin, Viper's Verdict.",
  ["Dual daggers, evasion, shadow. Class section (top left), keystone Living Shadow; Blackblood Creed; Shadow Twin, Viper's Verdict."] = "Adagas duplas, esquiva, sombra. Seção da classe (canto superior esquerdo), keystone Living Shadow; Blackblood Creed; Shadow Twin, Viper's Verdict.",
  ["Duelist off-tank: parries, counters, taunts. Class section (top left), keystone Way of the Blade; Blackblood Creed; Shadow Twin, Viper's Verdict."] = "Duelista off-tank: aparos, contra-ataques, provocação. Seção da classe (canto superior esquerdo), keystone Way of the Blade; Blackblood Creed; Shadow Twin, Viper's Verdict.",
  ["Skeletons, curses and corpses. Class section (top left): Lich and Bone Lord paths after ascension. Line keystone: Covenant of the Grave. Wrath / Resolve: Corpse Detonation, Reaper's Toll."] = "Esqueletos, maldições e cadáveres. Seção da classe (canto superior esquerdo): caminhos de Lich e Bone Lord após a ascensão. Keystone da linha: Covenant of the Grave. Wrath / Resolve: Corpse Detonation, Reaper's Toll.",
  ["Curses, rot, life drain, one shade. Class section (top left), keystone Hoarded Souls; Covenant of the Grave; Corpse Detonation, Reaper's Toll."] = "Maldições, podridão, drenagem de vida, uma sombra. Seção da classe (canto superior esquerdo), keystone Hoarded Souls; Covenant of the Grave; Corpse Detonation, Reaper's Toll.",
  ["The army, the Bone Golem, a banner. Class section (top left), keystone Bone Colossus; Covenant of the Grave; Corpse Detonation, Reaper's Toll."] = "O exército, o Bone Golem, um estandarte. Seção da classe (canto superior esquerdo), keystone Bone Colossus; Covenant of the Grave; Corpse Detonation, Reaper's Toll.",
  ["Unarmed strikes build chi, finishers spend it. Class section (top left): Shadowfist and Iron Sage paths. Line keystone: Scarred Discipline. Wrath / Resolve: Seventh Palm, Piercing Palm."] = "Golpes sem arma geram chi, os finalizadores o gastam. Seção da classe (canto superior esquerdo): caminhos de Shadowfist e Iron Sage. Keystone da linha: Scarred Discipline. Wrath / Resolve: Seventh Palm, Piercing Palm.",
  ["Single-target burst, focus crits. Class section (top left), keystone Hundred Hands; Scarred Discipline; Seventh Palm, Piercing Palm."] = "Explosão em alvo único, foco em críticos. Seção da classe (canto superior esquerdo), keystone Hundred Hands; Scarred Discipline; Seventh Palm, Piercing Palm.",
  ["Chi healer: Kindled Breath, Mantra, Chi Ward. Class section (top left), keystone Flowing Mercy; Scarred Discipline; Overgrowth (Wrath); Piercing Palm (Resolve)."] = "Curandeiro de chi: Kindled Breath, Mantra, Chi Ward. Seção da classe (canto superior esquerdo), keystone Flowing Mercy; Scarred Discipline; Overgrowth (Wrath); Piercing Palm (Resolve).",
  ["Holy melee, shield, a defence aura. Class section (top left): Inquisitor and Sentinel paths after ascension. Line keystone: Penitent's Wrath. Wrath / Resolve: Radiant Rebuke, Dawnchain."] = "Corpo a corpo sagrado, escudo, uma aura de defesa. Seção da classe (canto superior esquerdo): caminhos de Inquisitor e Sentinel após a ascensão. Keystone da linha: Penitent's Wrath. Wrath / Resolve: Radiant Rebuke, Dawnchain.",
  ["Holy area damage, Judgement, Zealotry. Class section (top left), keystone Divine Verdict; Penitent's Wrath; Radiant Rebuke, Dawnchain."] = "Dano sagrado em área, Judgement, Zealotry. Seção da classe (canto superior esquerdo), keystone Divine Verdict; Penitent's Wrath; Radiant Rebuke, Dawnchain.",
  ["Tank-support, the strongest aura. Class section (top left), keystone Bastion; Penitent's Wrath; Radiant Rebuke (Wrath); Thorns (Resolve)."] = "Tanque de suporte, a aura mais forte. Seção da classe (canto superior esquerdo), keystone Bastion; Penitent's Wrath; Radiant Rebuke (Wrath); Thorns (Resolve).",
  -- Passive tree descriptions: masteries and notables
  ["Mantra of Stone: 11% less damage taken (instead of 8%)."] = "Mantra of Stone: 11% menos dano recebido (em vez de 8%).",
  ["Kindled Breath also heals the next most hurt party member for 40% of it (and its heal over time)."] = "O Kindled Breath também cura o próximo membro do grupo mais ferido com 40% dele (e da cura ao longo do tempo).",
  ["Raise Dead: one more skeleton."] = "Raise Dead: um esqueleto a mais.",
  ["Your Radiant Strikes have a 20% chance to judge their target (Judgement: +20% holy damage taken from everyone for 8 s)."] = "Seus Radiant Strikes têm 20% de chance de julgar o alvo (Judgement: +20% de dano sagrado recebido de todos por 8 s).",
  ["Your aura regenerates 0.5% of the maximum health per second (instead of 0.4%)."] = "Sua aura regenera 0,5% da vida máxima por segundo (em vez de 0,4%).",
  ["Your aura: 4% less damage more and 1 sqm wider. Aegis of Faith also covers the party members under your aura, at half strength."] = "Sua aura: 4% a mais de redução de dano e 1 sqm mais larga. O Aegis of Faith também cobre os membros do grupo sob a sua aura, com metade da força.",
  ["Evasion +4%."] = "Esquiva +4%.",
  ["Radiant Strikes: the holy strike deals 30% of the hit (instead of 25%)."] = "Radiant Strikes: o golpe sagrado causa 30% do golpe (em vez de 25%).",
  ["Your Bone Golem hits +60% harder and has +50% health."] = "Seu Bone Golem bate +60% mais forte e tem +50% de vida.",
  ["Banner of Bones: your minions deal +45% damage (instead of 30%)."] = "Banner of Bones: seus lacaios causam +45% de dano (em vez de 30%).",
  ["Soul Hoard: +40% spell damage per empty shade slot (instead of 25%), and +15% while your shade is out."] = "Soul Hoard: +40% de dano de magia por espaço de sombra vazio (em vez de 25%), e +15% enquanto sua sombra está fora.",
  ["Soul Rot deals +25% damage."] = "O Soul Rot causa +25% de dano.",
  ["Withering Curse spreads to one more enemy."] = "O Withering Curse se espalha para mais um inimigo.",
  ["Mastery: choose one effect when you take it."] = "Mastery: escolha um efeito ao pegá-la.",
  ["Counter Stance: the answer deals +50% and the stance lasts 1 s longer."] = "Counter Stance: a resposta causa +50% e a postura dura 1 s a mais.",
  ["Counter Stance parries every melee hit while it lasts (not only the first). Bushido Focus: a hit taken keeps half of the stacks."] = "O Counter Stance aparra todo golpe corpo a corpo enquanto dura (não só o primeiro). Bushido Focus: um golpe recebido mantém metade das cargas.",
  ["A dodge, or your first hit out of Shadow Veil, opens a 4 s window: your weapon hits and strikes deal +25% damage."] = "Uma esquiva, ou seu primeiro golpe fora do Shadow Veil, abre uma janela de 4 s: seus golpes de arma e ataques causam +25% de dano.",
  ["Pressure Points: +6% damage taken per stack (instead of 5%)."] = "Pressure Points: +6% de dano recebido por carga (em vez de 5%).",
  ["Dual wield: the off-hand strike deals 65% of the main-hand hit (instead of 50%)."] = "Duas armas: o golpe da mão secundária causa 65% do golpe da mão principal (em vez de 50%).",
  ["Focus critical hits also give you a chi (at most one per second)."] = "Críticos do Focus também te dão 1 chi (no máximo um por segundo).",
