  ["%s socket, fixed (gems may be socketed and taken out)."] = "%s socket, fixo (gems podem ser colocadas e retiradas).",
  ["A unique keeps its stats: no orb changes it. Salvage gives %s rune shards and %s Conquest Tokens."] = "Um unique mantém seus atributos: nenhum orbe o muda. O salvage dá %s rune shards e %s Conquest Tokens.",
  ["An item carries each modifier once at most."] = "Um item carrega cada modificador no máximo uma vez.",
  ["Among every modifier an item of that kind may roll, powers not counted (weights):"] = "Entre todos os modificadores que um item desse tipo pode rolar, sem contar os poderes (pesos):",
