  ["A unique keeps its stats: no orb changes it. As a set piece it salvages for %s rune shards and %s Conquest Tokens."] = "Um unique mantém seus atributos: nenhum orbe o muda. Como peça de set, o salvage dá %s rune shards e %s Conquest Tokens.",
  ["Roll weight %s; on keys of tier %s or higher."] = "Peso de rolagem %s; em chaves de tier %s ou maior.",
  ["Critical Hit: chance +%s%%, damage +%s%%"] = "Golpe crítico: chance +%s%%, dano +%s%%",
  ["Physical Absorb +%s%%"] = "Absorção física +%s%%",
  ["The tier follows from the value; keys of tier %s-%s roll I-III, keys of tier %s-%s roll I-IV, keys of tier %s-%s roll II-V."] = "O tier vem do valor; chaves de tier %s-%s rolam I-III, chaves de tier %s-%s rolam I-IV, chaves de tier %s-%s rolam II-V.",
