  ["Fire Absorb +%s%%"] = "Absorção de fogo +%s%%",
  ["Prefix: the monsters or the guardian get stronger."] = "Prefixo: os monstros ou o guardião ficam mais fortes.",
  ["Suffix: the players or the area get worse."] = "Sufixo: os jogadores ou a área pioram.",
  ["%s gold at the Material Broker, x the week's demand (x%s, x%s, x%s, x%s, x%s); the full price for %s a day, then %s%% up to %s a day."] = "%s de ouro no Material Broker, x a demanda da semana (x%s, x%s, x%s, x%s, x%s); o preço cheio por %s ao dia, depois %s%% até %s ao dia.",
  ["A piece counts when it is worn in its slot and you have its level; the same piece twice counts once."] = "Uma peça conta quando está equipada no slot dela e você tem o nível dela; a mesma peça duas vezes conta uma só.",
  ["A two-handed weapon counts as two pieces."] = "Uma arma de duas mãos conta como duas peças.",
  ["Every spell with an id has up to %s support sockets: the first once you may cast it, the second at a character level of the spell's level + %s (at least %s), the third at the spell's level + %s (at least %s), opened once per spell with %s Orbs of Sockets."] = "Toda magia com id tem até %s sockets de support: o primeiro assim que você pode conjurá-la, o segundo no nível de personagem igual ao da magia + %s (no mínimo %s), o terceiro no nível da magia + %s (no mínimo %s), abertos uma vez por magia com %s Orbs of Sockets.",
  ["Number bonuses add to your gear's modifiers under the same caps; a set never lifts a cap."] = "Bônus numéricos somam aos modificadores do seu equipamento sob os mesmos limites; um set nunca ultrapassa um limite.",
  ["Pieces are uniques: no orb changes them, they keep one socket; salvage gives %s rune shards; a transmog look keeps the bonus."] = "As peças são uniques: nenhum orbe as muda, elas mantêm um socket; o salvage dá %s rune shards; um visual de transmog mantém o bônus.",
  ["Three runes of one support and level make one of the next level (Common > Rare > Epic > Legendary > Mythic)."] = "Três runas de um support e nível formam uma do nível seguinte (Common > Rare > Epic > Legendary > Mythic).",
  ["Use the stack, then left-click the same stack (or another stack of the same rune). The runes may be in your backpack, your purse or your depot."] = "Use a pilha e depois clique com o botão esquerdo na mesma pilha (ou em outra pilha da mesma runa). As runas podem estar na mochila, na bolsa ou no depot.",
  ["Health on Hit +%s"] = "Vida por golpe +%s",
  ["Reward bonus: +%s%% quantity, +%s%% rarity per point."] = "Bônus de recompensa: +%s%% de quantidade, +%s%% de raridade por ponto.",
  ["Reward bonus: +%s%% quantity, +%s%% experience per point."] = "Bônus de recompensa: +%s%% de quantidade, +%s%% de experiência por ponto.",
  ["Reward bonus: +%s%% quantity, +%s%% rarity, +%s%% experience per point."] = "Bônus de recompensa: +%s%% de quantidade, +%s%% de raridade, +%s%% de experiência por ponto.",
  ["Reward bonus: none (a boon)."] = "Bônus de recompensa: nenhum (uma bênção).",
  ["A boon: a pure reward without a reward bonus of its own."] = "Uma bênção: uma recompensa pura, sem bônus de recompensa próprio.",
  ["Uniques, ruined and corrupted items and stacks are refused; the crafting bench shows what an orb would do before you use it."] = "Uniques, itens arruinados e corrompidos e pilhas são recusados; a bancada de criação mostra o que um orbe faria antes de você usá-lo.",
