  ["Your best drop, Tower floor, rift tier and boss times. A new best shows \"New record\" in the game."] = "Seu melhor drop, andar da Torre, nível de fenda e tempos de chefe. Um novo recorde mostra \"Novo recorde\" no jogo.",
