  ["Absorbs a share of the arcane damage you take (shown on the item as \"Arcane +N%%\"). All your arcane absorb together, gear and passives, is capped at %s%%."] = "Absorve uma parte do dano arcano que você recebe (mostrado no item como \"Absorção arcana +N%%\"). Toda a sua absorção arcana junta, de equipamentos e passivas, tem limite de %s%%.",
  ["The weapon deals this much extra damage as arcane damage."] = "A arma causa essa quantidade de dano extra como dano arcano.",
  ["Raises the Armorsmithing profession skill while the item is worn."] = "Aumenta a skill da profissão Armorsmithing enquanto o item estiver equipado.",
  ["On an item: Attack Speed +%s-%s%% (T%s)."] = "Em um item: Velocidade de ataque +%s-%s%% (T%s).",
  ["Local to the weapon: it shortens that weapon's attack interval. With topaz gems at most %s%% on one weapon."] = "Local da arma: encurta o intervalo de ataque dessa arma. Com gemas de topázio, no máximo %s%% em uma arma.",
