  ["Critical / leech, prefix."] = "Crítico / roubo de vida, prefixo.",
  ["A pair: a chance to hit critically and the extra damage of a critical hit. The amount is the rolled value; the chance is about two thirds of it."] = "Um par: uma chance de acertar um crítico e o dano extra de um golpe crítico. A quantidade é o valor rolado; a chance é cerca de dois terços dela.",
  ["On an item: Critical Strike Chance with Bows +%s-%s%% (T%s)."] = "Em um item: Chance de golpe crítico com arcos +%s-%s%% (T%s).",
  ["On an item: Damage Taken from Monsters -%s-%s%% (T%s)."] = "Em um item: Dano recebido de monstros -%s-%s%% (T%s).",
  ["Shields, Helmets, Body armour and Legs."] = "Escudos, capacetes, armaduras de corpo e calças.",
  ["On an item: Damage over Time +%s-%s%% (T%s)."] = "Em um item: Dano ao longo do tempo +%s-%s%% (T%s).",
  ["On an item: Damage to Elites and Bosses +%s-%s%% (T%s)."] = "Em um item: Dano a elites e chefes +%s-%s%% (T%s).",
  ["Absorbs a share of the death damage you take (shown on the item as \"Death +N%%\"). All your death absorb together, gear and passives, is capped at %s%%."] = "Absorve uma parte do dano de morte que você recebe (mostrado no item como \"Absorção de morte +N%%\"). Toda a sua absorção de morte junta, de equipamentos e passivas, tem limite de %s%%.",
  ["The weapon deals this much extra damage as death damage."] = "A arma causa essa quantidade de dano extra como dano de morte.",
  ["On an item: Distance Fighting +%s-%s (T%s)."] = "Em um item: Distância +%s-%s (T%s).",
  ["On an item: Dodge +%s-%s%% (T%s)."] = "Em um item: Esquiva +%s-%s%% (T%s).",
