  ["On an item: Movement Speed +%s-%s%% (T%s)."] = "Em um item: Velocidade de movimento +%s-%s%% (T%s).",
  ["Boots."] = "Botas.",
  ["Shares its %s%% cap with the emerald gems' movement speed."] = "Divide seu limite de %s%% com a velocidade de movimento das gemas de esmeralda.",
  ["Absorbs a share of the physical damage you take (shown on the item as \"Physical +N%%\"). All your physical absorb together, gear and passives, is capped at %s%%."] = "Absorve uma parte do dano físico que você recebe (mostrado no item como \"Absorção física +N%%\"). Toda a sua absorção física junta, de equipamentos e passivas, tem limite de %s%%.",
