  ["On an item: Rarity Find +%s-%s%% (T%s)."] = "Em um item: Rarity find +%s-%s%% (T%s).",
  ["On an item: Reflect Damage +%s-%s%% (T%s)."] = "Em um item: Dano refletido +%s-%s%% (T%s).",
  ["Shields and Body armour."] = "Escudos e armaduras de corpo.",
  ["Raises your shielding skill while the item is worn."] = "Aumenta a sua skill de shielding enquanto o item estiver equipado.",
  ["On an item: Thorns +%s-%s (T%s)."] = "Em um item: Thorns +%s-%s (T%s).",
  ["Shields, Body armour and Legs."] = "Escudos, armaduras de corpo e calças.",
  ["On an item: Treasure Goblin Chance +%s-%s%% (T%s)."] = "Em um item: Chance de Treasure Goblin +%s-%s%% (T%s).",
  ["Absorbs a share of the water damage you take (shown on the item as \"Water +N%%\"). All your water absorb together, gear and passives, is capped at %s%%."] = "Absorve uma parte do dano de água que você recebe (mostrado no item como \"Absorção de água +N%%\"). Toda a sua absorção de água junta, de equipamentos e passivas, tem limite de %s%%.",
  ["The weapon deals this much extra damage as water damage."] = "A arma causa essa quantidade de dano extra como dano de água.",
  ["Raises the Weaponsmithing profession skill while the item is worn."] = "Aumenta a skill da profissão Weaponsmithing enquanto o item estiver equipado.",
  ["Raises the Woodcutting profession skill while the item is worn."] = "Aumenta a skill da profissão Woodcutting enquanto o item estiver equipado.",
  ["A hit arcs to up to %s other monsters within %s sqm for %s%% of it."] = "Um golpe salta para até %s outros monstros em %s sqm com %s%% do dano.",
  ["On an item: Arc Lightning: %s-%s%% chance on hit to arc to %s monsters nearby (T%s)."] = "Em um item: Arc Lightning: %s-%s%% de chance ao acertar de saltar para %s monstros próximos (T%s).",
  ["Every kill adds a stack for %s s, at most %s stacks; each stack adds the power's value to your damage."] = "Cada abate soma uma carga por %s s, no máximo %s cargas; cada carga soma o valor do poder ao seu dano.",
  ["Value: percent damage per stack."] = "Valor: dano em porcentagem por carga.",
  ["On an item: Bloodrush: each kill adds %s-%s%% damage (%s stacks, %s s) (T%s)."] = "Em um item: Bloodrush: cada abate soma %s-%s%% de dano (%s cargas, %s s) (T%s).",
  ["No cooldown: at most %s stacks."] = "Sem recarga: no máximo %s cargas.",
  ["A hit heals you for %s%% of your maximum health."] = "Um golpe cura você em %s%% da sua vida máxima.",
  ["On an item: Crimson Burst: %s-%s%% chance on hit to heal %s%% of your health (T%s)."] = "Em um item: Crimson Burst: %s-%s%% de chance ao acertar de curar %s%% da sua vida (T%s).",
  ["Weapons, Helmets and Jewellery (amulets, rings)."] = "Armas, capacetes e joias (amuletos, anéis).",
  ["A critical hit strikes again after %s ms for %s%% of its damage."] = "Um golpe crítico acerta de novo após %s ms com %s%% do seu dano.",
  ["Value: the chance on a critical hit."] = "Valor: a chance num golpe crítico.",
  ["On an item: Critical Echo: %s-%s%% chance on a critical hit to strike again (T%s)."] = "Em um item: Critical Echo: %s-%s%% de chance num golpe crítico de atacar de novo (T%s).",
  ["On a kill: a fire explosion where the monster died, %s%% of its maximum health (at most %s + %s x your level) to up to %s other monsters within %s sqm."] = "Ao matar: uma explosão de fogo onde o monstro morreu, com %s%% da vida máxima dele (no máximo %s + %s x seu nível) em até %s outros monstros num raio de %s sqm.",
  ["On an item: Death Blast: %s-%s%% chance on kill to explode (T%s)."] = "Em um item: Death Blast: %s-%s%% de chance ao matar de explodir (T%s).",
  ["A ranged hit that lands is shot again after %s ms for %s%% of its damage."] = "Um golpe à distância que acerta é disparado de novo após %s ms com %s%% do seu dano.",
  ["Value: the chance on a ranged hit."] = "Valor: a chance num golpe à distância.",
  ["On an item: Echo Shot: %s-%s%% chance on a ranged hit to shoot again (T%s)."] = "Em um item: Echo Shot: %s-%s%% de chance num golpe à distância de atirar de novo (T%s).",
  ["A single hit of at least %s%% of your maximum health blinks you up to %s sqm away and burns where you stood: %s + %s x your level fire damage to up to %s monsters within %s sqm."] = "Um único golpe de pelo menos %s%% da sua vida máxima teleporta você até %s sqm de distância e queima onde você estava: %s + %s x seu nível de dano de fogo em até %s monstros num raio de %s sqm.",
  ["Value: the chance on a hard hit."] = "Valor: a chance num golpe forte.",
  ["On an item: Ember Step: %s-%s%% chance when hit hard to blink away in flames (T%s)."] = "Em um item: Ember Step: %s-%s%% de chance ao levar um golpe forte de se teleportar em chamas (T%s).",
  ["Body armour, Legs, Boots and Jewellery (amulets, rings)."] = "Armaduras de corpo, calças, botas e joias (amuletos, anéis).",
  ["When a monster's hit is dodged or blocked: an ice nova around you, %s + %s x your level damage to up to %s monsters within %s sqm, slowed by %s%% for %s s."] = "Quando o golpe de um monstro é esquivado ou bloqueado: uma nova de gelo ao seu redor, %s + %s x seu nível de dano em até %s monstros num raio de %s sqm, com lentidão de %s%% por %s s.",
  ["Value: the chance on a dodge or block."] = "Valor: a chance ao esquivar ou bloquear.",
  ["On an item: Glacial Ward: %s-%s%% chance when you dodge or block for a frost nova (T%s)."] = "Em um item: Glacial Ward: %s-%s%% de chance ao esquivar ou bloquear de soltar uma nova de gelo (T%s).",
  ["Haste: +%s speed for %s s."] = "Pressa: +%s de velocidade por %s s.",
  ["On an item: Hunter's Rush: %s-%s%% chance on kill for haste (%s s) (T%s)."] = "Em um item: Hunter's Rush: %s-%s%% de chance ao matar de ganhar pressa (%s s) (T%s).",
  ["Helmets, Boots, Jewellery (amulets, rings) and Other gear (gloves, belts...)."] = "Capacetes, botas, joias (amuletos, anéis) e outros equipamentos (luvas, cintos...).",
  ["A hit that would kill you leaves you at the power's share of your health instead. The cooldown is kept over logout."] = "Um golpe que mataria você deixa você com a parte da sua vida indicada pelo poder. A recarga é mantida ao sair do jogo.",
  ["Value: the health left, percent of your maximum."] = "Valor: a vida que sobra, em porcentagem do seu máximo.",
  ["On an item: Last Breath: a lethal hit leaves you at %s-%s%% health (once per %s minutes) (T%s)."] = "Em um item: Last Breath: um golpe letal te deixa com %s-%s%% de vida (uma vez a cada %s minutos) (T%s).",
  ["The killing blow bursts onto up to %s monsters within %s sqm: the power's share of the health the blow took, shared by them."] = "O golpe final explode em até %s monstros num raio de %s sqm: a parte da vida que o golpe tirou indicada pelo poder, dividida entre eles.",
  ["Value: percent of the health the killing blow took."] = "Valor: porcentagem da vida que o golpe final tirou.",
  ["On an item: Shatter Splash: killing blows burst for %s-%s%%, shared by the monsters nearby (T%s)."] = "Em um item: Shatter Splash: golpes finais explodem com %s-%s%%, divididos entre os monstros próximos (T%s).",
  ["While you fight (you attacked a monster in the last %s s) and stand outside a protection zone, every %s s up to %s monsters within %s sqm and in sight burn for the power's value per second, at most %s + %s per %s levels of yours."] = "Enquanto você luta (atacou um monstro nos últimos %s s) e está fora de uma zona de proteção, a cada %s s até %s monstros num raio de %s sqm e à vista queimam com o valor do poder por segundo, no máximo %s + %s a cada %s níveis seus.",
  ["Value: fire damage per second."] = "Valor: dano de fogo por segundo.",
  ["On an item: Smoldering Aura: while you fight, monsters within %s sqm take %s-%s fire damage per second (T%s)."] = "Em um item: Smoldering Aura: enquanto você luta, monstros num raio de %s sqm sofrem %s-%s de dano de fogo por segundo (T%s).",
  ["No cooldown: it ticks every %s s."] = "Sem recarga: ele age a cada %s s.",
  ["Helmets, Body armour, Legs, Jewellery (amulets, rings) and Other gear (gloves, belts...)."] = "Capacetes, armaduras de corpo, calças, joias (amuletos, anéis) e outros equipamentos (luvas, cintos...).",
  ["Turns a normal item into a Common or Uncommon one with random modifiers (tiers by its item level)."] = "Transforma um item normal em um Common ou Uncommon com modificadores aleatórios (tiers pelo nível do item).",
  ["Gives a Rift Key without modifiers one modifier."] = "Dá um modificador a uma Rift Key sem modificadores.",
  ["Turns a normal item into a Magic, Rare or Legendary one with random modifiers (tiers by its item level)."] = "Transforma um item normal em um Magic, Rare ou Legendary com modificadores aleatórios (tiers pelo nível do item).",
  ["Gives a Rift Key without modifiers two or three modifiers."] = "Dá dois ou três modificadores a uma Rift Key sem modificadores.",
  ["Adds one random modifier on an open prefix or suffix of an item with a rarity."] = "Adiciona um modificador aleatório em um prefixo ou sufixo livre de um item com raridade.",
  ["Only an item with a rarity and an open prefix or suffix."] = "Só um item com raridade e um prefixo ou sufixo livre.",
  ["Adds one modifier to a Rift Key (three at most)."] = "Adiciona um modificador a uma Rift Key (três no máximo).",
  ["Removes one random modifier that is not bound."] = "Remove um modificador aleatório que não esteja vinculado.",
  ["Removes one random modifier of a Rift Key."] = "Remove um modificador aleatório de uma Rift Key.",
  ["Removes the rarity, every modifier and every bind: a normal item again (item level and quality stay)."] = "Remove a raridade, todos os modificadores e todos os vínculos: volta a ser um item normal (nível do item e qualidade permanecem).",
  ["Any item with a rarity."] = "Qualquer item com raridade.",
  ["Removes every modifier of a Rift Key."] = "Remove todos os modificadores de uma Rift Key.",
  ["Rerolls every modifier that is not bound (rarity, item level and quality stay)."] = "Rola de novo todos os modificadores que não estão vinculados (raridade, nível do item e qualidade permanecem).",
  ["Only an item with a rarity; bound modifiers stay."] = "Só um item com raridade; os modificadores vinculados permanecem.",
  ["Rerolls the modifiers of a Rift Key (one to three new ones)."] = "Rola de novo os modificadores de uma Rift Key (de um a três novos).",
  ["Raises the rarity one step with new modifiers (Legendary: a small chance of Divine); item level and quality stay. Not on an item with a bound modifier."] = "Sobe a raridade um degrau com modificadores novos (Legendary: uma pequena chance de Divine); nível do item e qualidade permanecem. Não funciona em um item com modificador vinculado.",
  ["Not on an item with a bound modifier."] = "Não funciona em um item com modificador vinculado.",
  ["Rerolls the values of a Rift Key's modifiers inside their ranges."] = "Rola de novo os valores dos modificadores de uma Rift Key dentro de suas faixas.",
  ["Sockets by kind at most: weapon %s, two-handed %s, armour %s, shield %s, helmet %s, legs %s, boots %s, jewel %s, other %s; by rarity at most %s/%s/%s/%s/%s/%s (Common, Uncommon, Magic, Rare, Legendary, Divine)."] = "Máximo de sockets por tipo: arma %s, duas mãos %s, armadura %s, escudo %s, capacete %s, calças %s, botas %s, joia %s, outros %s; por raridade no máximo %s/%s/%s/%s/%s/%s (Common, Uncommon, Magic, Rare, Legendary, Divine).",
  ["Spell supports: opening a spell's third support socket costs %s of these."] = "Supports de magia: abrir o terceiro socket de support de uma magia custa %s deles.",
  ["Rift Keys have no sockets."] = "Rift Keys não têm sockets.",
  ["Rolls the values of every modifier that is not bound again, inside their current tiers."] = "Rola de novo os valores de todos os modificadores que não estão vinculados, dentro dos tiers atuais.",
  ["Rolls the values of a Rift Key's modifiers again inside their ranges."] = "Rola de novo os valores dos modificadores de uma Rift Key dentro de suas faixas.",
  ["Binds one modifier: the orbs that change modifiers leave it alone. Pick it on the bench (used directly: a random one)."] = "Vincula um modificador: os orbes que mudam modificadores o deixam em paz. Escolha-o na bancada (usado direto: um aleatório).",
  ["Only an item with a rarity; bound modifiers per item: %s up to Rare, %s from Legendary."] = "Só um item com raridade; modificadores vinculados por item: %s até Rare, %s a partir de Legendary.",
  ["Removes the modifier you pick on the bench (used directly: a random one that is not bound)."] = "Remove o modificador que você escolher na bancada (usado direto: um aleatório que não esteja vinculado).",
  ["Removes one modifier of a Rift Key."] = "Remove um modificador de uma Rift Key.",
  ["Rolls the tier (by item level) and value of the modifier you pick again (used directly: a random unbound one)."] = "Rola de novo o tier (pelo nível do item) e o valor do modificador que você escolher (usado direto: um aleatório sem vínculo).",
  ["A gamble: %s%% it improves (a tier more on every unbound modifier, or an extra one), %s%% nothing happens. It never ruins the item."] = "Uma aposta: %s%% de chance de melhorar (um tier a mais em cada modificador sem vínculo, ou um extra), %s%% de nada acontecer. Nunca arruína o item.",
  ["Only an item with a rarity and a modifier; a ruined item can never be changed again."] = "Só um item com raridade e um modificador; um item arruinado nunca mais pode ser alterado.",
  ["+%s%% quality: every modifier value is multiplied by the quality, up to %s%% (%s%% from Divine rarity)."] = "+%s%% de qualidade: o valor de cada modificador é multiplicado pela qualidade, até %s%% (%s%% a partir da raridade Divine).",
  ["Only an item with a rarity and a modifier, below its quality cap (%s%%, %s%% from Divine)."] = "Só um item com raridade e um modificador, abaixo do limite de qualidade (%s%%, %s%% a partir de Divine).",
  ["Raises the modifier you pick on the bench by one tier, with a new value in that tier (used directly: a random unbound one that can still rise)."] = "Sobe o modificador que você escolher na bancada em um tier, com um valor novo nesse tier (usado direto: um aleatório sem vínculo que ainda possa subir).",
  ["Only an item with a rarity and a modifier that is not bound and below the top tier (T%s)."] = "Só um item com raridade e um modificador que não esteja vinculado e abaixo do tier máximo (T%s).",
  ["Lifts the item one rarity, up to Legendary. Every modifier stays, the base bonus becomes the new rarity's and the item gets %s more."] = "Sobe o item uma raridade, até Legendary. Todos os modificadores permanecem, o bônus base passa a ser o da nova raridade e o item ganha mais %s.",
  ["Only an item with a rarity below Legendary. It never makes Divine; unique items are refused."] = "Só um item com raridade abaixo de Legendary. Nunca gera Divine; itens unique são recusados.",
  ["Corrupts a Rare or better item for good: no orb can change it afterwards. Then %s%% nothing else happens, %s%% a modifier rises one tier, %s%% a corrupted implicit modifier, %s%% quality %s%%, %s%% one more socket (up to %s), %s%% every modifier rolls again, %s%% one rarity up (up to Divine), %s%% a modifier falls %s tiers."] = "Corrompe um item Rare ou melhor para sempre: nenhum orbe pode mudá-lo depois. Então %s%% de chance de nada mais acontecer, %s%% de um modificador subir um tier, %s%% de um modificador implícito corrompido, %s%% de qualidade %s%%, %s%% de mais um socket (até %s), %s%% de todos os modificadores rolarem de novo, %s%% de subir uma raridade (até Divine), %s%% de um modificador cair %s tiers.",
  ["Only a Rare or better item that is not locked, not a store item and not corrupted yet. A corrupted item can never be changed by an orb again (it can still be worn, sold, stashed and salvaged)."] = "Só um item Rare ou melhor que não esteja trancado, não seja item da loja e ainda não esteja corrompido. Um item corrompido nunca mais pode ser alterado por um orbe (ainda pode ser equipado, vendido, guardado e desmanchado).",
  ["The item is corrupted first, then one outcome is rolled. Corrupted implicits by kind: Weapon: Damage to Elites and Bosses, Attack Speed, Execute, Physical Penetration, Elemental Penetration; Shield: Block Chance, Reflect Damage, Damage Taken from Monsters; Armour: Damage Taken from Monsters, Reflect Damage, Health Regeneration, Thorns; Helmet: Damage Taken from Monsters, Cooldown Reduction, Mana Cost Reduction; Legs: Damage Taken from Monsters, Thorns, Dodge; Boots: Movement Speed, Dodge; Jewel: Damage to Elites and Bosses, Cooldown Reduction, Mana Cost Reduction, Experience; Other: Damage over Time, Dodge, Cooldown Reduction; Quiver: Damage to Elites and Bosses, Physical Penetration, Elemental Penetration."] = "O item é corrompido primeiro, depois um resultado é rolado. Implícitos corrompidos por tipo: Arma: Dano a elites e chefes, Velocidade de ataque, Execução, Penetração física, Penetração elemental; Escudo: Chance de bloqueio, Dano refletido, Dano recebido de monstros; Armadura: Dano recebido de monstros, Dano refletido, Regeneração de vida, Thorns; Capacete: Dano recebido de monstros, Redução de recarga, Redução de custo de mana; Calças: Dano recebido de monstros, Thorns, Esquiva; Botas: Velocidade de movimento, Esquiva; Joia: Dano a elites e chefes, Redução de recarga, Redução de custo de mana, Experiência; Outros: Dano ao longo do tempo, Esquiva, Redução de recarga; Aljava: Dano a elites e chefes, Penetração física, Penetração elemental.",
  ["Reveals the veiled modifier of an item: choose one of three modifiers of the veiled pool (tier by the item level). The choice is final."] = "Revela o modificador velado de um item: escolha um de três modificadores do pool velado (tier pelo nível do item). A escolha é definitiva.",
  ["Only an item with a veiled modifier that is not revealed yet. The three choices are rolled once and stay the same every time the window opens."] = "Só um item com um modificador velado que ainda não foi revelado. As três opções são roladas uma vez e ficam iguais toda vez que a janela abre.",
  ["V%s from item level %s, V%s from item level %s, V%s from item level %s, V%s from item level %s. An offer's tier is one of the best %s the item level allows. Uniques and set pieces never have a veiled slot; every other orb keeps it."] = "V%s a partir do nível de item %s, V%s a partir do nível de item %s, V%s a partir do nível de item %s, V%s a partir do nível de item %s. O tier de uma oferta é um dos %s melhores que o nível do item permite. Uniques e peças de set nunca têm slot velado; todos os outros orbes o mantêm.",
  ["Combine %s,%s at the Crafting Bench (Salvage tab) into a Crown Orb. One click makes one orb, Ctrl+click up to %s."] = "Combine %s,%s na Crafting Bench (aba Salvage) em um Crown Orb. Um clique faz um orbe, Ctrl+clique até %s.",
  ["Combine %s,%s at the Crafting Bench (Salvage tab) into an Ember Orb. One click makes one orb, Ctrl+click up to %s."] = "Combine %s,%s na Crafting Bench (aba Salvage) em um Ember Orb. Um clique faz um orbe, Ctrl+clique até %s.",
  ["A splinter of a rift's dying breath. Use %s of them to bind an Omen Key."] = "Uma lasca do último suspiro de um rift. Use %s delas para vincular uma Omen Key.",
  ["It hums with a guardian's name. Use it in a protection zone to open its arena."] = "Ela zune com o nome de um guardião. Use numa zona de proteção para abrir a arena dele.",
  ["Bound from %s omen fragments; it opens one guardian's arena (Rift tab > Omens)."] = "Vinculada com %s fragmentos de omen; abre a arena de um guardião (aba Rift > Omens).",
  ["Use it in a protection zone: you and up to %s party members within %s sqm enter a rift of the key's tier (%s tiers). See the Rift tab for its modifiers."] = "Use numa zona de proteção: você e até %s membros do grupo num raio de %s sqm entram num rift do tier da chave (%s tiers). Veja a aba Rift para os modificadores.",
  ["Rift tab > Rift Keys has the sources and the orbs that work on keys."] = "Aba Rift > Rift Keys tem as fontes e os orbes que funcionam em chaves.",
  ["A splinter of the power bound in salvaged gear. Combine shards into orbs at the crafting bench (Economy > Salvage)."] = "Uma lasca do poder preso no equipamento desmanchado. Junte shards em orbes na bancada de criação (Economy > Salvage).",
  ["Shards per item: the rarity's base, up to %s%% more by item level, +%s per modifier of T%s or better, +%s per empty socket. Uniques are never salvaged."] = "Shards por item: a base da raridade, até %s%% a mais pelo nível do item, +%s por modificador de T%s ou melhor, +%s por socket vazio. Uniques nunca são desmanchados.",
  ["Combine %s,%s at the Crafting Bench (Salvage tab) into a Void Orb. One click makes one orb, Ctrl+click up to %s."] = "Combine %s,%s na Crafting Bench (aba Salvage) em um Void Orb. Um clique faz um orbe, Ctrl+clique até %s.",
  ["Fire Damage at most %s%%."] = "Dano de fogo no máximo %s%%.",
  ["Max Health at most %s."] = "Vida máxima no máximo %s.",
  ["Fire Resistance at most %s%%."] = "Resistência a fogo no máximo %s%%.",
  ["Ice Damage at most %s%%."] = "Dano de gelo no máximo %s%%.",
  ["Max Mana at most %s."] = "Mana máxima no máximo %s.",
  ["Ice Resistance at most %s%%."] = "Resistência a gelo no máximo %s%%.",
  ["Earth Damage at most %s%%."] = "Dano de terra no máximo %s%%.",
  ["Movement Speed at most %s%%."] = "Velocidade de movimento no máximo %s%%.",
  ["Earth Resistance at most %s%%."] = "Resistência a terra no máximo %s%%.",
  ["Critical Chance at most %s%%, Critical Hit at most %s%%."] = "Chance crítica no máximo %s%%, golpe crítico no máximo %s%%.",
  ["Death Resistance at most %s%%."] = "Resistência a morte no máximo %s%%.",
  ["Death Damage at most %s%%."] = "Dano de morte no máximo %s%%.",
  ["Attack Speed at most %s%%."] = "Velocidade de ataque no máximo %s%%.",
  ["Energy Resistance at most %s%%."] = "Resistência a energia no máximo %s%%.",
  ["Energy Damage at most %s%%."] = "Dano de energia no máximo %s%%.",
  ["Holy Damage at most %s%%."] = "Dano sagrado no máximo %s%%.",
  ["Elemental Resistances: spread over each elemental resistance, under their caps."] = "Resistências elementais: distribuídas entre cada resistência elemental, abaixo dos limites delas.",
  ["Holy Resistance at most %s%%."] = "Resistência sagrada no máximo %s%%.",
  ["Life Leech Chance at most %s%%, Life Leech Amount at most %s%%."] = "Chance de roubo de vida no máximo %s%%, quantidade de roubo de vida no máximo %s%%.",
  ["Physical Resistance at most %s%%."] = "Resistência física no máximo %s%%.",
  ["Physical Damage at most %s%%."] = "Dano físico no máximo %s%%.",
  ["Gear has %s to %s sockets: the lower of its kind's and its rarity's maximum. Uniques have %s fixed socket. Every orb keeps sockets and gems."] = "Equipamentos têm de %s a %s sockets: o menor entre o máximo do tipo e o da raridade. Uniques têm %s socket fixo. Todo orbe mantém sockets e gems.",
  ["Socket a gem by Use with on the gem, then click the item."] = "Coloque uma gem usando Usar com na gem e depois clique no item.",
  ["Rarity Find +%s%%"] = "Rarity find +%s%%",
  ["The base item's own stats (no extra stats of its own)."] = "Os atributos do próprio item base (sem atributos extras próprios).",
  ["Critical Hit: chance +%s%%, damage %s%%"] = "Golpe crítico: chance +%s%%, dano %s%%",
  ["Energy Absorb -%s%%"] = "Absorção de energia -%s%%",
  -- BEGIN GENERATED UNIQUE DESCRIPTIONS (server/tools/gen_unique_specs.py; do not edit by hand)
  ["A cage of rattling chains for what is left of a mind. Rattling Cage: Your spells deal %s%% more damage per %s maximum mana, up to %s%%. For: Mystic, Necromancer. (Requires level %s.)"] = "Uma jaula de correntes chacoalhantes para o que sobrou de uma mente. Rattling Cage: Seus magias causam %s%% a mais de dano a cada %s de mana máxima, até %s%%. Só para: Místico, Necromante. (Requer nível %s.)",
  ["A candle wick that never burns down, bound in iron and old prayers. Wick Surplus: At %s%% mana or more you deal %s%% more damage. At %s%% mana or less you deal %s%% less. For: Mystic, Necromancer. (Requires level %s.)"] = "Um pavio de vela que nunca se consome, preso em ferro e orações antigas. Wick Surplus: Com %s%% de mana ou mais você causa %s%% a mais de dano. Com %s%% de mana ou menos você causa %s%% a menos. Só para: Místico, Necromante. (Requer nível %s.)",
  ["A choir sang under it until the fire took the last voice. Sigil of Cinders: the sigil burns %s%% harder. Last Voice: On a kill, a holy nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Mystic, Templar. (Requires level %s.)"] = "Um coro cantou sob ele até o fogo levar a última voz. Sigil of Cinders: o sigilo queima %s%% mais forte. Last Voice: Em uma morte, uma nova de sagrado atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Místico, Templário. (Requer nível %s.)",
  ["A circlet of black glass that rains sparks in the wind. Rain of Sparks: On a critical hit, a energy nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Mystic, Necromancer. (Requires level %s.)"] = "Um diadema de vidro negro que chove faíscas ao vento. Rain of Sparks: Em um golpe crítico, uma nova de energia atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Místico, Necromante. (Requer nível %s.)",
  ["A claw of fire clamped around the finger. Claw of Fire: %s%% of your physical damage is dealt as fire and deals %s%% more. Other elements deal %s%% less. For: Warrior, Templar, Thief. (Requires level %s.) Part of the Embers of Aranoth set."] = "Uma garra de fogo presa ao dedo. Claw of Fire: %s%% do seu dano físico é causado como fogo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Guerreiro, Templário, Ladino. (Requer nível %s.) Parte do set Embers of Aranoth.",
  ["A coal from the last hall, still beating. Last Hall Ember: Each kill adds a stack for %s s, up to %s: %s%% more damage dealt per stack. Each stack also adds %s%% damage taken. For: Warrior, Thief, Monk. (Requires level %s.)"] = "Uma brasa do último salão, ainda pulsando. Last Hall Ember: Cada morte dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Cada acúmulo também soma %s%% de dano recebido. Só para: Guerreiro, Ladino, Monge. (Requer nível %s.)",
  ["A coal that never cools, hung where a heart should be. Never-Cooling Coal: Your melee hits deal %s%% more damage per %s maximum health, up to %s%%. For: Warrior, Templar, Monk. (Requires level %s.)"] = "Uma brasa que nunca esfria, pendurada onde devia haver um coração. Never-Cooling Coal: Seus golpes corpo a corpo causam %s%% a mais de dano a cada %s de vida máxima, até %s%%. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["A crown with nothing inside it. Wear it and it is still empty. Nothing Inside: At %s%% mana or more you deal %s%% more damage. At %s%% mana or less you deal %s%% less. For: Mystic, Necromancer. (Requires level %s.)"] = "Uma coroa sem nada dentro. Vista-a e ela continua vazia. Nothing Inside: Com %s%% de mana ou mais você causa %s%% a mais de dano. Com %s%% de mana ou menos você causa %s%% a menos. Só para: Místico, Necromante. (Requer nível %s.)",
  ["A face of hammered iron that smiles only when the wearer bleeds. Smiles When You Bleed: Critical hits deal %s%% more damage. Other hits deal %s%% less. A critical hit heals %s%% of its damage. For: Warrior, Thief. (Requires level %s.)"] = "Um rosto de ferro batido que só sorri quando quem o veste sangra. Smiles When You Bleed: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Um golpe crítico cura %s%% do seu dano. Só para: Guerreiro, Ladino. (Requer nível %s.)",
  ["A face that looks back. It has never blinked. Looks Back: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Mystic, Necromancer, Thief. (Requires level %s.)"] = "Um rosto que olha de volta. Nunca piscou. Looks Back: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Místico, Necromante, Ladino. (Requer nível %s.)",
  ["A flower that opens only after dark, and only once. Its venom is the petals. Opens Once After Dark: A monster that dies with your poison damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Thief. (Requires level %s.)"] = "Uma flor que só abre depois do escuro, e só uma vez. Seu veneno são as pétalas. Opens Once After Dark: Um monstro que morre com seu dano de veneno passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Ladino. (Requer nível %s.)",
  ["A hangman's design: it only needs one shot. One Shot: Targets at %s%% health or more take %s%% more damage from you. Targets at %s%% or less take %s%% less. For: Ranger. (Requires level %s.)"] = "Um projeto de carrasco: só precisa de um disparo. One Shot: Alvos com %s%% de vida ou mais sofrem %s%% a mais de dano seu. Alvos com %s%% ou menos sofrem %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["A hood that swallows the light around the face. Swallowed Light: Against one target alone you deal %s%% more damage. Among %s or more monsters you deal %s%% less. For: Thief, Monk. (Requires level %s.)"] = "Um capuz que engole a luz em volta do rosto. Swallowed Light: Contra um único alvo você causa %s%% a mais de dano. Entre %s ou mais monstros você causa %s%% a menos. Só para: Ladino, Monge. (Requer nível %s.)",
  ["A horn-ring from something that did not want to give it up. Horn-Bind: Each kill adds a stack for %s s, up to %s: %s%% more damage dealt per stack. Each stack also adds %s%% damage taken. For: Warrior, Templar. (Requires level %s.)"] = "Um anel de chifre de algo que não queria entregá-lo. Horn-Bind: Cada morte dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Cada acúmulo também soma %s%% de dano recebido. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["A lantern hook is still bolted to its rim, for nights on the road. Lantern Ward: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.)"] = "Um gancho de lanterna ainda está preso ao aro, para as noites na estrada. Lantern Ward: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["A moment cracked in two; one half keeps happening. Cascade Edge: the burst deals %s%% more of the critical hit and comes %s s sooner. Crack in Time: On a critical hit, a energy nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Thief, Monk, Ranger. (Requires level %s.)"] = "Um instante rachado em dois; uma metade continua acontecendo. Cascade Edge: a explosão causa %s%% a mais do golpe crítico e vem %s s mais cedo. Crack in Time: Em um golpe crítico, uma nova de energia atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ladino, Monge, Ranger. (Requer nível %s.)",
  ["A pilgrim carried it from the burnt chapel to the first town and never sheathed it again. Pilgrim's Resolve: Below %s%% health you deal %s%% more damage. For: Warrior, Templar, Monk. (Requires level %s.)"] = "Um peregrino o carregou da capela queimada até a primeira cidade e nunca mais o embainhou. Pilgrim's Resolve: Abaixo de %s%% de vida você causa %s%% a mais de dano. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["A promise made to the grave, kept in blood. Grave Vow: Below %s%% health you deal %s%% more damage. Above %s%% health you deal %s%% less. For: Thief, Monk, Necromancer. (Requires level %s.)"] = "Uma promessa feita à sepultura, cumprida em sangue. Grave Vow: Abaixo de %s%% de vida você causa %s%% a mais de dano. Acima de %s%% de vida você causa %s%% a menos. Só para: Ladino, Monge, Necromante. (Requer nível %s.)",
  ["A purse-cutter's blade, worn thin by a thousand clean strokes. Thieves swear two of them are better than one. Light Fingers: Each critical hit adds a stack for %s s, up to %s: %s%% more damage dealt per stack. For: Thief, Monk. (Requires level %s.)"] = "A lâmina de um cortador de bolsas, gasta por mil golpes limpos. Os ladrões juram que duas valem mais que uma. Light Fingers: Cada golpe crítico dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Só para: Ladino, Monge. (Requer nível %s.)",
  ["A ring of braided thorn; it pricks, and then it heals. Prick and Heal: Each kill restores %s%% of your maximum health, at most %s%% per second. Healing on you is %s%% lower. For: Ranger, Thief, Warrior. (Requires level %s.)"] = "Um anel de espinho trançado; fura, e depois cura. Prick and Heal: Cada morte restaura %s%% da sua vida máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. Só para: Ranger, Ladino, Guerreiro. (Requer nível %s.)",
  ["A ring with no front and no back. No Front No Back: Critical hits deal %s%% more damage. Other hits deal %s%% less. For: Mystic, Ranger. (Requires level %s.)"] = "Um anel sem frente e sem verso. No Front No Back: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Só para: Místico, Ranger. (Requer nível %s.)",
  ["A ripper's sabre, notched by a thousand slaughters. Notched Edge: A monster that dies with your bleeding damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Warrior, Thief. (Requires level %s.)"] = "Um sabre de estripador, entalhado por mil massacres. Notched Edge: Um monstro que morre com seu dano de sangramento passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Guerreiro, Ladino. (Requer nível %s.)",
  ["A saint walked into the pyre and did not stop; only the hand came back out. Saint Walked On: Below %s%% health you deal %s%% more damage. Above %s%% health you deal %s%% less. For: Monk. (Requires level %s, Monks only.)"] = "Um santo entrou na pira e não parou; só a mão voltou. Saint Walked On: Abaixo de %s%% de vida você causa %s%% a mais de dano. Acima de %s%% de vida você causa %s%% a menos. Só para: Monge. (Requer nível %s, apenas Monks.)",
  ["A shard of a star that fell and was cut loose from the sky. Cut Loose: Critical hits deal %s%% more damage. Other hits deal %s%% less. For: Warrior, Thief, Monk, Ranger, Mystic, Necromancer. (Requires level %s.)"] = "Um caco de estrela que caiu e foi solto do céu. Cut Loose: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Só para: Guerreiro, Ladino, Monge, Ranger, Místico, Necromante. (Requer nível %s.)",
  ["A single drop of the dark, held in black stone. Void Pool: %s%% of the damage monsters deal is paid from your mana instead, never below %s%% mana. Your direct hits deal %s%% less. For: Mystic, Necromancer, Monk. (Requires level %s.)"] = "Uma única gota do escuro, presa em pedra negra. Void Pool: %s%% do dano dos monstros é pago com sua mana, nunca abaixo de %s%% de mana. Seus golpes diretos causam %s%% a menos. Só para: Místico, Necromante, Monge. (Requer nível %s.)",
  ["A skull on a pole. The skull is grinning, the pole is not. Grinding Wheel: You deal %s%% more damage per other monster within %s tiles, up to %s. Alone you deal %s%% less. For: Warrior, Monk. (Requires level %s.)"] = "Uma caveira num poste. A caveira está sorrindo, o poste não. Grinding Wheel: Você causa %s%% a mais de dano por outro monstro a %s passos, até %s. Sozinho você causa %s%% a menos. Só para: Guerreiro, Monge. (Requer nível %s.)",
  ["A sun that burned out and kept its shape. Sun That Kept Its Shape: %s%% of your physical damage is dealt as holy and deals %s%% more. Other elements deal %s%% less. For: Ranger. (Requires level %s. Ranger line.)"] = "Um sol que se apagou e manteve a forma. Sun That Kept Its Shape: %s%% do seu dano físico é causado como sagrado e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["A tiny lantern with a moth inside that never stops beating its wings. Moth to Flame: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Mystic, Templar, Monk. (Requires level %s.)"] = "Uma lanterna minúscula com uma mariposa dentro que nunca para de bater as asas. Moth to Flame: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Místico, Templário, Monge. (Requer nível %s.)",
  ["A two-handed argument that ends all debate. Argument Ender: Targets at %s%% health or less take %s%% more damage from you. Targets at %s%% or more take %s%% less. For: Templar, Monk. (Requires level %s.)"] = "Um argumento de duas mãos que encerra qualquer debate. Argument Ender: Alvos com %s%% de vida ou menos sofrem %s%% a mais de dano seu. Alvos com %s%% ou mais sofrem %s%% a menos. Só para: Templário, Monge. (Requer nível %s.)",
  ["A vow made after the first dawn burned; it keeps its wearer for the second. Second Dawn: A hit that leaves you under %s%% health makes you take %s%% less damage for %s s, but blocks your healing meanwhile. Once per %s s. (Requires level %s.)"] = "Um voto feito depois que o primeiro amanhecer queimou; ele guarda quem o veste para o segundo. Second Dawn: Um golpe que deixa você abaixo de %s%% de vida faz você receber %s%% a menos de dano por %s s, mas bloqueia sua cura nesse tempo. Uma vez a cada %s s. (Requer nível %s.)",
  ["A wolf's skull for a helm. The pack smells you as kin. Pack Smells Kin: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Ranger, Necromancer. (Requires level %s.)"] = "Um crânio de lobo como elmo. A matilha sente você como um dos seus. Pack Smells Kin: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Ranger, Necromante. (Requer nível %s.)",
  ["An effigy's eye, set in crystal. Every curse you hear, it hears first. Every Curse First: A monster that dies with your death damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Mystic, Necromancer. (Requires level %s.)"] = "O olho de uma efígie, engastado em cristal. Toda maldição que você ouve, ele ouve primeiro. Every Curse First: Um monstro que morre com seu dano de morte passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Místico, Necromante. (Requer nível %s.)",
  ["Ash fills its seams and never falls out. (Ashen Sepulchre.) Ash in the Seams: Immune to burning. Direct fire damage you take is %s%% higher. For: Warrior, Templar, Monk, Thief, Ranger. (Requires level %s.)"] = "A cinza enche as suas juntas e nunca cai. (Ashen Sepulchre.) Ash in the Seams: Imune a queimadura. O dano direto de fogo que você recebe é %s%% maior. Só para: Guerreiro, Templário, Monge, Ladino, Ranger. (Requer nível %s.)",
  ["Bark and leather, stitched with living vine. Living Vine: A monster hit of %s%% of your health or more is answered with %s%% of it as earth damage, every %s s. For: Ranger, Thief, Warrior. (Requires level %s.)"] = "Casca e couro, costurados com videira viva. Living Vine: Um golpe de monstro de %s%% da sua vida ou mais é respondido com %s%% dele como dano de terra, a cada %s s. Só para: Ranger, Ladino, Guerreiro. (Requer nível %s.)",
  ["Beneath it, only a voice and a smell of old earth. Burial Linen: Your minions deal %s%% more damage and have %s%% more health. Your own spells deal %s%% less. For: Necromancer. (Requires level %s.)"] = "Debaixo dele, só uma voz e um cheiro de terra velha. Burial Linen: Seus lacaios causam %s%% a mais de dano e têm %s%% a mais de vida. Suas próprias magias causam %s%% a menos. Só para: Necromante. (Requer nível %s.)",
  ["Black glass drawn into a sleeve. It never holds fewer than you need. Never Fewer Than You Need: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s. Ranger line.)"] = "Vidro negro puxado para dentro de uma manga. Nunca guarda menos do que você precisa. Never Fewer Than You Need: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["Black on black; blades slide off it like water. Blades Slide Off: A monster hit of %s%% of your health or more is answered with %s%% of it as physical damage, every %s s. For: Thief, Monk. (Requires level %s.)"] = "Preto sobre preto; lâminas escorregam nele como água. Blades Slide Off: Um golpe de monstro de %s%% da sua vida ou mais é respondido com %s%% dele como dano de físico, a cada %s s. Só para: Ladino, Monge. (Requer nível %s.)",
  ["Bone-white and cold; the eyes behind it go dark. (Ember Descent.) Eyes Go Dark: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Necromancer, Mystic. (Requires level %s.)"] = "Branca como osso e fria; os olhos por trás dela se apagam. (Ember Descent.) Eyes Go Dark: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Necromante, Místico. (Requer nível %s.)",
  ["Bound with cord that still glows at the knots. Glow at the Knots: %s%% of your physical damage is dealt as fire and deals %s%% more. Other elements deal %s%% less. For: Ranger. (Requires level %s. Ranger line.)"] = "Amarrado com uma corda que ainda brilha nos nós. Glow at the Knots: %s%% do seu dano físico é causado como fogo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["Briar wood that still grows a thorn after every shot. Briar Shot: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s.)"] = "Madeira de sarça que ainda faz nascer um espinho depois de cada disparo. Briar Shot: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s.)",
  ["Carried by the ones who walked in, and by the ones who walked out. Walked In Walked Out: A hit that leaves you under %s%% health makes you take %s%% less damage for %s s, but blocks your healing meanwhile. Once per %s s. (Requires level %s.)"] = "Carregado por quem entrou e por quem saiu. Walked In Walked Out: Um golpe que deixa você abaixo de %s%% de vida faz você receber %s%% a menos de dano por %s s, mas bloqueia sua cura nesse tempo. Uma vez a cada %s s. (Requer nível %s.)",
  ["Carried out of the burning hall by the one who put the Tyrant down. Put the Tyrant Down: Targets at %s%% health or less take %s%% more damage from you. Targets at %s%% or more take %s%% less. For: Warrior, Templar. (Requires level %s.)"] = "Carregado para fora do salão em chamas por quem derrubou o Tirano. Put the Tyrant Down: Alvos com %s%% de vida ou menos sofrem %s%% a mais de dano seu. Alvos com %s%% ou mais sofrem %s%% a menos. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Cold enough to crack what it touches, and what that touches. Winter's Lattice: shatters deal %s%% more of the maximum health and reach %s sqm further. Rime Heart: %s%% of your physical damage is dealt as ice and deals %s%% more. Other elements deal %s%% less. For: Warrior. (Requires level %s.)"] = "Frio o bastante para rachar o que toca, e o que isso toca. Winter's Lattice: estilhaços causam %s%% a mais da vida máxima e alcançam %s sqm a mais. Rime Heart: %s%% do seu dano físico é causado como gelo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Guerreiro. (Requer nível %s.)",
  ["Cut from a coat that outlived its owner and every wind he rode. Gale Sleeve: Each critical hit adds a stack for %s s, up to %s: %s%% more damage dealt per stack. Each stack also adds %s%% damage taken. For: Ranger. (Requires level %s. Ranger line.)"] = "Cortado de um casaco que sobreviveu ao dono e a todos os ventos que ele cavalgou. Gale Sleeve: Cada golpe crítico dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Cada acúmulo também soma %s%% de dano recebido. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["Cut from a giant that walked into its own pyre and did not stop. Pyre Oath: your burning aura deals %s%% more. Giant's Pyre: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.)"] = "Talhado de um gigante que entrou na própria pira e não parou. Pyre Oath: sua aura de queimadura causa %s%% a mais. Giant's Pyre: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Cut from a tree that grew in a graveyard and never once bloomed. Hollow Bark: Immune to poison. Direct poison damage you take is %s%% higher. For: Ranger, Mystic, Necromancer. (Requires level %s.)"] = "Talhado de uma árvore que cresceu num cemitério e nunca floresceu. Hollow Bark: Imune a veneno. O dano direto de veneno que você recebe é %s%% maior. Só para: Ranger, Místico, Necromante. (Requer nível %s.)",
  ["Cut from the gallows beam of a village the moon forgot to leave. Gallows Beam: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Ranger. (Requires level %s.)"] = "Talhada da viga da forca de uma vila que a lua esqueceu de deixar. Gallows Beam: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["Do not read it aloud. It will answer. Answering Voice: At %s%% mana or more you deal %s%% more damage. At %s%% mana or less you deal %s%% less. For: Mystic, Necromancer. (Requires level %s.)"] = "Não leia em voz alta. Ele vai responder. Answering Voice: Com %s%% de mana ou mais você causa %s%% a mais de dano. Com %s%% de mana ou menos você causa %s%% a menos. Só para: Místico, Necromante. (Requer nível %s.)",
  ["Dyed in the blood of the road they walked. Road of Blood: Your hits deal %s%% more damage per %s speed above %s, up to %s%%. For: Warrior, Thief, Ranger. (Requires level %s.) Part of the Embers of Aranoth set."] = "Tingidas no sangue da estrada que percorreram. Road of Blood: Seus golpes causam %s%% a mais de dano a cada %s de velocidade acima de %s, até %s%%. Só para: Guerreiro, Ladino, Ranger. (Requer nível %s.) Parte do set Embers of Aranoth.",
  ["Dyed in the juice of berries nobody should eat. Berry Juice: A monster that dies with your poison damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Thief, Ranger. (Requires level %s.)"] = "Tingido com o suco de frutas que ninguém deveria comer. Berry Juice: Um monstro que morre com seu dano de veneno passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Ladino, Ranger. (Requer nível %s.)",
  ["Each beat is a drop of someone else's life. Borrowed Beat: Each kill restores %s%% of your maximum health, at most %s%% per second. Healing on you is %s%% lower. For: Warrior, Necromancer, Templar. (Requires level %s.)"] = "Cada batida é uma gota da vida de outra pessoa. Borrowed Beat: Cada morte restaura %s%% da sua vida máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. Só para: Guerreiro, Necromante, Templário. (Requer nível %s.)",
  ["Each ember in it was a crown once. Each Ember a Crown: On a monster hit of %s%% of your health or more, a fire nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. For: Warrior, Templar, Mystic, Necromancer. (Requires level %s.)"] = "Cada brasa nele já foi uma coroa. Each Ember a Crown: Em um golpe de monstro de %s%% da sua vida ou mais, uma nova de fogo atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Só para: Guerreiro, Templário, Místico, Necromante. (Requer nível %s.)",
  ["Each ring of the mail was sworn on a separate wound. Sworn on a Wound: Each kill adds a stack for %s s, up to %s: %s%% more damage dealt per stack. Each stack also adds %s%% damage taken. For: Warrior, Templar. (Requires level %s.)"] = "Cada anel da cota foi jurado sobre uma ferida diferente. Sworn on a Wound: Cada morte dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Cada acúmulo também soma %s%% de dano recebido. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Each step leaves a warm print in the ash. Warm Print: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Templar, Monk, Mystic. (Requires level %s.) Part of the Embers of Aranoth set."] = "Cada passo deixa uma marca quente na cinza. Warm Print: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Templário, Monge, Místico. (Requer nível %s.) Parte do set Embers of Aranoth.",
  ["Eight pyres burned out before this one. It does not mean to. Eight Pyres Before: On a kill, a fire nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Mystic, Necromancer. (Requires level %s.)"] = "Oito piras se apagaram antes desta. Ela não pretende se apagar. Eight Pyres Before: Em uma morte, uma nova de fogo atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Místico, Necromante. (Requer nível %s.)",
  ["Embroidered with the same storm in fire and in frost. Same Storm Twice: %s%% of the damage monsters deal is paid from your mana instead, never below %s%% mana. Your direct hits deal %s%% less. For: Mystic, Necromancer. (Requires level %s.)"] = "Bordado com a mesma tempestade em fogo e em gelo. Same Storm Twice: %s%% do dano dos monstros é pago com sua mana, nunca abaixo de %s%% de mana. Seus golpes diretos causam %s%% a menos. Só para: Místico, Necromante. (Requer nível %s.)",
  ["Every arrow leaves it with a sigh. Wind-Borne: Against one target alone you deal %s%% more damage. Among %s or more monsters you deal %s%% less. For: Ranger. (Requires level %s. Ranger line.)"] = "Toda flecha sai dele com um suspiro. Wind-Borne: Contra um único alvo você causa %s%% a mais de dano. Entre %s ou mais monstros você causa %s%% a menos. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["Every dent in it was paid back. Thornbound Oath: you reflect %s%% more. Paid In Full: A monster hit of %s%% of your health or more is answered with %s%% of it as physical damage, every %s s. For: Warrior, Templar. (Requires level %s.)"] = "Cada amassado nela foi pago de volta. Thornbound Oath: você reflete %s%% a mais. Paid In Full: Um golpe de monstro de %s%% da sua vida ou mais é respondido com %s%% dele como dano de físico, a cada %s s. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Every page is a different way to burn a finger. Small Fires: On a kill, a fire nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. For: Mystic, Necromancer. (Requires level %s. Mystic and Necromancer lines.)"] = "Cada página é um jeito diferente de queimar um dedo. Small Fires: Em uma morte, uma nova de fogo atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Só para: Místico, Necromante. (Requer nível %s. Linhas Mystic e Necromancer.)",
  ["Every page shows the reader, a moment later. Every Page Shows the Reader: Your spells send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% mana. For: Mystic, Necromancer. (Requires level %s.)"] = "Cada página mostra o leitor, um instante depois. Every Page Shows the Reader: Seus magias enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de mana. Só para: Místico, Necromante. (Requer nível %s.)",
  ["Every road ends somewhere. These have not found where. Endless Road: Your hits deal %s%% more damage per %s speed above %s, up to %s%%. For: Warrior, Ranger, Thief, Monk. (Requires level %s.)"] = "Toda estrada termina em algum lugar. Estas ainda não acharam onde. Endless Road: Seus golpes causam %s%% a mais de dano a cada %s de velocidade acima de %s, até %s%%. Só para: Guerreiro, Ranger, Ladino, Monge. (Requer nível %s.)",
  ["Every shaft is a star that was not allowed to set. Not Allowed to Set: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s. Ranger line.)"] = "Cada haste é uma estrela que não teve permissão de se pôr. Not Allowed to Set: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["Every soul it cuts only feeds the hunger of its blade. Hungry Blade: Each kill restores %s%% of your maximum health, at most %s%% per second. Healing on you is %s%% lower. For: Warrior, Thief, Necromancer. (Requires level %s.)"] = "Cada alma que ela corta só alimenta a fome da sua lâmina. Hungry Blade: Cada morte restaura %s%% da sua vida máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. Só para: Guerreiro, Ladino, Necromante. (Requer nível %s.)",
  ["Every step leaves something behind. Snares: one more trap may be out, traps arm %s s sooner and hit %s%% harder. Footfall Debt: Each critical hit adds a stack for %s s, up to %s: %s%% more damage dealt per stack. Each stack also adds %s%% damage taken. For: Ranger, Thief. (Requires level %s. Ranger and Thief lines.)"] = "Cada passo deixa algo para trás. Snares: mais uma armadilha pode ficar ativa, as armadilhas armam %s s mais cedo e acertam %s%% mais forte. Footfall Debt: Cada golpe crítico dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Cada acúmulo também soma %s%% de dano recebido. Só para: Ranger, Ladino. (Requer nível %s. Linhas Ranger e Thief.)",
  ["Forged in the grave of a wyrm, quenched in what was left of it. Wyrm Quench: A monster that dies with your bleeding damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Warrior, Thief, Monk, Templar. (Requires level %s.)"] = "Forjada na tumba de um wyrm, temperada no que sobrou dele. Wyrm Quench: Um monstro que morre com seu dano de sangramento passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Guerreiro, Ladino, Monge, Templário. (Requer nível %s.)",
  ["Forged under a crimson moon; it never dries. Crimson Tide: Critical hits deal %s%% more damage. Other hits deal %s%% less. A critical hit heals %s%% of its damage. For: Warrior, Thief. (Requires level %s.)"] = "Forjado sob uma lua carmesim; nunca seca. Crimson Tide: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Um golpe crítico cura %s%% do seu dano. Só para: Guerreiro, Ladino. (Requer nível %s.)",
  ["Frost still sleeps in the bite of it, a winter older than the cinders. Winter Bite: %s%% of your physical damage is dealt as ice and deals %s%% more. Other elements deal %s%% less. For: Warrior, Templar. (Requires level %s.)"] = "A geada ainda dorme em sua mordida, um inverno mais velho que as brasas. Winter Bite: %s%% do seu dano físico é causado como gelo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Furs of every beast that ever ran with the covenant. Covenant Furs: You deal %s%% more damage per other monster within %s tiles, up to %s. Alone you deal %s%% less. For: Ranger, Warrior, Necromancer. (Requires level %s.)"] = "Peles de toda fera que já correu com o pacto. Covenant Furs: Você causa %s%% a mais de dano por outro monstro a %s passos, até %s. Sozinho você causa %s%% a menos. Só para: Ranger, Guerreiro, Necromante. (Requer nível %s.)",
  ["Gauntlets from a morning that never came. They still reach for it. Morning That Never Came: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. %s%% of what it absorbs is dealt back. Healing on you is %s%% lower. For: Monk. (Requires level %s, Monks only.)"] = "Manoplas de uma manhã que nunca veio. Elas ainda tentam alcançá-la. Morning That Never Came: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. %s%% do que ela absorve volta ao atacante. A cura que você recebe é %s%% menor. Só para: Monge. (Requer nível %s, apenas Monks.)",
  ["Grave linen bound with a cord of hair. (Ember Descent.) Cord of Hair: Your minions deal %s%% more damage and have %s%% more health. Your own spells deal %s%% less. For: Necromancer. (Requires level %s.)"] = "Linho de sepultura preso por um cordão de cabelo. (Ember Descent.) Cord of Hair: Seus lacaios causam %s%% a mais de dano e têm %s%% a mais de vida. Suas próprias magias causam %s%% a menos. Só para: Necromante. (Requer nível %s.)",
  ["Half ember, half hoarfrost; it hisses when it is drawn. Hisses When Drawn: %s%% of your physical damage is dealt as fire and deals %s%% more. Other elements deal %s%% less. For: Warrior. (Requires level %s.)"] = "Meio brasa, meio geada; chia quando é sacado. Hisses When Drawn: %s%% do seu dano físico é causado como fogo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Guerreiro. (Requer nível %s.)",
  ["Hewn from a dying star; the haft is always warm. Dying Star: %s%% of your physical damage is dealt as fire and deals %s%% more. Other elements deal %s%% less. For: Warrior, Templar. (Requires level %s.)"] = "Talhado de uma estrela moribunda; o cabo está sempre quente. Dying Star: %s%% do seu dano físico é causado como fogo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Hold it up and the fire has to ask permission. Fire Asks Permission: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. %s%% of what it absorbs is dealt back. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.) Part of the Embers of Aranoth set."] = "Levante-o e o fogo precisa pedir licença. Fire Asks Permission: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. %s%% do que ela absorve volta ao atacante. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.) Parte do set Embers of Aranoth.",
  ["Hurled by the damned at those who would leave. Damned Flight: %s%% of your physical damage is dealt as fire and deals %s%% more. Other elements deal %s%% less. For: Ranger, Thief. (Requires level %s.)"] = "Arremessada pelos condenados contra quem quer partir. Damned Flight: %s%% do seu dano físico é causado como fogo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Ranger, Ladino. (Requer nível %s.)",
  ["It drinks first and lets you have the rest. Sanguine Covenant: you leech %s%% more, and up to %s%% more of your maximum health a second. Drinks First: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. Healing on you is %s%% lower. (Requires level %s.)"] = "Ela bebe primeiro e deixa o resto para você. Sanguine Covenant: você rouba %s%% a mais, e até %s%% a mais da sua vida máxima por segundo. Drinks First: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. A cura que você recebe é %s%% menor. (Requer nível %s.)",
  ["It has reaped countless souls and still wants a few more. Reaper's Reach: Your melee hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Warrior, Templar. (Requires level %s.)"] = "Ela já ceifou incontáveis almas e ainda quer algumas mais. Reaper's Reach: Seus golpes corpo a corpo enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["It howls when swung, and the embers answer from far away. Embers Answer: %s%% of your physical damage is dealt as fire and deals %s%% more. Other elements deal %s%% less. For: Warrior, Templar. (Requires level %s.)"] = "Ele uiva quando é brandido, e as brasas respondem de longe. Embers Answer: %s%% do seu dano físico é causado como fogo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["It moves a heartbeat before the wearer does. Heartbeat Early: Each hit in a row on one target deals %s%% more, up to %s hits. The first hit on a new target deals %s%% less. For: Mystic, Ranger. (Requires level %s.)"] = "Ele se move um batimento antes de quem o veste. Heartbeat Early: Cada golpe seguido no mesmo alvo causa %s%% a mais, até %s golpes. O primeiro golpe em um alvo novo causa %s%% a menos. Só para: Místico, Ranger. (Requer nível %s.)",
  ["It opens onto a very small, very patient fire. Small Patient Fire: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Templar, Mystic, Monk. (Requires level %s.)"] = "Ele se abre para um fogo muito pequeno e muito paciente. Small Patient Fire: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Templário, Místico, Monge. (Requer nível %s.)",
  ["It ticks when no one is listening. Snares: two more mines may be out, they hit %s%% harder and their fuse burns %s s longer. Slow Burn: A monster that dies with your fire damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Ranger, Thief. (Requires level %s. Ranger and Thief lines.)"] = "Ele tiquetaqueia quando ninguém escuta. Snares: mais duas minas podem ficar ativas, elas acertam %s%% mais forte e o pavio queima %s s a mais. Slow Burn: Um monstro que morre com seu dano de fogo passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Ranger, Ladino. (Requer nível %s. Linhas Ranger e Thief.)",
  ["It watches you from the inside of your own skull. Evil Eye: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Mystic, Necromancer, Ranger. (Requires level %s.)"] = "Ele observa você de dentro do seu próprio crânio. Evil Eye: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Místico, Necromante, Ranger. (Requer nível %s.)",
  ["It weaves the last light of day into a shroud. Last-Light Shroud: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Mystic, Templar, Monk. (Requires level %s.)"] = "Ele tece a última luz do dia numa mortalha. Last-Light Shroud: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Místico, Templário, Monge. (Requer nível %s.)",
  ["It whispers the names of the burned, one by one, all night. (Ember Descent.) Names of the Burned: A monster that dies with your death damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Necromancer. (Requires level %s.)"] = "Ela sussurra os nomes dos queimados, um por um, a noite toda. (Ember Descent.) Names of the Burned: Um monstro que morre com seu dano de morte passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Necromante. (Requer nível %s.)",
  ["Its bolts come back with the tide, and bring something with them. Tide Brings Something: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Ranger. (Requires level %s.)"] = "Seus virotes voltam com a maré e trazem algo consigo. Tide Brings Something: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["Its bolts scream on the way down. Screaming Bolts: Critical hits deal %s%% more damage. Other hits deal %s%% less. For: Ranger. (Requires level %s.)"] = "Seus virotes gritam na descida. Screaming Bolts: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["Its edge was quenched in the Blood Colossus's altar and never quite dried. Altar Quench: Below %s%% health you deal %s%% more damage. Above %s%% health you deal %s%% less. For: Warrior. (Requires level %s.)"] = "Sua lâmina foi temperada no altar do Colosso de Sangue e nunca secou por completo. Altar Quench: Abaixo de %s%% de vida você causa %s%% a mais de dano. Acima de %s%% de vida você causa %s%% a menos. Só para: Guerreiro. (Requer nível %s.)",
  ["Its head was cast from a chapel bell; it still rings when it lands. Bell Toll: You deal %s%% more damage per other monster within %s tiles, up to %s. Alone you deal %s%% less. For: Templar, Monk. (Requires level %s.)"] = "Sua cabeça foi fundida de um sino de capela; ainda toca quando acerta. Bell Toll: Você causa %s%% a mais de dano por outro monstro a %s passos, até %s. Sozinho você causa %s%% a menos. Só para: Templário, Monge. (Requer nível %s.)",
  ["Its hem is always smouldering, and never burnt. Never Burnt: Immune to burning. Direct fire damage you take is %s%% higher. For: Mystic, Necromancer, Templar. (Requires level %s.)"] = "Sua barra está sempre em brasa, e nunca queimada. Never Burnt: Imune a queimadura. O dano direto de fogo que você recebe é %s%% maior. Só para: Místico, Necromante, Templário. (Requer nível %s.)",
  ["Its pages are carved, not written. Effigy Covenant: one more effigy may stand. Carver's Patience: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. Healing on you is %s%% lower. For: Mystic, Necromancer. (Requires level %s.)"] = "Suas páginas são entalhadas, não escritas. Effigy Covenant: mais uma efígie pode ficar de pé. Carver's Patience: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. A cura que você recebe é %s%% menor. Só para: Místico, Necromante. (Requer nível %s.)",
  ["Its smoke kneels before it rises. Reliquary Vow: your Reliquary Warden pulses %s%% stronger. Kneeling Smoke: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Templar, Mystic, Monk. (Requires level %s.)"] = "Sua fumaça se ajoelha antes de subir. Reliquary Vow: seu Reliquary Warden pulsa %s%% mais forte. Kneeling Smoke: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Templário, Místico, Monge. (Requer nível %s.)",
  ["Its string is a strand of the storm that drowned the herald. Strand of the Storm: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s.)"] = "Sua corda é um fio da tempestade que afogou o arauto. Strand of the Storm: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s.)",
  ["Its string was a hangman's rope. It still pulls tight on its own. Hangman's Rope: Targets at %s%% health or more take %s%% more damage from you. Targets at %s%% or less take %s%% less. For: Ranger. (Requires level %s.)"] = "Sua corda foi a corda de um carrasco. Ainda se aperta sozinha. Hangman's Rope: Alvos com %s%% de vida ou mais sofrem %s%% a mais de dano seu. Alvos com %s%% ou menos sofrem %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["Knuckles cast from the hinges of a chapel door that would not stay shut. Door-Hinge Counter: A monster hit of %s%% of your health or more is answered with %s%% of it as physical damage, every %s s. For: Monk. (Requires level %s, Monks only.)"] = "Soqueiras fundidas das dobradiças de uma porta de capela que não ficava fechada. Door-Hinge Counter: Um golpe de monstro de %s%% da sua vida ou mais é respondido com %s%% dele como dano de físico, a cada %s s. Só para: Monge. (Requer nível %s, apenas Monks.)",
  ["Light enough for a court mage, warm enough for a pyre. Court Mage's Pace: Your hits deal %s%% more damage per %s magic level, up to %s%%. For: Warrior, Monk, Templar. (Requires level %s.)"] = "Leve o bastante para um mago da corte, quente o bastante para uma pira. Court Mage's Pace: Seus golpes causam %s%% a mais de dano a cada %s de nível mágico, até %s%%. Só para: Guerreiro, Monge, Templário. (Requer nível %s.)",
  ["Light enough to run in. Loud enough to be followed. Reed Whistle: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s. Ranger line.)"] = "Leve o bastante para correr. Barulhenta o bastante para ser seguida. Reed Whistle: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["Light passes through it and comes out colder. Energy shield: recharges %s%% of its maximum a second faster and starts %s s after a hit, with or without Hollow Vessel. Cold Light: %s%% of the damage monsters deal is paid from your mana instead, never below %s%% mana. Your direct hits deal %s%% less. For: Mystic, Necromancer, Monk, Templar. (Requires level %s. Mystic, Necromancer, Monk and Templar lines.)"] = "A luz passa por ela e sai mais fria. Escudo de energia: recarrega %s%% do máximo por segundo mais rápido e começa %s s depois de um golpe, com ou sem Hollow Vessel. Cold Light: %s%% do dano dos monstros é pago com sua mana, nunca abaixo de %s%% de mana. Seus golpes diretos causam %s%% a menos. Só para: Místico, Necromante, Monge, Templário. (Requer nível %s. Linhas Mystic, Necromancer, Monk e Templar.)",
  ["Light, black and covered in grinning faces. Skull Pall: Immune to poison. Direct poison damage you take is %s%% higher. For: Thief, Ranger, Monk. (Requires level %s.)"] = "Leve, negro e coberto de rostos sorridentes. Skull Pall: Imune a veneno. O dano direto de veneno que você recebe é %s%% maior. Só para: Ladino, Ranger, Monge. (Requer nível %s.)",
  ["Long, dark and quiet; the pockets hold one bolt each. One Bolt per Pocket: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s.)"] = "Longa, escura e silenciosa; cada bolso guarda um virote. One Bolt per Pocket: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s.)",
  ["Made for standing still a long time on a cold scaffold. Standing Still: Each hit in a row on one target deals %s%% more, up to %s hits. The first hit on a new target deals %s%% less. For: Ranger, Mystic. (Requires level %s.)"] = "Feitas para ficar muito tempo paradas num cadafalso frio. Standing Still: Cada golpe seguido no mesmo alvo causa %s%% a mais, até %s golpes. O primeiro golpe em um alvo novo causa %s%% a menos. Só para: Ranger, Místico. (Requer nível %s.)",
  ["Nine doors, nine boons, one ring to show for them. Nine Boons: Each kill adds a stack for %s s, up to %s: %s%% more damage dealt per stack. Each stack also adds %s%% damage taken. For: Warrior, Thief, Monk, Ranger. (Requires level %s.)"] = "Nove portas, nove bênçãos, um anel para mostrar por elas. Nine Boons: Cada morte dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Cada acúmulo também soma %s%% de dano recebido. Só para: Guerreiro, Ladino, Monge, Ranger. (Requer nível %s.)",
  ["No king sits the hollow throne. The blade keeps the seat warm. Seat Kept Warm: Below %s%% health you deal %s%% more damage. Above %s%% health you deal %s%% less. For: Warrior, Templar. (Requires level %s.)"] = "Nenhum rei ocupa o trono oco. A lâmina mantém o assento aquecido. Seat Kept Warm: Abaixo de %s%% de vida você causa %s%% a mais de dano. Acima de %s%% de vida você causa %s%% a menos. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["No one sits there. Everyone bows. Everyone Bows: %s%% of the damage monsters deal is paid from your mana instead, never below %s%% mana. Your direct hits deal %s%% less. For: Mystic, Necromancer, Monk, Templar. (Requires level %s.)"] = "Ninguém se senta ali. Todos se curvam. Everyone Bows: %s%% do dano dos monstros é pago com sua mana, nunca abaixo de %s%% de mana. Seus golpes diretos causam %s%% a menos. Só para: Místico, Necromante, Monge, Templário. (Requer nível %s.)",
  ["One spark left. Make it count. One Spark: A hit that leaves you under %s%% health makes you take %s%% less damage for %s s, but blocks your healing meanwhile. Once per %s s. (Requires level %s.)"] = "Resta uma faísca. Faça-a valer. One Spark: Um golpe que deixa você abaixo de %s%% de vida faz você receber %s%% a menos de dano por %s s, mas bloqueia sua cura nesse tempo. Uma vez a cada %s s. (Requer nível %s.)",
  ["One tooth for every pact kept. One Tooth per Pact: Your minions deal %s%% more damage and have %s%% more health. Your own spells deal %s%% less. For: Necromancer. (Requires level %s.)"] = "Um dente para cada pacto cumprido. One Tooth per Pact: Seus lacaios causam %s%% a mais de dano e têm %s%% a mais de vida. Suas próprias magias causam %s%% a menos. Só para: Necromante. (Requer nível %s.)",
  ["Patched at every inn between the coast and the cinder fields. Road Rations: Each kill restores %s%% of your maximum health, at most %s%% per second. Healing on you is %s%% lower. For: Warrior, Ranger, Thief. (Requires level %s.)"] = "Remendada em cada estalagem entre a costa e os campos de brasa. Road Rations: Cada morte restaura %s%% da sua vida máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. Só para: Guerreiro, Ranger, Ladino. (Requer nível %s.)",
  ["Pilgrims of the pyre wore these on the road; the ash on it is still warm. Pilgrim's Pyre: On a monster hit of %s%% of your health or more, a fire nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. For: Mystic, Templar, Necromancer. (Requires level %s.)"] = "Peregrinos da pira as usavam na estrada; a cinza nelas ainda está quente. Pilgrim's Pyre: Em um golpe de monstro de %s%% da sua vida ou mais, uma nova de fogo atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Só para: Místico, Templário, Necromante. (Requer nível %s.)",
  ["Plate that remembers the hand that wore it. The hand still moves. Remembering Hand: A monster hit of %s%% of your health or more is answered with %s%% of it as death damage, every %s s. For: Warrior, Templar, Monk. (Requires level %s.)"] = "Placas que lembram da mão que as vestiu. A mão ainda se mexe. Remembering Hand: Um golpe de monstro de %s%% da sua vida ou mais é respondido com %s%% dele como dano de morte, a cada %s s. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["Plated with the Colossus's own bones. They creak when you stand still. Creak and Hold: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Warrior, Templar, Monk. (Requires level %s.)"] = "Revestidas com os ossos do próprio Colosso. Rangem quando você fica parado. Creak and Hold: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["Plated with what the void spat back out. Spat Back: Immune to death damage over time. Direct death damage you take is %s%% higher. (Requires level %s.)"] = "Revestida com o que o vazio cuspiu de volta. Spat Back: Imune a dano de morte contínuo. O dano direto de morte que você recebe é %s%% maior. (Requer nível %s.)",
  ["Plates that tighten when blood runs down them. Tightening Plates: Each kill restores %s%% of your maximum health, at most %s%% per second. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.)"] = "Placas que apertam quando o sangue escorre por elas. Tightening Plates: Cada morte restaura %s%% da sua vida máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Polished black glass; it reflects what you fear. Reflected Fear: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.)"] = "Vidro negro polido; reflete o que você teme. Reflected Fear: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Put it on and the living stop being able to find you. Unfound: Below %s%% health you deal %s%% more damage. Above %s%% health you deal %s%% less. For: Thief, Mystic, Necromancer. (Requires level %s.)"] = "Vista-o e os vivos deixam de conseguir encontrar você. Unfound: Abaixo de %s%% de vida você causa %s%% a mais de dano. Acima de %s%% de vida você causa %s%% a menos. Só para: Ladino, Místico, Necromante. (Requer nível %s.)",
  ["Quenched in the ninth hall of the Descent; it still glows where the embers bit. Ninth Hall Quench: Below %s%% health you deal %s%% more damage. Above %s%% health you deal %s%% less. For: Warrior, Templar. (Requires level %s.)"] = "Temperada no nono salão da Descent; ainda brilha onde as brasas morderam. Ninth Hall Quench: Abaixo de %s%% de vida você causa %s%% a mais de dano. Acima de %s%% de vida você causa %s%% a menos. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Quick as a whisper in the crypt, and as final. Crypt Whisper: Critical hits deal %s%% more damage. Other hits deal %s%% less. For: Thief. (Requires level %s.)"] = "Rápida como um sussurro na cripta, e tão final quanto. Crypt Whisper: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Só para: Ladino. (Requer nível %s.)",
  ["Quiet work for a quiet grave. It asks only for a twin in the other hand. Quiet Work: Critical hits deal %s%% more damage. Other hits deal %s%% less. A critical hit heals %s%% of its damage. For: Thief. (Requires level %s.)"] = "Trabalho quieto para uma tumba quieta. Pede apenas uma gêmea na outra mão. Quiet Work: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Um golpe crítico cura %s%% do seu dano. Só para: Ladino. (Requer nível %s.)",
  ["Scales shed by something that lives between the stars. Between Stars: Immune to energy damage over time. Direct energy damage you take is %s%% higher. For: Mystic, Necromancer, Monk. (Requires level %s.)"] = "Escamas largadas por algo que vive entre as estrelas. Between Stars: Imune a dano de energia contínuo. O dano direto de energia que você recebe é %s%% maior. Só para: Místico, Necromante, Monge. (Requer nível %s.)",
  ["Scorched black on the front, untouched on the back: everything behind it lived. (Ashen Sepulchre.) Everything Behind Lived: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. %s%% of what it absorbs is dealt back. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.)"] = "Chamuscado de preto na frente, intacto atrás: tudo o que estava atrás dele viveu. (Ashen Sepulchre.) Everything Behind Lived: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. %s%% do que ela absorve volta ao atacante. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Sewn the night before the first hunt. It smells of rain. First Quarry: Targets at %s%% health or more take %s%% more damage from you. For: Ranger. (Requires level %s. Ranger line.)"] = "Costurada na noite antes da primeira caçada. Cheira a chuva. First Quarry: Alvos com %s%% de vida ou mais sofrem %s%% a mais de dano seu. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["Silver that remembers the moon. It slips between ribs like a whisper. Silver Whisper: Targets at %s%% health or more take %s%% more damage from you. Targets at %s%% or less take %s%% less. For: Thief. (Requires level %s.)"] = "Prata que lembra da lua. Escorrega entre as costelas como um sussurro. Silver Whisper: Alvos com %s%% de vida ou mais sofrem %s%% a mais de dano seu. Alvos com %s%% ou menos sofrem %s%% a menos. Só para: Ladino. (Requer nível %s.)",
  ["Silver threads that catch light that is not there. Light That Is Not There: At %s%% mana or more you deal %s%% more damage. At %s%% mana or less you deal %s%% less. For: Mystic, Necromancer. (Requires level %s.)"] = "Fios de prata que capturam uma luz que não existe. Light That Is Not There: Com %s%% de mana ou mais você causa %s%% a mais de dano. Com %s%% de mana ou menos você causa %s%% a menos. Só para: Místico, Necromante. (Requer nível %s.)",
  ["Singed at the seams, it still smoulders when no one is looking. Cinder Coat: Immune to burning. Direct fire damage you take is %s%% higher. For: Warrior, Templar, Monk, Thief, Ranger. (Requires level %s.) Part of the Embers of Aranoth set."] = "Chamuscada nas costuras, ainda arde em brasa quando ninguém olha. Cinder Coat: Imune a queimadura. O dano direto de fogo que você recebe é %s%% maior. Só para: Guerreiro, Templário, Monge, Ladino, Ranger. (Requer nível %s.) Parte do set Embers of Aranoth.",
  ["Slim, patient and well-used; its owners all died young. Widow's Patience: Each hit in a row on one target deals %s%% more, up to %s hits. The first hit on a new target deals %s%% less. For: Thief, Monk, Warrior. (Requires level %s.)"] = "Esguia, paciente e muito usada; todos os seus donos morreram jovens. Widow's Patience: Cada golpe seguido no mesmo alvo causa %s%% a mais, até %s golpes. O primeiro golpe em um alvo novo causa %s%% a menos. Só para: Ladino, Monge, Guerreiro. (Requer nível %s.)",
  ["Something inside it is still alive, and hungry. (Ember Descent.) Alive and Hungry: Each kill restores %s%% of your maximum health, at most %s%% per second. Healing on you is %s%% lower. For: Necromancer. (Requires level %s.)"] = "Algo dentro dela ainda está vivo, e faminto. (Ember Descent.) Alive and Hungry: Cada morte restaura %s%% da sua vida máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. Só para: Necromante. (Requer nível %s.)",
  ["Split-toed and silent; even the dust does not hear them. Dust Does Not Hear: Critical hits deal %s%% more damage. Other hits deal %s%% less. For: Thief. (Requires level %s.)"] = "De dedo dividido e silenciosas; nem a poeira as ouve. Dust Does Not Hear: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Só para: Ladino. (Requer nível %s.)",
  ["Spun twice: once for the wearer, once for the reflection. Spun Twice: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. Healing on you is %s%% lower. For: Mystic, Necromancer, Templar. (Requires level %s.)"] = "Fiada duas vezes: uma para quem veste, outra para o reflexo. Spun Twice: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. A cura que você recebe é %s%% menor. Só para: Místico, Necromante, Templário. (Requer nível %s.)",
  ["Strung by the marsh wardens, who never let a light cross the fen unseen. Fen Warden's Mark: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. For: Ranger. (Requires level %s.)"] = "Encordoado pelos guardiões do pântano, que nunca deixam uma luz cruzar o charco sem ser vista. Fen Warden's Mark: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Só para: Ranger. (Requer nível %s.)",
  ["Strung with fen reeds that froze overnight and never thawed. Fen Frost: %s%% of your physical damage is dealt as ice and deals %s%% more. Other elements deal %s%% less. For: Ranger. (Requires level %s.)"] = "Encordoado com juncos do pântano que congelaram numa noite e nunca descongelaram. Fen Frost: %s%% do seu dano físico é causado como gelo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["Strung with something that was once alive; it hums at the dead. Hum of the Dead: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Ranger. (Requires level %s.)"] = "Encordoado com algo que já esteve vivo; zune para os mortos. Hum of the Dead: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["Sworn to a master who answers to no one above. Hornsworn Oath: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.) Part of the Embers of Aranoth set."] = "Jurado a um mestre que não responde a ninguém acima. Hornsworn Oath: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.) Parte do set Embers of Aranoth.",
  ["Talons that sing in the wind over a grave that is never filled. Wind Over an Empty Grave: Critical hits deal %s%% more damage. Other hits deal %s%% less. A critical hit heals %s%% of its damage. For: Monk. (Requires level %s, Monks only.)"] = "Garras que cantam ao vento sobre uma cova que nunca é preenchida. Wind Over an Empty Grave: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Um golpe crítico cura %s%% do seu dano. Só para: Monge. (Requer nível %s, apenas Monks.)",
  ["Tears a seam in the world and lets the death in. Seam of the World: On a critical hit, a death nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Mystic, Necromancer. (Requires level %s.)"] = "Rasga uma costura no mundo e deixa a morte entrar. Seam of the World: Em um golpe crítico, uma nova de morte atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Místico, Necromante. (Requer nível %s.)",
  ["The beetle was dead long before it was strung. Scarab Swarm: A monster that dies with your poison damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Thief. (Requires level %s.)"] = "O besouro estava morto muito antes de ser encordoado. Scarab Swarm: Um monstro que morre com seu dano de veneno passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Ladino. (Requer nível %s.)",
  ["The choir is gone. The silence it left hangs on this chain. Silence Left Behind: Each kill restores %s%% of your maximum health, at most %s%% per second. Healing on you is %s%% lower. (Requires level %s.)"] = "O coro se foi. O silêncio que deixou pende desta corrente. Silence Left Behind: Cada morte restaura %s%% da sua vida máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. (Requer nível %s.)",
  ["The choir sings so that you need not. Vigils: each reserves %s%% less. Conductor's Rest: On a monster hit of %s%% of your health or more, a holy nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. For: Templar, Mystic, Necromancer. (Requires level %s. Warrior, Mystic, Necromancer, Monk and Templar lines.)"] = "O coro canta para que você não precise. Vigils: cada uma reserva %s%% menos. Conductor's Rest: Em um golpe de monstro de %s%% da sua vida ou mais, uma nova de sagrado atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Só para: Templário, Místico, Necromante. (Requer nível %s. Linhas Warrior, Mystic, Necromancer, Monk e Templar.)",
  ["The drowned choir still sings through it, one note per blow. One Note per Blow: You deal %s%% more damage per other monster within %s tiles, up to %s. Alone you deal %s%% less. For: Warrior, Thief, Monk, Templar. (Requires level %s.)"] = "O coro afogado ainda canta por ela, uma nota por golpe. One Note per Blow: Você causa %s%% a mais de dano por outro monstro a %s passos, até %s. Sozinho você causa %s%% a menos. Só para: Guerreiro, Ladino, Monge, Templário. (Requer nível %s.)",
  ["The first of a pair. It wants the other one in your off hand. First of a Pair: Each hit in a row on one target deals %s%% more, up to %s hits. The first hit on a new target deals %s%% less. For: Thief. (Requires level %s.)"] = "A primeira de um par. Ela quer a outra na sua mão secundária. First of a Pair: Cada golpe seguido no mesmo alvo causa %s%% a mais, até %s golpes. O primeiro golpe em um alvo novo causa %s%% a menos. Só para: Ladino. (Requer nível %s.)",
  ["The flower inside has never stopped growing. Contagion Rite: your poison spreads to one more monster and one step deeper. Never-Stopping Flower: A monster that dies with your poison damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Thief, Ranger. (Requires level %s.)"] = "A flor lá dentro nunca parou de crescer. Contagion Rite: seu veneno se espalha para mais um monstro e um passo mais fundo. Never-Stopping Flower: Um monstro que morre com seu dano de veneno passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Ladino, Ranger. (Requer nível %s.)",
  ["The gold is only paint; the plate is lightning held still. Aether Edge: your hits add %s%% more of your energy shield. Held Lightning: %s%% of your physical damage is dealt as energy and deals %s%% more. Other elements deal %s%% less. For: Templar, Monk. (Requires level %s.)"] = "O dourado é só tinta; a placa é raio mantido parado. Aether Edge: seus golpes somam %s%% a mais do seu escudo de energia. Held Lightning: %s%% do seu dano físico é causado como energia e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Templário, Monge. (Requer nível %s.)",
  ["The grey tide broke on it for a hundred years and left only salt. Hundred Years of Tide: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.)"] = "A maré cinzenta quebrou nela por cem anos e deixou só sal. Hundred Years of Tide: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["The gutter saint gave his mail away twice; it found its way back both times. Gutter Mercy: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. Healing on you is %s%% lower. For: Warrior, Templar, Monk. (Requires level %s.)"] = "O santo da sarjeta deu sua cota de malha duas vezes; ela voltou para ele nas duas. Gutter Mercy: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["The heron stands over the dead water, and nothing it watches walks away. Nothing It Watches Walks: Targets at %s%% health or more take %s%% more damage from you. Targets at %s%% or less take %s%% less. For: Ranger. (Requires level %s.)"] = "A garça fica sobre a água morta, e nada que ela observa vai embora. Nothing It Watches Walks: Alvos com %s%% de vida ou mais sofrem %s%% a mais de dano seu. Alvos com %s%% ou menos sofrem %s%% a menos. Só para: Ranger. (Requer nível %s.)",
  ["The hood the hangman wore so the condemned would not see his face. Face Unseen: Your hits mark the target for %s s, up to %s at once. Marked monsters take %s%% more damage from you. Others take %s%% less. For: Ranger, Thief. (Requires level %s.)"] = "O capuz que o carrasco usava para que o condenado não visse seu rosto. Face Unseen: Seus golpes marcam o alvo por %s s, até %s ao mesmo tempo. Monstros marcados sofrem %s%% a mais de dano seu. Os demais sofrem %s%% a menos. Só para: Ranger, Ladino. (Requer nível %s.)",
  ["The king died, the crown kept burning. Burning Crown: On a kill, a fire nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Mystic, Templar, Warrior. (Requires level %s.)"] = "O rei morreu, a coroa continuou queimando. Burning Crown: Em uma morte, uma nova de fogo atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Místico, Templário, Guerreiro. (Requer nível %s.)",
  ["The last chapter has not been written. It is waiting for you to finish. Unwritten Chapter: At %s%% mana or more you deal %s%% more damage. At %s%% mana or less you deal %s%% less. For: Mystic, Necromancer. (Requires level %s. Mystic and Necromancer lines.)"] = "O último capítulo não foi escrito. Ele espera que você o termine. Unwritten Chapter: Com %s%% de mana ou mais você causa %s%% a mais de dano. Com %s%% de mana ou menos você causa %s%% a menos. Só para: Místico, Necromante. (Requer nível %s. Linhas Mystic e Necromancer.)",
  ["The last coal of a dead sovereign, set in a ring. It is never cold. Last Coal of a Sovereign: On a kill, a fire nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Warrior, Templar, Mystic. (Requires level %s.)"] = "A última brasa de um soberano morto, engastada num anel. Nunca esfria. Last Coal of a Sovereign: Em uma morte, uma nova de fogo atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Guerreiro, Templário, Místico. (Requer nível %s.)",
  ["The last dawn broke on this plate and went no further. Dawn Broke Here: A hit that leaves you under %s%% health makes you take %s%% less damage for %s s, but blocks your healing meanwhile. Once per %s s. For: Warrior, Templar. (Requires level %s.)"] = "O último amanhecer quebrou nesta placa e não foi além. Dawn Broke Here: Um golpe que deixa você abaixo de %s%% de vida faz você receber %s%% a menos de dano por %s s, mas bloqueia sua cura nesse tempo. Uma vez a cada %s s. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["The last mercy of a drowned order, given to anyone who can carry it. Carry two. Carry Two: Each hit in a row on one target deals %s%% more, up to %s hits. The first hit on a new target deals %s%% less. For: Thief. (Requires level %s.)"] = "A última misericórdia de uma ordem afogada, dada a qualquer um que possa carregá-la. Carregue duas. Carry Two: Cada golpe seguido no mesmo alvo causa %s%% a mais, até %s golpes. O primeiro golpe em um alvo novo causa %s%% a menos. Só para: Ladino. (Requer nível %s.)",
  ["The last thing many a condemned man heard was its song. Last Words: Targets at %s%% health or less take %s%% more damage from you. Targets at %s%% or more take %s%% less. For: Warrior, Monk. (Requires level %s.)"] = "A última coisa que muitos condenados ouviram foi a sua canção. Last Words: Alvos com %s%% de vida ou menos sofrem %s%% a mais de dano seu. Alvos com %s%% ou mais sofrem %s%% a menos. Só para: Guerreiro, Monge. (Requer nível %s.)",
  ["The last watch rang it once, and the hour has not ended since. Hour Without End: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Warrior, Templar, Monk. (Requires level %s.)"] = "A última vigília o tocou uma vez, e a hora não acabou desde então. Hour Without End: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["The oath is cut into the stone; the stone is still warm. (Ashen Sepulchre.) Oath in Stone: A monster hit of %s%% of your health or more is answered with %s%% of it as holy damage, every %s s. For: Warrior, Templar, Monk. (Requires level %s.)"] = "O juramento está gravado na pedra; a pedra ainda está quente. (Ashen Sepulchre.) Oath in Stone: Um golpe de monstro de %s%% da sua vida ou mais é respondido com %s%% dele como dano de sagrado, a cada %s s. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["The pyre went out. The oath did not. Oath Outlives the Pyre: A hit that leaves you under %s%% health makes you take %s%% less damage for %s s, but blocks your healing meanwhile. Once per %s s. (Requires level %s.)"] = "A pira se apagou. O juramento não. Oath Outlives the Pyre: Um golpe que deixa você abaixo de %s%% de vida faz você receber %s%% a menos de dano por %s s, mas bloqueia sua cura nesse tempo. Uma vez a cada %s s. (Requer nível %s.)",
  ["The red moon's last crescent, cut down and given an edge. It drinks before you do. Drinks Before You: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. Healing on you is %s%% lower. (Requires level %s.)"] = "O último crescente da lua vermelha, cortado e afiado. Ela bebe antes de você. Drinks Before You: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. A cura que você recebe é %s%% menor. (Requer nível %s.)",
  ["The scent of death clings to it; so does its former owner. Lich's Grasp: A monster that dies with your death damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Necromancer. (Requires level %s.)"] = "O cheiro da morte se agarra a ela; e ao seu antigo dono também. Lich's Grasp: Um monstro que morre com seu dano de morte passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Necromante. (Requer nível %s.)",
  ["The seal of a court that burned itself down to win an argument. Court That Burned: %s%% of your physical damage is dealt as ice and deals %s%% more. Other elements deal %s%% less. For: Templar. (Requires level %s.)"] = "O selo de uma corte que se queimou para ganhar uma discussão. Court That Burned: %s%% do seu dano físico é causado como gelo e causa %s%% a mais. Outros elementos causam %s%% a menos. Só para: Templário. (Requer nível %s.)",
  ["The second of a pair. It strikes where the Fang was. Where the Fang Was: Your melee hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Thief. (Requires level %s.)"] = "A segunda de um par. Ela golpeia onde a Presa estava. Where the Fang Was: Seus golpes corpo a corpo enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ladino. (Requer nível %s.)",
  ["The seer saw every death but her own. The eye still watches for it. Seer's Last Sight: On a critical hit, a energy nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. Costs %s%% health, never below %s%%. For: Mystic, Necromancer, Thief. (Requires level %s.)"] = "A vidente viu todas as mortes, menos a sua. O olho ainda a procura. Seer's Last Sight: Em um golpe crítico, uma nova de energia atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Místico, Necromante, Ladino. (Requer nível %s.)",
  ["The sentence of the ash judges, passed once and never appealed. Judges of Ash: Targets at %s%% health or less take %s%% more damage from you. Targets at %s%% or more take %s%% less. For: Warrior, Thief, Monk, Templar. (Requires level %s.)"] = "A sentença dos juízes das cinzas, dada uma vez e nunca apelada. Judges of Ash: Alvos com %s%% de vida ou menos sofrem %s%% a mais de dano seu. Alvos com %s%% ou mais sofrem %s%% a menos. Só para: Guerreiro, Ladino, Monge, Templário. (Requer nível %s.)",
  ["The sky broke once. This is where the pieces went. Shattered Volley: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s. Ranger line.)"] = "O céu se partiu uma vez. Foi para cá que os pedaços foram. Shattered Volley: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["The string hums before the storm does. Your bow hits arc to one more enemy for %s%% as energy (with Stormstring: one more arc). Stormcall: Your ranged hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Ranger. (Requires level %s.)"] = "A corda zune antes da tempestade. Seus golpes de arco saltam para mais um inimigo com %s%% como energia (com Stormstring: mais um salto). Stormcall: Seus golpes à distância enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Ranger. (Requer nível %s.)",
  ["The undergrowth parts for them and closes behind. Parting Undergrowth: Your ranged hits deal %s%% more damage per %s speed above %s, up to %s%%. For: Ranger, Thief. (Requires level %s.)"] = "A vegetação se abre para eles e se fecha atrás. Parting Undergrowth: Seus golpes à distância causam %s%% a mais de dano a cada %s de velocidade acima de %s, até %s%%. Só para: Ranger, Ladino. (Requer nível %s.)",
  ["The visor of a warden who swore the dead would stay down. They did. (Ashen Sepulchre.) Down They Stayed: Your melee hits deal %s%% more damage per %s shielding skill, up to %s%%. For: Warrior, Templar, Monk. (Requires level %s.)"] = "O visor de um carcereiro que jurou que os mortos ficariam no chão. Ficaram. (Ashen Sepulchre.) Down They Stayed: Seus golpes corpo a corpo causam %s%% a mais de dano a cada %s de escudo, até %s%%. Só para: Guerreiro, Templário, Monge. (Requer nível %s.)",
  ["The warden's flail broke every shield brought to the first gate. Now it answers you. Broken Shields: Targets at %s%% health or less take %s%% more damage from you. Targets at %s%% or more take %s%% less. For: Warrior, Templar. (Requires level %s.)"] = "O mangual do carcereiro quebrou todo escudo levado ao primeiro portão. Agora ele responde a você. Broken Shields: Alvos com %s%% de vida ou menos sofrem %s%% a mais de dano seu. Alvos com %s%% ou mais sofrem %s%% a menos. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["There is always one more. That is the whole curse. One More: Each kill adds a stack for %s s, up to %s: %s%% more damage dealt per stack. Each stack also adds %s%% damage taken. For: Ranger. (Requires level %s. Ranger line.)"] = "Sempre há mais um. Essa é toda a maldição. One More: Cada morte dá um acúmulo por %s s, até %s: %s%% a mais de dano causado por acúmulo. Cada acúmulo também soma %s%% de dano recebido. Só para: Ranger. (Requer nível %s. Linha Ranger.)",
  ["They know every short way home, and most of the long ones. Short Ways Home: Your hits deal %s%% more damage per %s speed above %s, up to %s%%. For: Ranger, Thief, Monk. (Requires level %s.)"] = "Elas conhecem todo atalho para casa, e a maioria dos caminhos longos. Short Ways Home: Seus golpes causam %s%% a mais de dano a cada %s de velocidade acima de %s, até %s%%. Só para: Ranger, Ladino, Monge. (Requer nível %s.)",
  ["They leave red prints on clean stone. Red Prints: A monster that dies with your bleeding damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Warrior, Thief. (Requires level %s.)"] = "Deixam marcas vermelhas na pedra limpa. Red Prints: Um monstro que morre com seu dano de sangramento passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Guerreiro, Ladino. (Requer nível %s.)",
  ["They leave two sets of footprints. Two Sets of Footprints: On a monster hit of %s%% of your health or more, a energy nova hits up to %s monsters within %s tiles for %s plus %s per level, every %s s. For: Mystic, Necromancer, Templar. (Requires level %s.)"] = "Deixam dois conjuntos de pegadas. Two Sets of Footprints: Em um golpe de monstro de %s%% da sua vida ou mais, uma nova de energia atinge até %s monstros a %s passos com %s mais %s por nível, a cada %s s. Só para: Místico, Necromante, Templário. (Requer nível %s.)",
  ["They make no sound, and neither does the one who falls behind. Soundless Step: Against one target alone you deal %s%% more damage. Among %s or more monsters you deal %s%% less. For: Thief, Ranger, Monk. (Requires level %s.)"] = "Não fazem som, e quem fica para trás também não. Soundless Step: Contra um único alvo você causa %s%% a mais de dano. Entre %s ou mais monstros você causa %s%% a menos. Só para: Ladino, Ranger, Monge. (Requer nível %s.)",
  ["They remember every step down, and none back up. Down Never Back: Your hits deal %s%% more damage per %s speed above %s, up to %s%%. For: Warrior, Thief, Monk. (Requires level %s.)"] = "Elas lembram cada passo para baixo, e nenhum de volta. Down Never Back: Seus golpes causam %s%% a mais de dano a cada %s de velocidade acima de %s, até %s%%. Só para: Guerreiro, Ladino, Monge. (Requer nível %s.)",
  ["Those who stand under it keep their oaths. Vigils: each reserves %s%% less and reaches %s sqm farther. Oath Under the Banner: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Templar, Monk, Mystic, Warrior. (Requires level %s. Warrior, Mystic, Necromancer, Monk and Templar lines.)"] = "Quem fica sob ele cumpre seus juramentos. Vigils: cada uma reserva %s%% menos e alcança %s sqm a mais. Oath Under the Banner: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Templário, Monge, Místico, Guerreiro. (Requer nível %s. Linhas Warrior, Mystic, Necromancer, Monk e Templar.)",
  ["Tiny fangs line the soles; it is best not to ask why. Tiny Fangs: A monster hit of %s%% of your health or more is answered with %s%% of it as physical damage, every %s s. For: Warrior, Thief, Monk. (Requires level %s.)"] = "Pequenas presas forram as solas; melhor não perguntar por quê. Tiny Fangs: Um golpe de monstro de %s%% da sua vida ou mais é respondido com %s%% dele como dano de físico, a cada %s s. Só para: Guerreiro, Ladino, Monge. (Requer nível %s.)",
  ["Twin horned heads, cut from something that fell a long way down. Ninth-Circle Bite: A monster that dies with your fire damage on it passes it to %s monsters within %s tiles: %s%% of the last tick for %s ticks. Your direct hits deal %s%% less. For: Mystic, Templar. (Requires level %s.)"] = "Duas cabeças com chifres, cortadas de algo que caiu de muito alto. Ninth-Circle Bite: Um monstro que morre com seu dano de fogo passa o efeito a %s monstros a %s passos: %s%% do último golpe por %s vezes. Seus golpes diretos causam %s%% a menos. Só para: Místico, Templário. (Requer nível %s.)",
  ["Varkhul wore it to the end of the world and back. It still expects a throne. Expected Throne: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Warrior, Templar. (Requires level %s.)"] = "Varkhul a usou até o fim do mundo e de volta. Ainda espera um trono. Expected Throne: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Guerreiro, Templário. (Requer nível %s.)",
  ["Walk far enough and the road turns to ash behind you. Road Turns to Ash: Your melee hits deal %s%% more damage per %s speed above %s, up to %s%%. For: Warrior, Thief, Monk. (Requires level %s.)"] = "Ande longe o bastante e a estrada vira cinza atrás de você. Road Turns to Ash: Seus golpes corpo a corpo causam %s%% a mais de dano a cada %s de velocidade acima de %s, até %s%%. Só para: Guerreiro, Ladino, Monge. (Requer nível %s.)",
  ["Warm from a hand that was never quite taken off. Knuckle Spark: Critical hits deal %s%% more damage. Other hits deal %s%% less. For: Monk, Thief. (Requires level %s.)"] = "Quente de uma mão que nunca foi totalmente tirada. Knuckle Spark: Golpes críticos causam %s%% a mais de dano. Outros golpes causam %s%% a menos. Só para: Monge, Ladino. (Requer nível %s.)",
  ["When it grows warm, something you summoned has fed. Fed Bond: Each kill restores %s%% of your maximum mana, at most %s%% per second. Healing on you is %s%% lower. For: Necromancer, Mystic, Ranger. (Requires level %s.)"] = "Quando esquenta, algo que você invocou se alimentou. Fed Bond: Cada morte restaura %s%% da sua mana máxima, no máximo %s%% por segundo. A cura que você recebe é %s%% menor. Só para: Necromante, Místico, Ranger. (Requer nível %s.)",
  ["Wherever it lands, a new mouth opens. New Mouth: Your melee hits send %s%% of their damage at %s more monsters within %s tiles of the target. Costs %s%% health, never below %s%%. For: Templar, Monk. (Requires level %s.)"] = "Onde quer que caia, uma nova boca se abre. New Mouth: Seus golpes corpo a corpo enviam %s%% do dano a mais %s monstros a %s passos do alvo. Custa %s%% de vida, nunca abaixo de %s%%. Só para: Templário, Monge. (Requer nível %s.)",
  ["Worn by a choir that sang on after its voices were gone. Choir Sang On: Your minions deal %s%% more damage and have %s%% more health. Your own spells deal %s%% less. For: Necromancer. (Requires level %s.)"] = "Usada por um coro que continuou cantando depois que as vozes se foram. Choir Sang On: Seus lacaios causam %s%% a mais de dano e têm %s%% a mais de vida. Suas próprias magias causam %s%% a menos. Só para: Necromante. (Requer nível %s.)",
  ["Worn on the hand that never held a blade. Your bare fists hit as with the Open Hand Creed at %s%% without the keystone; with it, %s%% harder. Hand That Never Held: Each hit in a row on one target deals %s%% more, up to %s hits. The first hit on a new target deals %s%% less. For: Monk, Thief, Warrior. (Requires level %s.)"] = "Usada na mão que nunca empunhou uma lâmina. Seus punhos nus acertam como com o Open Hand Creed a %s%% sem a keystone; com ela, %s%% mais forte. Hand That Never Held: Cada golpe seguido no mesmo alvo causa %s%% a mais, até %s golpes. O primeiro golpe em um alvo novo causa %s%% a menos. Só para: Monge, Ladino, Guerreiro. (Requer nível %s.)",
  ["Woven for a body that no longer bleeds. Hollow Vessel: the items' energy shield counts %s%% more. Bloodless Body: A single hit from a monster takes at most %s%% of your maximum health. Healing on you is %s%% lower. For: Mystic, Necromancer, Monk, Templar. (Requires level %s. Mystic, Necromancer, Monk and Templar lines.)"] = "Tecido para um corpo que já não sangra. Hollow Vessel: o escudo de energia dos itens conta %s%% a mais. Bloodless Body: Um único golpe de monstro tira no máximo %s%% da sua vida máxima. A cura que você recebe é %s%% menor. Só para: Místico, Necromante, Monge, Templário. (Requer nível %s. Linhas Mystic, Necromancer, Monk e Templar.)",
  ["Woven from burial linen of a lich-queen. Lich-Queen's Linen: Your minions deal %s%% more damage and have %s%% more health. Your own spells deal %s%% less. For: Necromancer. (Requires level %s.)"] = "Tecida do linho funerário de uma rainha lich. Lich-Queen's Linen: Seus lacaios causam %s%% a mais de dano e têm %s%% a mais de vida. Suas próprias magias causam %s%% a menos. Só para: Necromante. (Requer nível %s.)",
  ["Woven from the ash of every lullaby she sang. It is warm, and it should not be. Warm and Wrong: While you fight, you and your party within %s tiles heal %s%% of their health every %s s. Other healing on you is %s%% lower. For: Mystic, Templar, Monk, Necromancer. (Requires level %s.)"] = "Tecido com a cinza de toda canção de ninar que ela cantou. É quente, e não deveria ser. Warm and Wrong: Enquanto você luta, você e seu grupo a %s passos curam %s%% da vida a cada %s s. Outra cura que você recebe é %s%% menor. Só para: Místico, Templário, Monge, Necromante. (Requer nível %s.)",
  ["Wrapped tight, for running along rooftops. Rooftop Run: Your hits deal %s%% more damage per %s speed above %s, up to %s%%. For: Thief, Monk, Ranger. (Requires level %s.)"] = "Enrolada firme, para correr pelos telhados. Rooftop Run: Seus golpes causam %s%% a mais de dano a cada %s de velocidade acima de %s, até %s%%. Só para: Ladino, Monge, Ranger. (Requer nível %s.)",
  ["Wraps knotted by a monk who kept watch over a burning chapel. Vigil Knot: %s%% of the damage you deal and %s%% of your health per kill become a ward, up to %s%% of your health. It absorbs damage and fades after %s s. For: Monk. (Requires level %s, Monks only.)"] = "Ataduras atadas por um monge que vigiou uma capela em chamas. Vigil Knot: %s%% do dano que você causa e %s%% da sua vida por morte viram uma proteção, até %s%% da sua vida. Ela absorve dano e some após %s s. Só para: Monge. (Requer nível %s, apenas Monks.)",
  -- END GENERATED UNIQUE DESCRIPTIONS
  ["Mana on Hit +%s"] = "Mana por golpe +%s",
  ["Smoldering Aura: while you fight, monsters within %s sqm take %s fire damage per second"] = "Smoldering Aura: enquanto você luta, monstros num raio de %s sqm sofrem %s de dano de fogo por segundo",
  ["Sworn on the Blood Colossus's own altar: every wound you open must stay open."] = "Jurado no altar do próprio Colosso de Sangue: toda ferida que você abrir deve continuar aberta.",
  ["Woven by the fire and frost queens' court mages, who never agreed on anything but the burning."] = "Tecido pelos magos da corte das rainhas do fogo e do gelo, que nunca concordaram em nada além da queima.",
  ["The Void Archon's knife-hands wore it to walk between his heartbeats. Two blades, never one."] = "As mãos-faca do Void Archon o usavam para andar entre seus batimentos. Duas lâminas, nunca uma.",
  ["The armour of the last warden-mage of Aranoth, who held the burning gate until the gate itself gave way."] = "A armadura do último mago-guardião de Aranoth, que segurou o portão em chamas até o próprio portão ceder.",
  ["A hangman's kit for the patient: one bolt, one verdict, no appeal."] = "Um kit de carrasco para os pacientes: um virote, um veredito, sem apelação.",
  ["A pact sealed in the Rotmother's den: the pack feeds the master, the master feeds the pack."] = "Um pacto selado na toca da Rotmother: a matilha alimenta o mestre, o mestre alimenta a matilha.",
  ["Found on the ninth landing of the Descent, still warm, still whispering the names of the burned."] = "Achado no nono patamar da Descida, ainda quente, ainda sussurrando os nomes dos queimados.",
  ["Every thread was spun twice, once for the wearer and once for the reflection that heals beside her."] = "Cada fio foi fiado duas vezes, uma para quem veste e outra para o reflexo que cura ao lado dela.",
  ["The wardens of the Sepulchre swore to keep the dead in. Their oath outlived them; their armour still keeps it."] = "Os guardiões do Sepulcro juraram manter os mortos lá dentro. O juramento sobreviveu a eles; a armadura deles ainda o cumpre.",
  ["Cut from the briar that swallowed the Wildwood's first road; its arrows still remember the thorns."] = "Talhado do espinheiro que engoliu a primeira estrada da Wildwood; suas flechas ainda lembram dos espinhos.",
  ["Players receive %s-%s%% less healing."] = "Jogadores recebem %s-%s%% menos cura.",
  ["Monsters deal +%s-%s%% damage."] = "Monstros causam +%s-%s%% de dano.",
  ["Reward bonus: +%s%% rarity, +%s%% experience per point."] = "Bônus de recompensa: +%s%% de raridade, +%s%% de experiência por ponto.",
  ["Slain monsters burst for %s-%s%% health."] = "Monstros abatidos explodem com %s-%s%% de vida.",
  ["Guardian +%s-%s%% health and damage."] = "Guardião +%s-%s%% de vida e dano.",
  ["%s-%s%% chance of double loot."] = "%s-%s%% de chance de loot em dobro.",
  ["+%s-%s%% magic, rare and legendary monsters."] = "+%s-%s%% de monstros magic, rare e legendary.",
  ["Monsters deal +%s-%s%% of their damage as extra fire."] = "Monstros causam +%s-%s%% do dano deles como fogo extra.",
  ["Never on a key with Frostbrand, Stormbrand."] = "Nunca numa chave com Frostbrand, Stormbrand.",
  ["Monster hits have a %s-%s%% chance to fester for %s%% more as earth over %s s."] = "Golpes de monstros têm %s-%s%% de chance de infeccionar, causando %s%% a mais como terra ao longo de %s s.",
  ["Players take %s-%s%% more physical damage."] = "Jogadores sofrem %s-%s%% a mais de dano físico.",
  ["Never on a key with Searing Hex, Sapping Hex."] = "Nunca numa chave com Searing Hex, Sapping Hex.",
  ["%s-%s fewer shared lives."] = "%s-%s vidas compartilhadas a menos.",
  ["No tiers: value %s-%s."] = "Sem tiers: valor %s-%s.",
  ["Monsters deal +%s-%s%% of their damage as extra ice."] = "Monstros causam +%s-%s%% do dano deles como gelo extra.",
  ["Never on a key with Emberbrand, Stormbrand."] = "Nunca numa chave com Emberbrand, Stormbrand.",
  ["%s-%s%% chance of a fleeing Treasure Goblin."] = "%s-%s%% de chance de um Treasure Goblin fugitivo.",
  ["Monsters move +%s-%s faster."] = "Monstros se movem +%s-%s mais rápido.",
  ["Reward bonus: +%s%% quantity per point."] = "Bônus de recompensa: +%s%% de quantidade por ponto.",
  ["Monsters take %s-%s%% less physical damage."] = "Monstros sofrem %s-%s%% menos dano físico.",
  ["Hardest on physical builds (melee, arrows and bolts)."] = "Mais difícil para builds físicas (corpo a corpo, flechas e virotes).",
  ["Monster hits have a %s-%s%% chance to deal %s%% more."] = "Golpes de monstros têm %s-%s%% de chance de causar %s%% a mais.",
  ["Players do not regenerate mana."] = "Jogadores não regeneram mana.",
  ["Reward bonus: +%s%% quantity, +%s%% rarity, +%s%% experience (flat)."] = "Bônus de recompensa: +%s%% de quantidade, +%s%% de raridade, +%s%% de experiência (fixo).",
  ["Hardest on casters. Never with Withering."] = "Mais difícil para conjuradores. Nunca com Withering.",
  ["Never on a key with Withering."] = "Nunca numa chave com Withering.",
  ["Monsters reflect %s-%s%% of the damage they take."] = "Monstros refletem %s-%s%% do dano que sofrem.",
  ["Never on a key with Spiteglass."] = "Nunca numa chave com Spiteglass.",
  ["Freezing ground under the players: %s-%s%% of max health a second and slowed."] = "Chão congelante sob os jogadores: %s-%s%% da vida máxima por segundo e lentidão.",
  ["Never on a key with Scorched Earth."] = "Nunca numa chave com Scorched Earth.",
  ["Players deal %s-%s%% less damage."] = "Jogadores causam %s-%s%% menos dano.",
  ["Never on a key with Searing Hex, Flaying Hex."] = "Nunca numa chave com Searing Hex, Flaying Hex.",
  ["Burning ground under the players: %s-%s%% of max health a second."] = "Chão em chamas sob os jogadores: %s-%s%% da vida máxima por segundo.",
  ["Never on a key with Rimefloor."] = "Nunca numa chave com Rimefloor.",
  ["%s-%s%% chance of a guarded coffer."] = "%s-%s%% de chance de um cofre guardado.",
  ["Players take %s-%s%% more elemental damage."] = "Jogadores sofrem %s-%s%% a mais de dano elemental.",
  ["Never on a key with Flaying Hex, Sapping Hex."] = "Nunca numa chave com Flaying Hex, Sapping Hex.",
  ["Every pack is of the rift's strongest kind."] = "Todo pack é do tipo mais forte do rift.",
  ["Reward bonus: +%s%% quantity, +%s%% rarity (flat)."] = "Bônus de recompensa: +%s%% de quantidade, +%s%% de raridade (fixo).",
  ["Monsters reflect %s-%s%% of the elemental damage they take."] = "Monstros refletem %s-%s%% do dano elemental que sofrem.",
  ["Hardest on casters and elemental builds. Never with Reflection."] = "Mais difícil para conjuradores e builds elementais. Nunca com Reflection.",
  ["Never on a key with Reflection."] = "Nunca numa chave com Reflection.",
  ["Monsters deal +%s-%s%% of their damage as extra energy."] = "Monstros causam +%s-%s%% do dano deles como energia extra.",
  ["Never on a key with Emberbrand, Frostbrand."] = "Nunca numa chave com Emberbrand, Frostbrand.",
  ["+%s-%s monsters in every pack."] = "+%s-%s monstros em cada pack.",
  ["+%s-%s%% monster packs."] = "+%s-%s%% de packs de monstros.",
  ["Twin guardians, %s-%s%% health each."] = "Guardiões gêmeos, %s-%s%% de vida cada.",
  ["Never on a key with Wrathful Guardian."] = "Nunca numa chave com Wrathful Guardian.",
  ["%s-%s%% of slain monsters tear open a breach of two more."] = "%s-%s%% dos monstros abatidos abrem uma brecha com mais dois.",
  ["Marked storm strikes near the players: %s-%s%% of max health."] = "Uma tempestade marcada cai perto dos jogadores: %s-%s%% da vida máxima.",
  ["Monsters have +%s-%s%% health."] = "Monstros têm +%s-%s%% de vida.",
  ["The rift closes %s-%s%% sooner."] = "O rift fecha %s-%s%% mais cedo.",
  ["%s-%s%% of packs are rare warbands."] = "%s-%s%% dos packs são bandos rare.",
  ["Monsters resist %s-%s%% elemental damage."] = "Monstros resistem a %s-%s%% do dano elemental.",
  ["Players do not regenerate health."] = "Jogadores não regeneram vida.",
  ["Reward bonus: +%s%% quantity, +%s%% experience (flat)."] = "Bônus de recompensa: +%s%% de quantidade, +%s%% de experiência (fixo).",
  ["Never on a key with Parched Veins."] = "Nunca numa chave com Parched Veins.",
  ["The guardian's nova hits for %s-%s%% of max health every %s s; it calls thralls."] = "A nova do guardião acerta %s-%s%% da vida máxima a cada %s s; ele chama servos.",
  ["The nova is marked first: step out of it."] = "A nova é marcada antes: saia dela.",
  ["Never on a key with Twin Guardians."] = "Nunca numa chave com Twin Guardians.",
  ["A key has a tier (%s-%s) and up to %s modifiers. Modifiers on a drop: %s: %s%%, %s: %s%%, %s: %s%%."] = "Uma chave tem um tier (%s-%s) e até %s modificadores. Modificadores num drop: %s: %s%%, %s: %s%%, %s: %s%%.",
  ["The modifiers make the rift harder and raise its rewards: quantity, rarity, experience, at most +%s%%/+%s%%/+%s%% (raised by tier IV and V modifiers)."] = "Os modificadores deixam o rift mais difícil e aumentam suas recompensas: quantidade, raridade, experiência, no máximo +%s%%/+%s%%/+%s%% (aumentado por modificadores de tier IV e V).",
  ["Tiers above %s reuse the last window: +%s levels to enter and +%s%% health, damage and +%s%% rewards per tier."] = "Tiers acima de %s reutilizam a última faixa: +%s níveis para entrar e +%s%% de vida, dano e +%s%% de recompensas por tier.",
  ["Every rift is a new generated map: a cave system, an open waste, a ruined complex or a cave with ruined chambers, sometimes on two floors, with the guardian's arena in the far corner. Its size follows the key's tier: tiers %s-%s %s x %s tiles, %s minutes; tiers %s-%s %s x %s tiles, %s minutes; tiers %s-%s %s x %s tiles, %s minutes."] = "Todo rift é um mapa novo gerado: um sistema de cavernas, um ermo aberto, um complexo em ruínas ou uma caverna com câmaras em ruínas, às vezes em dois andares, com a arena do guardião no canto mais distante. O tamanho segue o tier da chave: tiers %s-%s %s x %s tiles, %s minutos; tiers %s-%s %s x %s tiles, %s minutos; tiers %s-%s %s x %s tiles, %s minutos.",
  ["The guardian comes after %s%% of the monsters; %s shared lives + %s per extra player; up to %s players."] = "O guardião aparece depois de %s%% dos monstros; %s vidas compartilhadas + %s por jogador extra; até %s jogadores.",
  ["About %s monsters solo at tier %s up to %s at tier %s on a map of typical size (+%s%% per extra player; a bigger map holds more), in packs of %s-%s over the whole map; about %s-%s alive at once, the rest gather ahead of you as you advance. Most monsters are husks: experience only. Magic and better monsters always carry loot, so a run drops about what fewer, tougher packs did."] = "Cerca de %s monstros solo no tier %s até %s no tier %s num mapa de tamanho típico (+%s%% por jogador extra; um mapa maior comporta mais), em packs de %s-%s por todo o mapa; cerca de %s-%s vivos de uma vez, o resto se reúne à sua frente conforme você avança. A maioria dos monstros são cascas: só experiência. Monstros magic ou melhores sempre carregam loot, então uma run solta mais ou menos o que menos packs, porém mais duros, soltavam.",
  ["Each extra player: +%s%% monster health in total (more packs, tougher monsters), +%s%% guardian health, +%s%% damage taken; every finisher's chest +%s%% (at most +%s%%) and +%s%% kill loot (at most +%s%%)."] = "Cada jogador extra: +%s%% de vida de monstros no total (mais packs, monstros mais duros), +%s%% de vida do guardião, +%s%% de dano recebido; o baú de cada finalizador +%s%% (no máximo +%s%%) e +%s%% de loot por abate (no máximo +%s%%).",
  ["Gold: %s x tier squared to the bank."] = "Ouro: %s x tier ao quadrado para o banco.",
  ["Orb of Upheaval: %s + %s per tier; Orb of Fate: %s + %s per tier."] = "Orb of Upheaval: %s + %s por tier; Orb of Fate: %s + %s por tier.",
  ["Item rolls: %s + %s per tier from the rift monsters' loot, gear with a rarity; one currency roll and one unique roll."] = "Rolagens de item: %s + %s por tier do loot dos monstros do rift, equipamentos com raridade; uma rolagem de moeda e uma de unique.",
  ["Gems and spell supports too (Gems and Supports tabs). Gold, orbs and rolls x (%s + quantity bonus)."] = "Gems e supports de magia também (abas Gems e Supports). Ouro, orbes e rolagens x (%s + bônus de quantidade).",
  ["Rifts of tier %s or more give omen fragments; %s fragments bind an Omen Key of a random kind. The key opens that guardian's arena (level %s, %s minutes, the rift's lives). Omen keys have no modifiers."] = "Rifts de tier %s ou mais dão fragmentos de omen; %s fragmentos vinculam uma Omen Key de um tipo aleatório. A chave abre a arena desse guardião (nível %s, %s minutos, as vidas do rift). Omen Keys não têm modificadores.",
  ["%s x your level in gold to the bank, %s Orb of Upheaval, %s Orb of Fate, %s item rolls of the guardian's loot (x%s rarity), %s unique rolls (x%s find), gems and supports as a tier %s rift. Drops in the arena get +%s item level."] = "%s x seu nível em ouro para o banco, %s Orb of Upheaval, %s Orb of Fate, %s rolagens de item do loot do guardião (x%s de raridade), %s rolagens de unique (x%s de find), gems e supports como um rift de tier %s. Drops na arena ganham +%s de nível de item.",
  ["Heals you for %s/%s/%s/%s/%s%% of the spell's damage (at most %s%% of your max health per cast)."] = "Cura você em %s/%s/%s/%s/%s%% do dano da magia (no máximo %s%% da sua vida máxima por conjuração).",
  ["Enemies within %s/%s/%s/%s/%s sqm of the hit ones that the spell missed take %s/%s/%s/%s/%s%% of the average hit (max %s)."] = "Inimigos num raio de %s/%s/%s/%s/%s sqm dos atingidos que a magia errou sofrem %s/%s/%s/%s/%s%% do golpe médio (máx. %s).",
  ["Fits area spells."] = "Serve para magias de área.",
  ["%s/%s/%s/%s/%s%% of the spell's damage is added as extra holy damage."] = "%s/%s/%s/%s/%s%% do dano da magia é adicionado como dano extra sagrado.",
  ["A kill by the spell bursts the corpse: enemies within %s sqm take %s/%s/%s/%s/%s%% of the killing hit (once per cast)."] = "Um abate pela magia explode o cadáver: inimigos num raio de %s sqm sofrem %s/%s/%s/%s/%s%% do golpe final (uma vez por conjuração).",
  ["%s/%s/%s/%s/%s%% chance per cast that the spell's hits strike again %s s later for %s%% damage."] = "%s/%s/%s/%s/%s%% de chance por conjuração de os golpes da magia acertarem de novo %s s depois com %s%% de dano.",
  ["%s/%s/%s/%s/%s%% of the spell's damage is added as extra fire damage."] = "%s/%s/%s/%s/%s%% do dano da magia é adicionado como dano extra de fogo.",
  ["The hit forks to %s/%s/%s/%s/%s more enemies within %s sqm for %s/%s/%s/%s/%s%% of it."] = "O golpe se bifurca para mais %s/%s/%s/%s/%s inimigos num raio de %s sqm com %s/%s/%s/%s/%s%% dele.",
  ["%s/%s/%s/%s/%s%% of the spell's damage is added as extra death damage."] = "%s/%s/%s/%s/%s%% do dano da magia é adicionado como dano extra de morte.",
  ["Monsters hit take +%s/%s/%s/%s/%s%% damage from everyone for %s s (the strongest hex counts)."] = "Monstros atingidos sofrem +%s/%s/%s/%s/%s%% de dano de todos por %s s (vale a maldição mais forte).",
  ["+%s/%s/%s/%s/%s%% chance per hit to strike critically for +%s%% damage."] = "+%s/%s/%s/%s/%s%% de chance por golpe de acertar um crítico com +%s%% de dano.",
  ["The spell heals %s/%s/%s/%s/%s%% more."] = "A magia cura %s/%s/%s/%s/%s%% a mais.",
  ["Fits healing spells."] = "Serve para magias de cura.",
  ["Cooldown -%s/%s/%s/%s/%s%%."] = "Recarga -%s/%s/%s/%s/%s%%.",
  ["For %s s after the cast, a monster's hit on you has a %s%% chance to strike it back for %s/%s/%s/%s/%s%% of the hit."] = "Por %s s depois da conjuração, o golpe de um monstro em você tem %s%% de chance de revidar com %s/%s/%s/%s/%s%% do golpe.",
  ["%s/%s/%s/%s/%s%% of the spell's damage is added as extra ice damage."] = "%s/%s/%s/%s/%s%% do dano da magia é adicionado como dano extra de gelo.",
  ["Enemies next to the target take %s/%s/%s/%s/%s%% of the hit (max %s)."] = "Inimigos ao lado do alvo sofrem %s/%s/%s/%s/%s%% do golpe (máx. %s).",
  ["Restores %s/%s/%s/%s/%s mana per %s damage of the spell (at most %s%% of your max mana per cast)."] = "Restaura %s/%s/%s/%s/%s de mana a cada %s de dano da magia (no máximo %s%% da sua mana máxima por conjuração).",
  ["%s/%s/%s/%s/%s%% of the spell's damage is added as extra energy damage."] = "%s/%s/%s/%s/%s%% do dano da magia é adicionado como dano extra de energia.",
  ["Ignores %s/%s/%s/%s/%s points of a monster's resistance to the spell's element (never below %s)."] = "Ignora %s/%s/%s/%s/%s pontos da resistência de um monstro ao elemento da magia (nunca abaixo de %s).",
  ["A critical hit of the spell blasts the enemies next to the target for %s/%s/%s/%s/%s%% of it (once per cast)."] = "Um golpe crítico da magia atinge os inimigos ao lado do alvo com %s/%s/%s/%s/%s%% dele (uma vez por conjuração).",
  ["Mana cost -%s/%s/%s/%s/%s%%, given back right after the cast."] = "Custo de mana -%s/%s/%s/%s/%s%%, devolvido logo depois da conjuração.",
  ["Four gathering professions, each with its own level %s-%s: Delving (ore veins), Wortcunning (herb patches), Flaying (corpses of beasts and reptiles) and Angling (fishing). They make no gear and no orbs: what you gather is sold to a Material Broker (one stands next to every temple; in Cinderhold in the teleport room's market)."] = "Quatro profissões de coleta, cada uma com seu próprio nível %s-%s: Delving (veios de minério), Wortcunning (canteiros de ervas), Flaying (cadáveres de feras e répteis) e Angling (pesca). Elas não fazem equipamentos nem orbes: o que você coleta é vendido a um Material Broker (há um ao lado de cada templo; em Cinderhold, no mercado da sala de teleporte).",
  ["Every profession level above %s adds %s%% experience from monsters, all four together at most +%s%% (every profession at %s)."] = "Cada nível de profissão acima de %s soma %s%% de experiência dos monstros, as quatro juntas no máximo +%s%% (todas as profissões em %s).",
  ["Each week every material gets one of the demand multipliers x%s, x%s, x%s, x%s, x%s (Economy > Professions shows the week's board). Per material and day the broker pays the full price for %s units, then %s%% of it up to %s, then takes no more until the next day."] = "Toda semana cada material recebe um dos multiplicadores de procura x%s, x%s, x%s, x%s, x%s (Economy > Professions mostra o quadro da semana). Por material e por dia, o broker paga o preço cheio por %s unidades, depois %s%% dele até %s, e não compra mais até o dia seguinte.",
  ["Grey ore with a smell of old fires. Sell it to a Material Broker."] = "Minério cinzento com cheiro de fogueiras antigas. Venda a um Material Broker.",
  ["Ore veined with rust as red as blood. Sell it to a Material Broker."] = "Minério veiado de ferrugem, vermelha como sangue. Venda a um Material Broker.",
  ["A violet shard that drinks the light. Sell it to a Material Broker."] = "Um caco violeta que bebe a luz. Venda a um Material Broker.",
  ["Pale silver, cold to the touch. Sell it to a Material Broker."] = "Prata pálida, fria ao toque. Venda a um Material Broker.",
  ["A crystal that still glows from the depths. Sell it to a Material Broker."] = "Um cristal que ainda brilha das profundezas. Venda a um Material Broker.",
  ["Moss from the shade of old graves. Sell it to a Material Broker."] = "Musgo da sombra de túmulos antigos. Venda a um Material Broker.",
  ["A gnarled root, bitter enough to wake the dying. Sell it to a Material Broker."] = "Uma raiz retorcida, amarga o bastante para acordar os moribundos. Venda a um Material Broker.",
  ["A dark bloom that opens only at night. Sell it to a Material Broker."] = "Uma flor escura que só abre à noite. Venda a um Material Broker.",
  ["A grey mushroom that grows on haunted ground. Sell it to a Material Broker."] = "Um cogumelo cinzento que cresce em solo assombrado. Venda a um Material Broker.",
  ["A red herb that grows in the ash of hellfire. Sell it to a Material Broker."] = "Uma erva vermelha que cresce nas cinzas do fogo infernal. Venda a um Material Broker.",
  ["A coarse pelt, still smelling of the wild. Sell it to a Material Broker."] = "Um couro grosseiro, ainda com cheiro de mato. Venda a um Material Broker.",
  ["A thick hide, scarred by many fights. Sell it to a Material Broker."] = "Um couro grosso, marcado por muitas lutas. Venda a um Material Broker.",
  ["Hard scales on a supple skin. Sell it to a Material Broker."] = "Escamas duras sobre uma pele flexível. Venda a um Material Broker.",
  ["The dark pelt of a monstrous beast. Sell it to a Material Broker."] = "O couro escuro de uma fera monstruosa. Venda a um Material Broker.",
  ["A scale as hard as forged steel. Sell it to a Material Broker."] = "Uma escama dura como aço forjado. Venda a um Material Broker.",
  ["A grey fish from muddy water. Sell it to a Material Broker."] = "Um peixe cinzento de água barrenta. Venda a um Material Broker.",
  ["A carp from the shadowed pools. Sell it to a Material Broker."] = "Uma carpa dos poços sombrios. Venda a um Material Broker.",
  ["A trout with fins the colour of blood. Sell it to a Material Broker."] = "Uma truta com nadadeiras cor de sangue. Venda a um Material Broker.",
  ["A pike that hunts at nightfall. Sell it to a Material Broker."] = "Um lúcio que caça ao anoitecer. Venda a um Material Broker.",
  ["A black pearl from the deepest waters. Sell it to a Material Broker."] = "Uma pérola negra das águas mais profundas. Venda a um Material Broker.",
  ["Items come in seven rarities: Common, Uncommon, Magic, Rare, Legendary, Divine and Unique. Gear can carry one of the first six; a unique has fixed stats of its own. The rarity decides how many modifiers a new item gets and how many prefixes and suffixes it may carry."] = "Os itens vêm em sete raridades: Common, Uncommon, Magic, Rare, Legendary, Divine e Unique. Equipamentos podem ter uma das seis primeiras; um unique tem atributos fixos próprios. A raridade decide quantos modificadores um item novo recebe e quantos prefixos e sufixos ele pode ter.",
  ["Every item has an item level (%s-%s) from where it dropped. The item level decides which tiers its modifiers can roll: T%s (lowest) to T%s (highest)."] = "Todo item tem um nível de item (%s-%s) de acordo com onde caiu. O nível do item decide quais tiers seus modificadores podem rolar: de T%s (o mais baixo) a T%s (o mais alto).",
  ["Prefixes are damage and defence, suffixes utility, resistances and speed."] = "Prefixos são dano e defesa, sufixos são utilidade, resistências e velocidade.",
  ["Orbs change items (Orbs tab); the crafting bench shows what each would do. Legendary powers roll only from Legendary."] = "Orbes mudam itens (aba Orbs); a bancada de criação mostra o que cada um faria. Poderes lendários só rolam a partir de Legendary.",
  ["Uniques have fixed stats and are never changed by orbs."] = "Uniques têm atributos fixos e nunca são alterados por orbes.",
  ["New = modifiers on a new item; Sides = most prefixes (and suffixes); Max = what the Orb of Grafting fills up to; Binds = bound modifiers allowed; Quality = Whetstone cap; Sockets = most sockets by rarity."] = "Novo = modificadores num item novo; Lados = máximo de prefixos (e sufixos); Máx = até onde o Orb of Grafting preenche; Vínculos = modificadores vinculados permitidos; Qualidade = limite do Whetstone; Sockets = máximo de sockets por raridade.",
  ["Legendary powers: from Legendary, %s per item."] = "Poderes lendários: a partir de Legendary, %s por item.",
  ["A modifier rolls among the best %s tiers its item level allows, weighted (higher tiers are rarer)."] = "Um modificador rola entre os %s melhores tiers que o nível do item permite, com pesos (tiers mais altos são mais raros).",
  ["A drop's item level follows the monster's level along the curve below (straight lines in between), then: Normal +%s, Magic +%s, Rare +%s, Legendary +%s, Boss +%s; inside a rift +%s per rift tier (at most +%s); an Omen arena +%s more; at most %s."] = "O nível de item de um drop segue o nível do monstro pela curva abaixo (retas entre os pontos), depois: Normal +%s, Magic +%s, Rare +%s, Legendary +%s, Boss +%s; dentro de um rift +%s por tier do rift (no máximo +%s); uma arena de Omen +%s a mais; no máximo %s.",
  ["Fixed: world boss drops and rewards %s, store gear %s, the tutorial's gear %s."] = "Fixo: drops e recompensas de world boss %s, equipamentos da loja %s, equipamentos do tutorial %s.",
  ["Orbs keep the item level."] = "Orbes mantêm o nível do item.",
  ["Prefixes: damage and defence (skills, critical hits, weapon elements, block, dodge, reflect, thorns, penetration, ailments...)."] = "Prefixos: dano e defesa (skills, golpes críticos, elementos da arma, bloqueio, esquiva, reflexo, thorns, penetração, efeitos...).",
  ["Suffixes: utility, resistances and speed (absorbs, leech, attack and movement speed, life and mana on kill or hit, find, experience...)."] = "Sufixos: utilidade, resistências e velocidade (absorções, roubo, velocidade de ataque e de movimento, vida e mana por abate ou golpe, find, experiência...).",
  ["A new item is rolled until its count or both sides are full; the Orb of Grafting only adds on a side that is open. An Orb of Ruin can give one extra slot on one side."] = "Um item novo é rolado até completar a quantidade ou os dois lados ficarem cheios; o Orb of Grafting só adiciona num lado que esteja livre. Um Orb of Ruin pode dar um espaço extra em um lado.",
  ["Every boss you help slay (damage, last hit, or a party member within range), every sealed rift, dungeon clear, Ember Descent run and invasion reward gives Conquest Tokens. Each source has a daily limit; the window's Progress tab shows today's tokens."] = "Todo chefe que você ajuda a abater (dano, último golpe ou membro do grupo ao alcance), todo rift selado, dungeon concluída, run da Ember Descent e recompensa de invasão dá Conquest Tokens. Cada fonte tem um limite diário; a aba Progress da janela mostra os tokens de hoje.",
  ["Iselde Varrow in the teleport room's market, or Economy > Conquest Vendor, from a protection zone. Any unique or set piece is for sale once it dropped for you, once you slew a monster that drops it, or when its level is at most your level + %s. A bought item is made like a drop. Grasp of the Pyre Saint is always on sale."] = "Iselde Varrow no mercado da sala de teleporte, ou Economy > Conquest Vendor, a partir de uma zona de proteção. Qualquer unique ou peça de set fica à venda depois que caiu para você, depois que você matou um monstro que a solta, ou quando o nível dela é no máximo o seu nível + %s. Um item comprado é feito como um drop. Grasp of the Pyre Saint está sempre à venda.",
  ["The Cinderheart chain: an Omen Key of the kind you choose (%s), your Omen Key attuned to another kind (%s), an Ascended Shard of the kind you choose (%s); %s shards or %s relics of one kind become one of another."] = "A cadeia do Cinderheart: uma Omen Key do tipo que você escolher (%s), sua Omen Key sintonizada para outro tipo (%s), um Ascended Shard do tipo que você escolher (%s); %s shards ou %s relíquias de um tipo viram um de outro.",
  ["Refinement: a worn item with a rarity rises one rarity (up to Legendary), keeps every modifier and gains one; %s + %s x the new rarity tokens."] = "Refinamento: um item equipado com raridade sobe uma raridade (até Legendary), mantém todos os modificadores e ganha um; %s + %s x os tokens da nova raridade.",
  ["Salvage: a unique on the bench gives %s%% of its price in tokens (at least %s)."] = "Salvage: um unique na bancada dá %s%% do preço dele em tokens (no mínimo %s).",
  ["Each miss of a roll raises your next chance of that group; a drop starts the count again. Perfect rolls and the top rarities stay luck."] = "Cada falha numa rolagem aumenta sua próxima chance daquele grupo; um drop reinicia a contagem. Rolagens perfeitas e as raridades mais altas continuam sendo sorte.",
  ["Each Whetstone adds %s%% quality, up to %s%% (%s%% from Divine). Every modifier value is multiplied by (%s + quality) / %s, rounded."] = "Cada Whetstone soma %s%% de qualidade, até %s%% (%s%% a partir de Divine). O valor de cada modificador é multiplicado por (%s + qualidade) / %s, arredondado.",
  ["A bound modifier is left alone by Tempering, Unmaking, Excision, Reforging and Upheaval. Only an Orb of Erasure frees it (and wipes the item). An item with a bound modifier refuses the Orb of Fate."] = "Um modificador vinculado é ignorado por Tempering, Unmaking, Excision, Reforging e Upheaval. Só um Orb of Erasure o liberta (e apaga o item). Um item com modificador vinculado recusa o Orb of Fate.",
  ["The Void Orb corrupts a Rare or better item for good: no orb changes it afterwards, and the tooltip shows Corrupted. Then: %s%% nothing else happens, %s%% a modifier rises one tier, %s%% a corrupted implicit modifier, %s%% quality %s%%, %s%% one more socket (up to %s), %s%% every modifier rolls again, %s%% one rarity up (up to Divine), %s%% a modifier falls %s tiers. A locked or store item is refused."] = "O Void Orb corrompe um item Rare ou melhor para sempre: nenhum orbe o muda depois, e a dica mostra Corrompido. Então: %s%% de nada mais acontecer, %s%% de um modificador subir um tier, %s%% de um modificador implícito corrompido, %s%% de qualidade %s%%, %s%% de mais um socket (até %s), %s%% de todos os modificadores rolarem de novo, %s%% de subir uma raridade (até Divine), %s%% de um modificador cair %s tiers. Um item trancado ou da loja é recusado.",
  ["The Orb of Ruin: %s%% the item improves (%s%% of those one tier more on every unbound modifier, else an extra modifier above the side limit, once per item), %s%% nothing happens. It never ruins an item (items ruined before stay ruined). For a sure step up, the Conquest vendor's refinement raises a worn item one rarity (up to Legendary), keeps its modifiers and adds one."] = "O Orb of Ruin: %s%% de o item melhorar (%s%% desses com um tier a mais em cada modificador sem vínculo, senão um modificador extra acima do limite do lado, uma vez por item), %s%% de nada acontecer. Nunca arruína um item (itens arruinados antes continuam arruinados). Para um avanço garantido, o refinamento do vendedor Conquest sobe um item equipado uma raridade (até Legendary), mantém os modificadores e adiciona um.",
  ["Hunting monsters have much less health and come in bigger packs. Pull a group and kill it together: area spells and cleaves matter."] = "Monstros de caça têm muito menos vida e vêm em packs maiores. Puxe um grupo e mate todos juntos: magias de área e golpes em arco importam.",
  ["Experience and loot per kill are lower by the same share, so experience and gold per hour stay where they were. Kill counts (bounties, bestiary, tasks, achievements) need more kills by the same share."] = "Experiência e loot por abate são menores na mesma proporção, então experiência e ouro por hora ficam onde estavam. Contagens de abates (recompensas, bestiário, tarefas, conquistas) pedem mais abates na mesma proporção.",
  ["Multikill: kills each within %s s of the one before form a chain; the whole chain's experience gets %s kills +%s%%, %s kills +%s%%, %s kills +%s%%, %s kills +%s%%."] = "Multikill: abates com até %s s do anterior formam uma cadeia; a experiência de toda a cadeia ganha %s abates +%s%%, %s abates +%s%%, %s abates +%s%%, %s abates +%s%%.",
  ["Bosses, rifts, the Ember Descent, the tower, invasions, arena, battleground and PvP are not changed."] = "Chefes, rifts, a Ember Descent, a torre, invasões, arena, battleground e PvP não mudam.",
  ["Health, experience per kill, loot per kill and the monster's damage to you, in percent of the monster's own numbers. Monsters with a level of their own (late game, generated areas and dungeons) use the second set, on top of the health and experience their level already gives them."] = "Vida, experiência por abate, loot por abate e dano do monstro em você, em porcentagem dos números do próprio monstro. Monstros com nível próprio (fim de jogo, áreas geradas e dungeons) usam o segundo conjunto, além da vida e da experiência que o nível deles já dá.",
  ["A direct hit on a hunting monster, yours or your summon's, also deals a share of it to monsters within %s sqm of it (never bosses, players or their summons), so every class kills packs. The share goes from the first number at level %s and below to the second at level %s and above."] = "Um golpe direto num monstro de caça, seu ou do seu summon, também causa uma parte dele nos monstros num raio de %s sqm (nunca chefes, jogadores ou summons deles), então toda classe mata packs. A parte vai do primeiro número no nível %s ou menos ao segundo no nível %s ou mais.",
  ["The world bosses, the island bosses and the random raid bosses each have a pocket: a private arena with that boss, opened any time with the Pocket button of the Boss Spawns window, alone or with your party."] = "Os world bosses, os chefes das ilhas e os chefes de raid aleatórios têm cada um um bolso: uma arena privada com aquele chefe, aberta a qualquer hora pelo botão Pocket da janela Boss Spawns, sozinho ou com seu grupo.",
  ["Every character has %s charges a day per boss (new ones at %s:%s); every party member spends one. Bonus charges stay over the reset (at most %s held, %s added a day)."] = "Todo personagem tem %s cargas por dia por chefe (novas às %s:%s); cada membro do grupo gasta uma. Cargas bônus permanecem após a renovação (no máximo %s guardadas, %s adicionadas por dia).",
  ["The boss is scaled to the party. It pays less than the scheduled fight: experience and loot are cut (even the always-dropped items are not sure), and world bosses give a smaller share of their event reward with one roll of their set."] = "O chefe é ajustado ao grupo. Ele paga menos que a luta agendada: experiência e loot são cortados (nem os itens sempre dropados são garantidos), e world bosses dão uma parte menor da recompensa de evento com uma rolagem do set deles.",
  ["The boss passive point counts for a pocket kill as for any other kill: no one is locked out by the clock."] = "O ponto passivo de chefe conta para um abate no pocket como para qualquer outro: ninguém fica de fora pelo relógio.",
  ["A lethal hit carries you out without dying; the charge stays spent. After a boss's event rewarded you, its pocket waits %s minutes."] = "Um golpe letal tira você de lá sem morrer; a carga continua gasta. Depois que o evento de um chefe recompensa você, o pocket dele espera %s minutos.",
  ["Island and raid bosses spawned in the world: every helper whose damage and healing reach %s%% of the boss's health gets a personal loot roll, not only the corpse owner."] = "Chefes de ilha e de raid surgidos no mundo: todo ajudante cujo dano e cura alcancem %s%% da vida do chefe ganha uma rolagem de loot pessoal, não só o dono do cadáver.",
  ["An item with a rarity also gets a small bonus to its attack, defence, armour and hit chance, once: min + item level x (max - min + %s) / %s."] = "Um item com raridade também ganha um pequeno bônus de ataque, defesa, armadura e chance de acerto, uma vez: mín. + nível do item x (máx. - mín. + %s) / %s.",
  -- Descent (descentmath.lua)
  ["Stack %d of %d"] = "Pilha %d de %d",
  ["Held %d of %d"] = "Com você: %d de %d",
  ["Not needed"] = "Desnecessário",
  ["The Descent is conquered!"] = "A Descent foi conquistada!",
  ["You fell in the Descent."] = "Você caiu na Descent.",
  ["The embers burned out."] = "As brasas se apagaram.",
  ["You left the Descent."] = "Você saiu da Descent.",
  ["The Descent closed for a restart."] = "A Descent fechou para uma reinicialização.",
  ["Depth %d of %d"] = "Profundidade %d de %d",
  ["(weekly)"] = "(semanal)",
  ["Unique: "] = "Único: ",
  -- Market (marketview.lua, market.lua)
  ["Shields"] = "Escudos",
  ["Helmets"] = "Elmos",
  ["Armors"] = "Armaduras",
  ["Other gear"] = "Outros equipamentos",
  ["Rift keys"] = "Rift Keys",
  ["Newest"] = "Mais recentes",
  ["Price: low to high"] = "Preço: do menor ao maior",
  ["Price: high to low"] = "Preço: do maior ao menor",
  ["Ending soon"] = "Terminam em breve",
  ["Best price"] = "Melhor preço",
  ["All items"] = "Todos os itens",
  ["Any rarity"] = "Qualquer raridade",
  ["Any price"] = "Qualquer preço",
  ["Any currency"] = "Qualquer moeda",
